        hull = next((h for h, (x0, x1, z0, z1) in zip(HULLS, HULL_BOXES)
                     if xz[0][0] < x1 and xz[2][0] > x0 and xz[0][1] < z1 and xz[2][1] > z0 and not convex_apart(xz, h)), None)
