# under the water: pebbles, fish, reeds, lily pads and a sunken rowing boat
FISH_BODY = [(-0.8, -0.02, 0.012, 0.01), (-0.77, -0.02, 0.08, 0.06), (-0.7, -0.012, 0.15, 0.1), (-0.6, -0.004, 0.22, 0.13),
             (-0.52, 0.0, 0.265, 0.15), (-0.5, 0.0, 0.275, 0.155), (-0.47, 0.003, 0.29, 0.16), (-0.35, 0.01, 0.35, 0.18),
             (-0.2, 0.02, 0.39, 0.2), (0.0, 0.02, 0.38, 0.19), (0.2, 0.02, 0.32, 0.16), (0.4, 0.01, 0.23, 0.12),
             (0.55, 0.0, 0.15, 0.08), (0.68, 0.0, 0.1, 0.05), (0.74, 0.0, 0.11, 0.04)]   # (x, y of the middle, half-height,
                                                                                           # half-width), the snout at -x


def fish_section(x):
    """The fish's body at ``x``: (y of its middle, half-height, half-width)."""
    i = next((j for j in range(len(FISH_BODY) - 2) if x <= FISH_BODY[j + 1][0]), len(FISH_BODY) - 2)
    r0, r1 = FISH_BODY[i], FISH_BODY[i + 1]
    t = max(0.0, min(1.0, (x - r0[0]) / (r1[0] - r0[0])))
    return [r0[j] + (r1[j] - r0[j]) * t for j in (1, 2, 3)]


def fish_pt(x, a, off=0.0):
    """A point of the fish's skin at ``x`` and angle ``a`` round it (0: the
    back, pi/2: its right side (+z)), ``off`` out from it."""
    yc, hh, hw = fish_section(x)
    c, s = add.cos(a), add.sin(a)
    k = 2.4                                                                      # (a little full at the shoulders)
    r = (abs(c) ** k + abs(s) ** k) ** (-1.0 / k)
    y, z = hh * c * r, hw * s * r
    g = vunit([0, c / hh, s / hw])
    return [x, yc + y + g[1] * off, z + g[2] * off]


def fin_plate(outline, z, t, colour):
    """A fin: the flat outline (x, y) given a thickness ``t`` about ``z``,
    its faces fanned from the outline's middle (the outlines are drawn so
    that it sees all of them)."""
    n = len(outline)
    cx, cy = sum(p[0] for p in outline) / n, sum(p[1] for p in outline) / n
    M = add.Mesh()
    for sz in (-1, 1):
        for x, y in outline:
            M.add_vertex([x, y, z + sz * t / 2])
        M.add_vertex([cx, cy, z + sz * t / 2])
    for i in range(n):
        j = (i + 1) % n
        M.add_face([i, j, n], colour)                                             # (one face,
        M.add_face([n + 1 + j, n + 1 + i, 2 * n + 1], colour)                     # the other,
        M.add_face([i, n + 1 + i, n + 1 + j, j], colour)                          # the edge)
    return add.fix_normals(M)


def fish(at, facing, color, size=1.0, lying=False):
    """A fish, its snout towards -x (turned by ``facing``), ``size`` times a
    fish 2.1 long: a body lofted through its sections -- the pointed snout
    with the mouth, the head with the gill cover's edge, the deep flank, the
    slender tail stock -- the back in its colour over a pale belly; eyes
    with a dark pupil; a forked tail of two lobes, a dorsal fin along the
    back and an anal fin under the tail stock, pectoral fins behind the
    gills and pelvic fins under the belly, all thin and flat.  Baked (the
    colour of bread), it is golden brown over a paler belly, its fins
    browned and its eyes gone white.  ``lying`` on its side (on a dish, in
    a basket): without the paired fins, pressed flat to it."""
    baked = color is P["bread"]
    belly = P["straw"] if baked else P["cheese"] if color is P["gold"] else P["steel"] if color in (P["blue"], P["slate"]) else P["white"]
    fin_c = P["wood_light"] if baked else color
    iris = P["white"] if baked else P["gold"]
    add.push()
    K = 18
    xs_ = [q[0] for q in FISH_BODY]
    rings = [[fish_pt(x, 2 * add.pi * (j + 0.5) / K) for j in range(K)] for x in xs_]
    M = add.make(add.loft, rings, color)
    for i, f in enumerate(M.F):                                                  # its colours: the back, the belly, the
        c = [sum(M.V[j][k] for j in f) / len(f) for k in range(3)]               # gill cover's edge and the mouth
        yc, hh, hw = fish_section(c[0])
        if -0.5 < c[0] < -0.47:
            M.C[i] = add.rgb(P["black"] if not baked else P["meat"])
        elif c[0] < -0.77 and abs(c[1] - yc) < 0.03:
            M.C[i] = add.rgb(P["black"])
        elif c[1] < yc - 0.1 * hh:
            M.C[i] = add.rgb(belly)
    add.mesh(M)
    for s in (-1, 1):                                                            # the eyes
        e = fish_pt(-0.62, s * 1.15)
        add.sphere(e, 0.05, 6, iris)
        add.sphere(fish_pt(-0.62, s * 1.15, 0.045), 0.024, 4, P["black"])
    add.mesh(fin_plate([(0.741, 0.0), (0.741, 0.1), (1.0, 0.27), (1.3, 0.45), (1.27, 0.2), (1.13, 0.0)], 0.0, 0.02, fin_c))   # the tail,
    add.mesh(fin_plate([(0.741, 0.0), (1.13, 0.0), (1.27, -0.2), (1.3, -0.45), (1.0, -0.27), (0.741, -0.1)], 0.0, 0.02, fin_c))   # two
                                                                                                                                    # lobes
    back = [(x, fish_section(x)[0] + fish_section(x)[1] + 0.004) for x in (0.22, 0.2, 0.1, 0.0, -0.1, -0.2, -0.22)]   # (by the
                                                                                                                      # rings)
    add.mesh(fin_plate(back + [(-0.16, back[-1][1] + 0.12), (0.0, back[-1][1] + 0.14), (0.18, back[0][1] + 0.1)], 0.0, 0.016, fin_c))
    under = [(x, fish_section(x)[0] - fish_section(x)[1] - 0.003) for x in (0.32, 0.4, 0.48, 0.55)]
    add.mesh(fin_plate(under + [(0.58, under[-1][1] - 0.05), (0.42, under[1][1] - 0.13), (0.34, under[0][1] - 0.1)], 0.0, 0.014,
                       fin_c))                                                    # the anal fin
    for s in (() if lying else (-1, 1)):                                         # the pectoral fins, behind the gills,
        for x0, a0, L_, W_, tilt in ((-0.42, 1.95, 0.2, 0.09, 0.5), (0.02, 2.55, 0.16, 0.07, 0.25)):   # and the pelvic
            root = fish_pt(x0, s * a0, 0.006)                                    # fins under the belly: out from the
            pl = fin_plate([(0.0, 0.0), (0.05, 0.0), (L_ * 1.05, W_ * 0.3), (L_, W_), (0.06, W_ * 0.7), (0.01, W_ * 0.3)], 0.0,
                           0.012, fin_c)                                         # skin, back along it and down
            pl = add.rotateY(add.rotateX(pl, s * (add.pi / 2 + tilt)), -s * 0.35)
            add.mesh(add.move(pl, root))
    M = add.pop()
    add.mesh(add.move(add.rotateY(add.stretch(M, [size, size, size], (0, 0, 0)), facing), at))


STONES = [shade_of("stone_dark", 0), shade_of("stone_dark", 1), shade_of("stone_dark", 2), shade_of("stone", 0), shade_of("stone", 1),
          shade_of("stone", 2), P["rock"], P["granite"]]      # the cobbles' colours: greys, a few pinkish
COBBLE_DOME = ((1.0, -0.02), (1.0, 0.03), (0.93, 0.065), (0.78, 0.095), (0.5, 0.115))   # a cobble's rings: how far out, how high


def cobble_pack(sample, area, inside, y, seed=0, radii=(0.2, 0.15, 0.11, 0.08), gap=0.015, colours=None, more=(), edge=(), cut=None,
                laid=None):
    """Cobbles set close, as a paver sets them: stones of several sizes
    thrown down at random over an ``area`` (square metres) -- ``sample(s,
    t)`` turns two numbers in 0..1 into a point (x, z) of it -- the biggest
    first, each kept only where it clears the others and lies wholly
    ``inside(x, z)``, then smaller and smaller ones into the gaps left.
    (``more``: further (sample, area) pairs, ground thrown at again after
    it at each size, its stones numbered on from its, so that the rest is
    laid as it would be without them -- and last, at that ground only,
    stones smaller still, of the radii ``edge``, into the gaps left along
    what the paving is laid up to.)  Then every stone takes the ground
    that is nearer to it than to any other (the bigger the stone, the
    farther its share reaches), but not more than half again farther out
    than it is round -- ``cut(x, z, share)`` trims it to the ground it may
    take, cut straight along masonry it is set against (see kerb_cut) --
    nor over the edge, less a joint all round: so they fill the ground,
    each a worn dome of its own irregular shape, of one of the ``colours``,
    its foot at ``y`` (a height, or a function of (x, z)).  Returns how many.
    (``laid``: a test of (x, z) and a list -- the stones whose middles pass
    it go into the list too, to stand something on them: see lift_onto.)"""
    colours = colours or STONES
    cell = 0.5                                         # (as big as the biggest stone and its joint: 2 * 0.2 * 1.12 + gap)
    assert cell >= 2 * radii[0] * 1.12 + gap
    grid, stones = {}, []
    for k, r0 in enumerate(tuple(radii) + tuple(edge)):
        a0 = 0
        for sample_, area_ in ((sample, area if k < len(radii) else 0.0),) + tuple(more):
            m = int(2.6 * area_ / (3.2 * r0 * r0))
            for a in range(a0, a0 + m):
                x, z = sample_(hash2(a, k, seed), hash2(a, k, seed + 1))
                r = r0 * (0.88 + 0.24 * hash2(a, k, seed + 2))
                ci, cj = int(add.floor(x / cell)), int(add.floor(z / cell))
                if any((x - px) ** 2 + (z - pz) ** 2 < (r + pr + gap) ** 2
                       for di in (-1, 0, 1) for dj in (-1, 0, 1) for px, pz, pr in grid.get((ci + di, cj + dj), ())):
                    continue
                if not (inside(x, z) and inside(x + r, z) and inside(x - r, z) and inside(x, z + r) and inside(x, z - r)):
                    continue
                grid.setdefault((ci, cj), []).append((x, z, r))
                stones.append((x, z, r, a, k))
            a0 += m
    for x, z, r, a, k in stones:
        if hash2(a, k, seed + 3) > max(DENSITY, 0.35):
            continue
        ph = hash2(a, k, seed + 7) * 6.28
        ci, cj = int(add.floor(x / cell)), int(add.floor(z / cell))
        near = [q for di in (-2, -1, 0, 1, 2) for dj in (-2, -1, 0, 1, 2) for q in grid.get((ci + di, cj + dj), ()) if q[:2] != (x, z)]
        for reach in (1.6, 1.0):                                                # (just itself, if its share will not
            poly = [(x + reach * r * add.cos(ph + j * add.pi / 5), z + reach * r * add.sin(ph + j * add.pi / 5)) for j in range(10)]
            for px, pz, pr in near:                                             # keep off the edge)
                if len(poly) > 2:                                               # its share: nearer to it than to that one
                    poly = clip_half(poly, 2 * (px - x), 2 * (pz - z), px * px + pz * pz - x * x - z * z - pr * pr + r * r)
            if cut is not None and len(poly) > 2:
                poly = cut(x, z, poly)
            f = 1.0
            while f > 0.64 and not all(inside(x + (qx - x) * f, z + (qz - z) * f) for qx, qz in poly):
                f -= 0.04                                                       # (drawn in from the edge)
            poly = [(x + (qx - x) * f, z + (qz - z) * f) for qx, qz in poly]
            if all(inside(qx, qz) for qx, qz in poly):
                break
        stone = shrunk(poly, gap / 2) if len(poly) > 2 else None
        if not stone:
            continue
        yy = y(x, z) if callable(y) else y
        hs = r / 0.2 * (0.75 + 0.45 * hash2(a, k, seed + 5))
        M, n = add.Mesh(), len(stone)
        for f_, h_ in COBBLE_DOME:
            for qx, qz in stone:
                M.add_vertex([x + (qx - x) * f_, yy + h_ * hs, z + (qz - z) * f_])
        top = M.add_vertex([x, yy + 0.122 * hs, z])
        M.add_face(list(range(n)), None)                                          # its foot,
        for ring in range(len(COBBLE_DOME) - 1):                                  # its sides and its worn dome
            for j in range(n):
                lo0, lo1 = ring * n + j, ring * n + (j + 1) % n
                M.add_face([lo0, lo0 + n, lo1 + n, lo1], None)
        for j in range(n):
            M.add_face([top, (len(COBBLE_DOME) - 1) * n + (j + 1) % n, (len(COBBLE_DOME) - 1) * n + j], None)
        cobble = add.color(M, colours[int(hash2(a, k, seed + 6) * len(colours)) % len(colours)])
        add.mesh(cobble)
        if laid is not None and laid[0](x, z):
            laid[1].append(cobble)
    return len(stones)


def height_over(t, x, z):
    """How high the triangle ``t`` (three points, and the box round them in
    XZ) is over (x, z) -- or None, if (x, z) is not under it (or it stands
    on edge)."""
    a, b, c, x0, x1, z0, z1 = t
    if x < x0 or x > x1 or z < z0 or z > z1:
        return None
    d = (b[0] - a[0]) * (c[2] - a[2]) - (c[0] - a[0]) * (b[2] - a[2])
    if abs(d) < 1e-12:
        return None
    u = ((x - a[0]) * (c[2] - a[2]) - (c[0] - a[0]) * (z - a[2])) / d
    v = ((b[0] - a[0]) * (z - a[2]) - (x - a[0]) * (b[2] - a[2])) / d
    if u < -1e-9 or v < -1e-9 or u + v > 1.0 + 1e-9:
        return None
    return a[1] + u * (b[1] - a[1]) + v * (c[1] - a[1])


def boxed_triangles(M, f, out):
    """The face ``f`` of ``M`` as a fan of triangles, each with the box round
    it in XZ (see height_over), onto ``out``."""
    for j in range(1, len(f) - 1):
        a, b, c = M.V[f[0]], M.V[f[j]], M.V[f[j + 1]]
        out.append((a, b, c, min(a[0], b[0], c[0]), max(a[0], b[0], c[0]), min(a[2], b[2], c[2]), max(a[2], b[2], c[2])))


def lift_onto(K, under, reach=0.1, margin=0.002):
    """How far to raise the figure ``K``, stood a little low on the meshes
    ``under`` (cobbles: see cobble_pack's ``laid``), for it to stand on
    them: its underside clear of their tops -- their surface under each
    point of K within ``reach`` of its lowest, and K's over each point of
    theirs, the most either way -- and a hair (``margin``) more.  So it
    rests on the highest stones under its feet, as one does."""
    lo = min(v[1] for v in K.V)
    kt, ut = [], []
    for f in K.F:                                                           # the figure's triangles near its foot,
        if min(K.V[i][1] for i in f) < lo + reach:
            boxed_triangles(K, f, kt)
    for M in under:                                                         # and all of theirs
        for f in M.F:
            boxed_triangles(M, f, ut)
    lift = 0.0
    for t in kt:                                                            # each point of the figure's over their
        for p in (t[0], t[1], t[2]):                                        # triangles, and each of theirs under
            for s in ut:                                                    # its
                h = height_over(s, p[0], p[2])
                if h is not None and h - p[1] > lift:
                    lift = h - p[1]
    for s in ut:
        for p in (s[0], s[1], s[2]):
            for t in kt:
                h = height_over(t, p[0], p[2])
                if h is not None and p[1] - h > lift:
                    lift = p[1] - h
    return lift + margin


def convex_in(poly, x, z, margin=0.0):
    """Is (x, z) inside the convex anticlockwise polygon ``poly`` (a list of
    (x, z)), or no farther than ``margin`` outside any of its edges?"""
    n = len(poly)
    for i in range(n):
        (ax, az), (bx, bz) = poly[i], poly[(i + 1) % n]
        ex, ez = bx - ax, bz - az
        if ex * (z - az) - ez * (x - ax) < -margin * add.sqrt(ex * ex + ez * ez):
            return False
    return True


def seg_cross(p, q, a, b):
    """Where the segment p-q meets the segment a-b, as a fraction along p-q (None if they do not)."""
    rx, rz, sx, sz = q[0] - p[0], q[1] - p[1], b[0] - a[0], b[1] - a[1]
    d = rx * sz - rz * sx
    if abs(d) < 1e-12:
        return None
    t = ((a[0] - p[0]) * sz - (a[1] - p[1]) * sx) / d
    u = ((a[0] - p[0]) * rz - (a[1] - p[1]) * rx) / d
    return t if -1e-9 <= t <= 1 + 1e-9 and -1e-9 <= u <= 1 + 1e-9 else None


def seg_in(p, q, poly):
    """Does more than a point of the segment p-q lie inside the convex
    anticlockwise polygon ``poly``?"""
    t0, t1 = 0.0, 1.0
    for i in range(len(poly)):
        (ax, az), (bx, bz) = poly[i], poly[(i + 1) % len(poly)]
        f0 = (bx - ax) * (p[1] - az) - (bz - az) * (p[0] - ax)                # (> 0: inside of this edge)
        f1 = (bx - ax) * (q[1] - az) - (bz - az) * (q[0] - ax)
        if f0 < 0 and f1 < 0:
            return False
        if f0 < 0:
            t0 = max(t0, f0 / (f0 - f1))
        elif f1 < 0:
            t1 = min(t1, f0 / (f0 - f1))
    return (t1 - t0) * add.sqrt((q[0] - p[0]) ** 2 + (q[1] - p[1]) ** 2) > 1e-6


def ground_outline(pieces, cuts, keep):
    """The edge of the ground made of the convex ``pieces`` (their union),
    inside every one of the convex ``keep`` and outside every one of the
    convex ``cuts``: every edge of them all, split where it crosses another,
    and each bit kept that has that ground on one side and not on the other
    -- turned to have it on its left.  Returns the bits ((x, z), (x, z))."""
    def inside(x, z):
        return (all(convex_in(k, x, z) for k in keep) and not any(convex_in(c, x, z) for c in cuts)
                and any(convex_in(q, x, z) for q in pieces))
    x0, x1 = min(p[0] for q in pieces for p in q) - 1, max(p[0] for q in pieces for p in q) + 1
    z0, z1 = min(p[1] for q in pieces for p in q) - 1, max(p[1] for q in pieces for p in q) + 1
    edges = [(q[i], q[(i + 1) % len(q)]) for q in pieces + cuts + keep for i in range(len(q))]
    edges = [e for e in edges if max(e[0][0], e[1][0]) > x0 and min(e[0][0], e[1][0]) < x1
             and max(e[0][1], e[1][1]) > z0 and min(e[0][1], e[1][1]) < z1]
    box = [(min(a[0], b[0]), max(a[0], b[0]), min(a[1], b[1]), max(a[1], b[1])) for a, b in edges]
    out, seen = [], set()
    for i, (a, b) in enumerate(edges):
        ts = [0.0, 1.0]
        for j, (c, d) in enumerate(edges):
            if j != i and box[j][0] <= box[i][1] and box[i][0] <= box[j][1] and box[j][2] <= box[i][3] and box[i][2] <= box[j][3]:
                t = seg_cross(a, b, c, d)
                if t is not None:
                    ts.append(min(1.0, max(0.0, t)))
        ts.sort()
        L = add.sqrt((b[0] - a[0]) ** 2 + (b[1] - a[1]) ** 2)
        nx, nz = -(b[1] - a[1]) / L * 1e-6, (b[0] - a[0]) / L * 1e-6                  # (a hair to its left)
        for t0, t1 in zip(ts, ts[1:]):
            if (t1 - t0) * L < 1e-7:
                continue
            p = (a[0] + (b[0] - a[0]) * t0, a[1] + (b[1] - a[1]) * t0)
            q = (a[0] + (b[0] - a[0]) * t1, a[1] + (b[1] - a[1]) * t1)
            mx, mz = (p[0] + q[0]) / 2, (p[1] + q[1]) / 2
            left, right = inside(mx + nx, mz + nz), inside(mx - nx, mz - nz)
            if left != right:
                bit = (p, q) if left else (q, p)
                key = tuple(round(v, 5) for v in bit[0] + bit[1])
                if key not in seen:
                    seen.add(key)
                    out.append(bit)
    return out


def flag_paths(pieces, cuts=(), keep=(), y=None, top=None, gap=GAP, low=None, seed=0):
    """Paths of split flagstones of all shapes and sizes, laid close (crazy
    paving) as one piece of work over all the ground of the paths -- the
    union of the convex ``pieces``, inside the convex ``keep`` and outside
    the convex ``cuts`` (see ground_outline): points scattered over it, no
    two nearer than 0.3 to 0.7 (it changes along the way), a pair set
    either side of every inside corner of its edge (so that a joint runs
    out of the corner and no stone is cut to an L), each point the middle
    of a stone -- the ground that lies nearer to it than to any other point,
    cut off along the edge, a joint (``gap``) in all round; a stone that
    would come out a sliver (under 0.035 square metres, or thinner than 9
    cm) is left out and its neighbours take its ground instead (but a small
    piece cut off at an inside corner stays: it fills the corner).  The stones
    are bedded from ``y`` up to ``top`` -- where the yard's people, beasts
    and things stand -- each a few millimetres lower or higher than the
    next, but none higher than what stands on it; ``low(x, z, r)`` says how
    low the lowest thing over the ground within ``r`` comes (see low_over):
    a stone takes its top down to anything a little lower (a hoof set into
    the ground), and one that something sunk deeper stands in (it should
    not: the buildings are ``cuts``) is dressed smaller to come up to it.
    Returns how many stones."""
    y = G if y is None else y
    top = G + 0.05 if top is None else top
    rim = ground_outline(list(pieces), list(cuts), list(keep))

    def inside(x, z):
        return (all(convex_in(k, x, z) for k in keep) and not any(convex_in(c, x, z) for c in cuts)
                and any(convex_in(q, x, z) for q in pieces))
    rgrid = {}                                                              # the edge, by 1 m squares
    rim_at = {e: k for k, e in enumerate(rim)}                              # (and where each piece comes along it)
    for e in rim:
        for i in range(int(add.floor(min(e[0][0], e[1][0]))), int(add.floor(max(e[0][0], e[1][0]))) + 1):
            for j in range(int(add.floor(min(e[0][1], e[1][1]))), int(add.floor(max(e[0][1], e[1][1]))) + 1):
                rgrid.setdefault((i, j), []).append(e)
    starts = {}
    for e in rim:
        starts.setdefault((round(e[0][0], 4), round(e[0][1], 4)), []).append(e)
    corners = []                                                            # the inside corners: (x, z, bisector)
    for (a, b) in rim:
        for (_, c) in starts.get((round(b[0], 4), round(b[1], 4)), ()):
            d1 = ((b[0] - a[0]), (b[1] - a[1]))
            d2 = ((c[0] - b[0]), (c[1] - b[1]))
            l1, l2 = add.sqrt(d1[0] ** 2 + d1[1] ** 2), add.sqrt(d2[0] ** 2 + d2[1] ** 2)
            turn = add.atan2(d1[0] * d2[1] - d1[1] * d2[0], d1[0] * d2[0] + d1[1] * d2[1])
            if turn < -1e-4:                                                # (a right turn: the ground is on the left)
                bx, bz = -d1[1] / l1 - d2[1] / l2, d1[0] / l1 + d2[0] / l2
                bl = add.sqrt(bx * bx + bz * bz)
                corners.append((b[0], b[1], bx / bl, bz / bl, add.pi - turn))
    seeds, grid = [], {}

    def near(x, z, r):
        i, j = int(x // 0.5), int(z // 0.5)
        k = int(r // 0.5) + 1
        return [q for a in range(i - k, i + k + 1) for b in range(j - k, j + k + 1) for q in grid.get((a, b), ())
                if (x - q[0]) ** 2 + (z - q[1]) ** 2 < r * r]

    def put(x, z):
        q = (x, z, len(seeds))
        seeds.append(q)
        grid.setdefault((int(x // 0.5), int(z // 0.5)), []).append(q)
    for cx, cz, bx, bz, ang in corners:                                     # the pairs at the inside corners
        for s in (-1, 1):
            a = s * ang / 4
            x, z = cx + 0.3 * (bx * add.cos(a) - bz * add.sin(a)), cz + 0.3 * (bx * add.sin(a) + bz * add.cos(a))
            if inside(x, z) and not near(x, z, 0.24):
                put(x, z)
    for pi_, q in enumerate(pieces):                                        # then points thrown down all over it
        qx0, qx1 = min(p[0] for p in q), max(p[0] for p in q)
        qz0, qz1 = min(p[1] for p in q), max(p[1] for p in q)
        for m in range(int(abs(poly_area(q)) / 0.04)):
            x, z = qx0 + (qx1 - qx0) * hash2(pi_, m, 71 + seed), qz0 + (qz1 - qz0) * hash2(pi_, m, 72 + seed)
            if not convex_in(q, x, z) or not inside(x, z) or near(x, z, 0.3 + 0.4 * value_noise(x, z, 2.0, 73)):
                continue
            if any((x - cx) ** 2 + (z - cz) ** 2 < 0.45 ** 2 for cx, cz, _, _, _ in corners):
                continue
            put(x, z)

    def cut_to_edge(poly, depth=0):                                         # a cell cut off along the edge of the ground
        if len(poly) < 3:
            return []
        xs, zs = [p[0] for p in poly], [p[1] for p in poly]
        es = sorted({e for i in range(int(add.floor(min(xs))), int(add.floor(max(xs))) + 1)       # (the edges near it, in
                     for j in range(int(add.floor(min(zs))), int(add.floor(max(zs))) + 1) for e in rgrid.get((i, j), ())},
                    key=lambda e: rim_at[e])                                #  their order along the edge)
        for cx, cz, bx, bz, _ in corners:                                   # (an inside corner in it: split it along
            if depth < 4 and convex_in(poly, cx, cz, -1e-6):                #  the corner's bisector first)
                return [p for s in (1, -1) for p in cut_to_edge(clip_half(poly, s * bz, -s * bx, s * (bz * cx - bx * cz)), depth + 1)]
        for a, b in es:
            if seg_in(a, b, poly):                                          # (a bit of the edge crosses it)
                poly = clip_half(poly, b[1] - a[1], a[0] - b[0], (b[1] - a[1]) * a[0] + (a[0] - b[0]) * a[1])
                if len(poly) < 3:
                    return []
        return [poly]

    def cell(x, z, k, gone):
        poly = [(x - 1.2, z - 1.2), (x + 1.2, z - 1.2), (x + 1.2, z + 1.2), (x - 1.2, z + 1.2)]
        for x2, z2, k2 in near(x, z, 2.4):
            if k2 != k and k2 not in gone and len(poly) > 2:                # nearer to this point than to that one
                poly = clip_half(poly, x2 - x, z2 - z, (x2 - x) * (x + x2) / 2 + (z2 - z) * (z + z2) / 2)
        return cut_to_edge(poly) if len(poly) > 2 else []

    def sliver(p):
        A = abs(poly_area(p))
        per = sum(add.sqrt((p[i][0] - p[i - 1][0]) ** 2 + (p[i][1] - p[i - 1][1]) ** 2) for i in range(len(p)))
        return A < 0.035 or 2 * A / per < 0.045                             # (2A/perimeter: half a thin stone's width)
    gone, cells = set(), {}
    todo = [q for q in seeds]
    for sweep in range(4):                                                  # the slivers' points taken out, and
        again = set()                                                       # their neighbours' cells cut afresh
        for x, z, k in todo:
            if k in gone:
                continue
            ps = cell(x, z, k, gone)
            cells[k] = ps
            if ps and all(sliver(p) for p in ps) or not ps:
                gone.add(k)
                cells.pop(k, None)
                again.update(q[2] for q in near(x, z, 2.4) if q[2] != k)
        todo = [seeds[k] for k in sorted(again) if k not in gone]
        if not todo:
            break
    count_ = 0
    shades = (shade_of("stone_dark", 0), shade_of("stone_dark", 1), shade_of("stone_dark", 2), shade_of("stone", 0), shade_of("stone", 2))
    for k in sorted(cells):
        x, z, _ = seeds[k]
        for j, poly in enumerate(cells[k]):
            A = abs(poly_area(poly))                                        # (a bit split off at an inside corner
            if A < 0.006 or 4 * A < 0.02 * sum(add.sqrt((poly[i][0] - poly[i - 1][0]) ** 2 + (poly[i][1] - poly[i - 1][1]) ** 2)
                                                for i in range(len(poly))):   #  is kept, unless it is next to nothing)
                continue
            stone = shrunk(poly, gap / 2)
            if not stone:
                continue
            h = top - 0.008 * hash2(k, 1, 74)                               # (its own few millimetres)
            if low:
                cx_, cz_ = sum(p[0] for p in stone) / len(stone), sum(p[1] for p in stone) / len(stone)
                r_ = max(add.sqrt((p[0] - cx_) ** 2 + (p[1] - cz_) ** 2) for p in stone)
                m = low(stone, cx_, cz_, r_)
                if m < top - 0.035:                                         # (something sunk into the ground on it)
                    f = 1.0
                    while f > 0.45 and low([(cx_ + (qx - cx_) * f, cz_ + (qz - cz_) * f) for qx, qz in stone], cx_, cz_, r_ * f) < top - 0.035:
                        f -= 0.05
                    if f <= 0.45:
                        continue
                    stone = [(cx_ + (qx - cx_) * f, cz_ + (qz - cz_) * f) for qx, qz in stone]
                    m = low(stone, cx_, cz_, r_ * f)
                if m < top + 0.03:                                          # (something stands on it: flush under it)
                    h = min(top, m)
            add.mesh(solid(stone, y, h, shades[int(hash2(k, 2 + j, 74) * 5) % 5]))
            count_ += 1
    return count_


WRECK = (70.0, 82.0, 2.43)                              # the sunken boat: where it lies and which way its bow points


def lie_along(M, x, z, heading, half):
    """``M`` (built along its own x) tipped to follow the ground under it:
    along ``heading`` from (x, z), ``half`` each way."""
    c, sn = add.cos(heading), add.sin(heading)
    fall = ground(x + half * c, z - half * sn) - ground(x - half * c, z + half * sn)
    return add.rotateZ(M, add.atan2(fall, 2 * half))


def settle(M, sink=0.1):
    """``M`` lowered (or raised) onto the ground under it so that it goes
    ``sink`` into the sand at its deepest and nowhere deeper."""
    dy = max(ground(v[0], v[2]) - v[1] for v in M.V) - sink
    return add.move(M, [0, dy, 0])


def hull_point(u, s, inset=0.0, gap=0.0):
    """A point of the sunken boat's hull in its own frame (bow towards +x,
    port +z, the keel on y = 0): ``u`` from -1 (stern) to 1 (bow) along
    it, ``s`` from 0 (the keel) to 1 (the gunwale) round its side -- on
    the planking's outside, or ``inset`` in from it; negative ``s`` is the
    starboard side; ``gap`` moves the side off the middle line (the planks
    of the two sides meet on the keel, each in its own rabbet)."""
    L, B, D = 5.2, 1.7, 0.75
    side = 1.0 if s >= 0 else -1.0
    th = abs(s) * add.pi / 2
    b = B / 2 * max(0.0, 1.0 - u * u) ** 0.55                   # the half beam, pointed at stem and stern
    yk, ys = 0.08 * u * u, D + 0.2 * u * u                      # keel and sheer, rising to the ends
    z, y = b * add.sin(th), yk + (ys - yk) * (1 - add.cos(th))
    nz, ny = add.sin(th) * (ys - yk), add.cos(th) * b              # (the outward normal of the section curve)
    n = add.sqrt(nz * nz + ny * ny) or 1.0
    return [u * L / 2, y + inset * ny / n, side * (z - inset * nz / n + gap)]


def wreck_boat(seed=0):
    """A rowing boat that sank long ago, in its own frame (see hull_point):
    a keel, stem and stern posts, bent ribs, the planks (strakes) round
    them -- a stretch of three of them on the starboard side broken away,
    so that the ribs show -- the gunwales (the starboard one broken), two
    thwarts come away from the sides, one of them split, lying in the
    bottom; all of dark, waterlogged oak.  Returns the mesh."""
    add.push()
    NS, NU, T = 6, 20, 0.028                                    # strakes a side, stations along, plank thickness
    for side in (1, -1):
        for k in range(NS):
            s0, s1 = (k + 0.04) / NS, (k + 0.96) / NS
            u0, u1 = -0.95, 0.95
            spans = [(u0, u1)]
            if side < 0 and k >= 3:                             # the hole in the starboard side
                spans = [(u0, -0.18 + 0.07 * (k - 3)), (0.3 - 0.05 * (k - 3), u1)]
            for a, b in spans:
                rows = []
                for i in range(NU + 1):
                    u = a + (b - a) * i / NU
                    rows.append([hull_point(u, side * s, 0.0, 0.004) for s in (s0, s1)] + [hull_point(u, side * s, T, 0.004) for s in (s1, s0)])
                add.mesh(add.fix_normals(add.make(add.loft, rows, pick("wood_dark", k, seed + side))))
    for i in range(10):                                         # the ribs, inside the planks, keel to gunwale
        u = -0.74 + 0.1644 * i
        for side in (1, -1):
            top = 0.97 if not (side < 0 and -0.2 < u < 0.32 and i % 2) else 0.55   # (two broken off at the hole)
            pts = [hull_point(u, side * (0.03 + (top - 0.03) * j / 7), T + 0.032) for j in range(8)]
            add.polyline(pts, 0.022, 4, P["wood"])
    for sg in (1, -1):                                          # the ends: solid wood from the planks' ends to the stem
        rings = []
        for u in (0.9505, 0.965, 0.98, 0.99, 1.0):
            rings.append([hull_point(sg * u, (1 - j / 6), 0.0) for j in range(7)] + [hull_point(sg * u, -j / 6, 0.0) for j in range(1, 7)])
        add.mesh(add.fix_normals(add.make(add.loft, rings if sg > 0 else rings[::-1], P["wood_dark"])))
    keel = [hull_point(-0.98 + 1.96 * i / 16, 0.0, -0.045) for i in range(17)]
    add.polyline(keel, 0.042, 6, P["wood_dark"])                # the keel under it all
    for sg in (1, -1):                                          # stem and stern post, the planks' ends on them
        x = sg * (2.6 + 0.045)
        add.polyline([[x, -0.07, 0.0], [x, 0.5, 0.0], [x, 1.05, 0.0]], 0.036, 6, P["wood_dark"])
    for side in (1, -1):                                        # the gunwales on the top strakes
        spans = [(-0.9, 0.9)] if side > 0 else [(-0.9, -0.22), (0.36, 0.9)]
        for a, b in spans:
            add.polyline([hull_point(a + (b - a) * i / 48, side * 1.0, -0.038, 0.004) for i in range(49)], 0.035, 5, P["wood_dark"])
    down = [0.0, -add.cos(0.55), add.sin(0.55)]                 # the thwarts, come away from the sides long ago -- one
    dot = lambda p, q: p[0] * q[0] + p[1] * q[1] + p[2] * q[2]  # whole, one split, half of it gone -- lying in the
    ribs = []                                                   # bottom of the hull as it lies heeled over (see below),
    for i in range(10):                                         # along it, on the ribs of its port side (the straight
        rib = [hull_point(-0.74 + 0.1644 * i, 0.03 + 0.94 * j / 7, T + 0.032) for j in range(8)]   # runs of their tubes)
        ribs += [[rib[j][k] + (rib[j + 1][k] - rib[j][k]) * f / 8.0 for k in range(3)] for j in range(7) for f in range(9)]
    for xc, L in ((-0.8, 1.3), (0.6, 0.8)):                     # where the hull is lowest (down: as ``down`` points)
        ends = []
        for x in (xc - L / 2, xc + L / 2, xc):
            s = max([j / 100 for j in range(101)], key=lambda s, x=x: dot(hull_point(x / 2.6, s, T + 0.054), down))
            ends.append((x, s))
        p0, p1 = [hull_point(x / 2.6, s, T + 0.054) for x, s in ends[:2]]
        a = vunit(vsub(p1, p0))
        mid = [(p0[k] + p1[k]) / 2 for k in range(3)]
        n = vsub(hull_point(xc / 2.6, ends[2][1], T + 0.1), hull_point(xc / 2.6, ends[2][1], T))   # (into the hull, square
        n = vunit([n[k] - a[k] * dot(n, a) for k in range(3)])                                       # to the plank's length)
        w = vcross(n, a)
        rest = max([dot(vsub(q, mid), n) + 0.025 for q in ribs                    # (on the highest rib under it, a hair
                    if abs(dot(vsub(q, mid), a)) < L / 2 + 0.025 and abs(dot(vsub(q, mid), w)) < 0.12 + 0.025])   # off)
        c = [mid[k] + n[k] * (rest + 0.002 + 0.02) for k in range(3)]
        z_ = vcross(a, n)
        add.mesh(add.transform(add.make(add.cuboid, [0, 0, 0], [L, 0.04, 0.24], P["wood"]),
                               [[a[0], n[0], z_[0], c[0]], [a[1], n[1], z_[1], c[1]], [a[2], n[2], z_[2], c[2]]]))
    return add.pop()


def sea_chest(open_=0.9, seed=0):
    """A sea chest, in its own frame (on the origin, its front towards +z):
    sides of boards with iron straps at the corners and round it, rope
    handles at the ends, a hasp and lock, a lid of boards on two hinges
    thrown open ``open_`` radians -- and full of gold coins, heaped up to
    the brim: three layers of them lying on a mound, one over another,
    none in another."""
    add.push()
    W, Dp, H = 0.9, 0.52, 0.42
    for k in range(3):                                           # the sides of boards
        y0, y1 = 0.02 + k * (H - 0.02) / 3 + 0.003, 0.02 + (k + 1) * (H - 0.02) / 3 - 0.003
        for sz in (-1, 1):
            add.cuboid([0, (y0 + y1) / 2, sz * (Dp / 2 - 0.015)], [W - 0.06, y1 - y0, 0.03], pick("wood", k, seed + sz))
        for sx in (-1, 1):
            add.cuboid([sx * (W / 2 - 0.015), (y0 + y1) / 2, 0], [0.03, y1 - y0, Dp], pick("wood", k + 1, seed + sx))
    add.cuboid([0, 0.01, 0], [W, 0.02, Dp], P["wood_dark"])                                     # the bottom
    for sx in (-1, 1):                                          # iron at the corners, rope handles at the ends
        for sz in (-1, 1):
            add.cuboid([sx * (W / 2 + 0.003), H / 2, sz * (Dp / 2 - 0.03)], [0.006, H - 0.02, 0.06], P["iron"])
            add.cuboid([sx * (W / 2 - 0.03), H / 2, sz * (Dp / 2 + 0.003)], [0.06, H - 0.02, 0.006], P["iron"])
        add.polyline([[sx * (W / 2 + 0.012 + 0.07 * add.sin(a)), H * 0.62, 0.07 * add.cos(a)] for a in [add.pi * j / 8 for j in range(9)]],
                     0.012, 5, P["rope"])
    add.cuboid([0, H * 0.75, Dp / 2 + 0.008], [0.1, 0.12, 0.012], P["iron"])                  # the lock
    add.cuboid([0, H * 0.72, Dp / 2 + 0.016], [0.02, 0.04, 0.004], P["black"])
    lid = add.Mesh()                                             # the lid: boards on two battens, hinged at the back
    for k in range(4):
        z0, z1 = -Dp / 2 + k * Dp / 4 + 0.003, -Dp / 2 + (k + 1) * Dp / 4 - 0.003
        lid.extend(add.make(add.cuboid, [0, 0.015, (z0 + z1) / 2 + Dp / 2], [W, 0.03, z1 - z0], pick("wood", k + 2, seed)))
    for sx in (-1, 1):
        lid.extend(add.make(add.cuboid, [sx * (W / 2 - 0.08), 0.038, Dp / 2], [0.05, 0.016, Dp - 0.04], P["iron"]))
    add.mesh(add.move(add.rotateX(lid, -open_), [0, H, -Dp / 2]))
    YF, HM, RX, RZ = 0.22, 0.17, 0.47, 0.27                     # the gold: a board across the chest (under it the
    add.cuboid([0, YF - 0.01, 0], [W - 0.062, 0.02, Dp - 0.062], P["wood_dark"])   # chest is empty), and on it a mound,

    def mound(x, z):                                            # its height and its normal at (x, z): rising smoothly
        s = (x / RX) ** 2 + (z / RZ) ** 2                       # from the board at the sides to the middle
        if s >= 1.0:
            return YF, [0.0, 1.0, 0.0]
        f = 2 * HM * (1 - s) * 2
        return YF + HM * (1 - s) ** 2, vunit([f * x / RX ** 2, 1.0, f * z / RZ ** 2])
    coin = add.make(add.cylinder, [0, 0.0015, 0], [0, 0.0055, 0], 0.022, 10, P["gold"])
    for layer in range(3):                                      # coins on it in three layers, each 7 mm over the one
        placed = []                                             # under it along the mound's normal, none touching
        for k in range(1400):                                   # another in its layer
            x = (W / 2 - 0.055) * (2 * hash2(k, layer, seed + 61) - 1)
            z = (Dp / 2 - 0.055) * (2 * hash2(k, layer, seed + 62) - 1)
            y, n = mound(x, z)
            off = 0.001 + 0.007 * layer
            c = [x + n[0] * off, y + n[1] * off, z + n[2] * off]
            if any((c[0] - q[0]) ** 2 + (c[1] - q[1]) ** 2 + (c[2] - q[2]) ** 2 < 0.047 ** 2 for q in placed):
                continue
            placed.append(c)
            m = add.rotate(coin, vcross([0, 1, 0], n), add.acos(max(-1.0, min(1.0, n[1])))) if n[1] < 0.99999 else coin
            add.mesh(add.move(add.rotateY(m, 6.28 * hash2(k, layer, seed + 63)) if n[1] >= 0.99999 else m, c))
    return add.pop()


def oar():
    """An oar lying flat, in its own frame (along x, the blade at +x)."""
    add.push()
    add.cylinder([-1.3, 0.035, 0], [0.9, 0.035, 0], 0.03, 8, P["wood"])
    add.cuboid([1.21, 0.02, 0], [0.62, 0.02, 0.14], P["wood"])
    add.cylinder([-1.45, 0.035, 0], [-1.3, 0.035, 0], 0.024, 8, P["wood_dark"])           # the grip
    return add.pop()


def grapnel():
    """A small four-fluked iron grapnel lying on its side, its ring up."""
    add.push()
    add.cylinder([0, 0, 0], [0.55, 0, 0], 0.025, 8, P["iron"])
    add.torus([0.6, 0, 0], 0.05, 0.012, 10, 4, P["iron"], axis=(0, 0, 1))
    for k in range(4):
        a = k * add.pi / 2 + 0.4
        tip = [0.14, 0.16 * add.cos(a), 0.16 * add.sin(a)]
        add.polyline([[0.0, 0, 0], [0.02, 0.1 * add.cos(a), 0.1 * add.sin(a)], tip], 0.018, 5, P["iron"])
    return add.pop()


# the sunken boat: a wreck of a rowing boat lying heeled over on the lake bed, half in the sand; a sea chest beside it,
# its lid thrown open, gold in it and spilled on the sand; an oar and the boat's grapnel on its rope
bx, bz, bh = WRECK
add.push()
wreck_m = add.rotate(wreck_boat(3), [1, 0, 0], 0.55)                  # heeled over onto its port side, lying
wreck_m = add.rotateY(lie_along(wreck_m, bx, bz, bh, 2.6), bh)              # along the slope of the bed
wreck_m = settle(add.move(wreck_m, [bx, 0, bz]), 0.12)
add.mesh(wreck_m)
chest_m = add.rotateY(sea_chest(0.95, 5), bh + 2.3)
cx, cz = bx + 2.2 * add.cos(bh - 1.2), bz - 2.2 * add.sin(bh - 1.2)
nb = vunit([(ground(cx - 0.5, cz) - ground(cx + 0.5, cz)) / 1.0, 1.0, (ground(cx, cz - 0.5) - ground(cx, cz + 0.5)) / 1.0])
if nb[1] < 0.99999:                                                                  # (its bottom square to the bed under it,
    chest_m = add.rotate(chest_m, vunit(vcross([0, 1, 0], nb)), add.acos(nb[1]))    # a little into the sand)
add.mesh(settle(add.move(chest_m, [cx, 0, cz]), 0.03))
spilt = []
for k in range(30):                                              # coins spilled on the sand before it
    a, r = bh + 2.3 + 0.7 * (hash2(k, 1, 77) - 0.5), 0.5 + 0.9 * hash2(k, 2, 77)
    x, z = cx + r * add.sin(a), cz + r * add.cos(a)
    if any((x - p) ** 2 + (z - q) ** 2 < 0.05 ** 2 for p, q in spilt):
        continue
    spilt.append((x, z))
    c = add.make(add.cylinder, [0, 0, 0], [0, 0.004, 0], 0.022, 10, P["gold"])
    add.mesh(add.move(c, [x, ground(x, z) - 0.001, z]))
oar_m = add.rotateY(lie_along(oar(), bx - 1.4 * add.sin(bh), bz - 1.4 * add.cos(bh), bh + 0.25, 1.4), bh + 0.25)
ox, oz = bx - 1.4 * add.sin(bh), bz - 1.4 * add.cos(bh)
add.mesh(settle(add.move(oar_m, [ox, 0, oz]), 0.02))
grapnel_m = add.rotateY(grapnel(), bh - 0.5)
gx, gz = bx + 3.9 * add.cos(bh), bz - 3.9 * add.sin(bh)
add.mesh(settle(add.move(grapnel_m, [gx, 0, gz]), 0.05))
W_ALL = add.pop()
add.mesh(W_ALL)
WRECK_CELLS = set()                                              # (the ground it covers, in half-metre cells, for the
for v in W_ALL.V:                                                # pebbles to keep off)
    i, j = int(add.floor(v[0] / 0.5)), int(add.floor(v[2] / 0.5))
    WRECK_CELLS.update((i + a, j + b) for a in (-1, 0, 1) for b in (-1, 0, 1))


def by_wreck(x, z, r=0.0):
    """Does a thing of radius ``r`` at (x, z) on the lake bed come near the wreck?"""
    n = int(r / 0.5) + 1
    i, j = int(add.floor(x / 0.5)), int(add.floor(z / 0.5))
    return any((i + a, j + b) in WRECK_CELLS for a in range(-n, n + 1) for b in range(-n, n + 1))


PEBBLE = add.make(add.icosahedron, [0, 0, 0], 1.0)
add.seed(7)
N_PEBBLES = count(24000)
i = 0
while i < N_PEBBLES:                                   # stones lie on the whole bed of the lake, out to its edges
    x, z = add.uniform(-W_EDGE + 1, W_EDGE - 1), add.uniform(-W_EDGE + 1, W_EDGE - 1)
    if ground(x, z) > WATER_Y - 0.25 or by_wreck(x, z, 0.6):
        continue
    a = add.uniform(0, 2 * add.pi)
    rr = add.uniform(0.15, 0.45)
    pebble = add.color(add.stretch(PEBBLE, [rr * add.uniform(0.8, 1.3), rr * 0.6, rr], (0, 0, 0)),
                       add.choice([P["rock"], P["stone_dark"], P["sand"]]))
    add.mesh(add.move(add.rotateY(pebble, a), [x, ground(x, z) + 0.05, z]))
    i += 1
    if i % 10000 == 0:
        flush("pebbles (%d)" % i, clean=False)
flush("pebbles", clean=False)
def by_boat(x, z, margin=0.0):
    """By one of the rowing boats on the shore (plus ``margin``)?"""
    for deg in BOAT_DEGS:
        a = deg * add.pi / 180
        r = shore_r(a) + 1.9
        if (x - r * add.cos(a)) ** 2 + (z - r * add.sin(a)) ** 2 < (3.2 + margin) ** 2:
            return True
    return False


def by_jetty(x, z, margin=0.5):
    """By the harbour -- the end of the road, the wharf, the ships moored to
    it -- or by one of the rowing boats on the shore (plus ``margin``)?"""
    u, v = x * DOCK_C + z * DOCK_S, -x * DOCK_S + z * DOCK_C
    if DOCK_U0 - 6 - margin < u < DOCK_U1 + 8 + margin and abs(v) < 13 + margin:
        return True
    return by_boat(x, z, margin)


def on_wharf(x, z, margin=0.0):
    """On the wharf itself -- its deck from the end of the road out into the
    lake, its beams and posts -- plus ``margin`` (the land round it is
    free for the grass)?"""
    u, v = x * DOCK_C + z * DOCK_S, -x * DOCK_S + z * DOCK_C
    return DOCK_U0 - 0.3 - margin < u < DOCK_U1 + 0.5 + margin and abs(v) < DOCK_W + 0.3 + margin


# fish in the lake, in schools of one kind, each school heading one way: small silver roach in big schools, perch, bluish
# bream, a few big orange carp together -- in the deep water only, clear of the bed and its stones, of the surface, of
# the harbour and the sunken boat, and of each other
FISH_KINDS = ((P["steel"], (0.26, 0.32), (14, 22)), (P["gold"], (0.34, 0.42), (8, 14)),   # colour, sizes, how many
              (P["blue"], (0.4, 0.5), (6, 10)), (P["orange"], (0.52, 0.62), (3, 6)))
_fish_cells = {}                                       # (a grid of 1 m cells: the spheres round the fish in each)


def fish_clear(x, y, z, heading, size):
    """The three spheres round a fish (see fish()) swimming the way ``heading``
    (an angle in XZ) -- or None if they touch the lake bed, its stones, the
    surface, another fish, the harbour or the sunken boat."""
    c, sn = add.cos(heading), add.sin(heading)
    balls = [(x + c * d * size, y, z + sn * d * size, 0.62 * size) for d in (0.45, -0.25, -1.0)]
    if y + 0.75 * size > WATER_Y - 0.3 or by_jetty(x, z, 4.0) or (x - 71) ** 2 + (z - 83) ** 2 < 7 ** 2:
        return None
    for bx, by, bz, br in balls:
        if abs(bx) > W_EDGE - 3 or abs(bz) > W_EDGE - 3 or by - br < ground(bx, bz) + 0.36:
            return None
        i, j, k = int(bx // 1), int(by // 1), int(bz // 1)
        if any((bx - q[0]) ** 2 + (by - q[1]) ** 2 + (bz - q[2]) ** 2 < (br + q[3]) ** 2 for a in (i - 1, i, i + 1)
               for b in (j - 1, j, j + 1) for e in (k - 1, k, k + 1) for q in _fish_cells.get((a, b, e), ())):
            return None
    return balls


n_fish, SCHOOLS = 0, []
for n in range(count(900) // 12 * 4):                                                   # (tries)
    if n_fish >= count(900):
        break
    h = lambda j: hash2(n, j, 111)
    a, r = 6.2832 * h(1), 80 + 66 * add.sqrt(h(2))
    cx, cz = r * add.cos(a), r * add.sin(a)
    if abs(cx) > W_EDGE - 8 or abs(cz) > W_EDGE - 8 or ground(cx, cz) > WATER_Y - 3.2:
        continue
    colour, sizes, many = FISH_KINDS[int(h(3) * 4) % 4]
    N = many[0] + int(h(4) * (many[1] - many[0] + 1))
    heading = 6.2832 * h(5)
    L, W = 0.9 * add.sqrt(N) * sizes[1] * 2.2, 0.9 * add.sqrt(N) * sizes[1] * 1.4        # the school: long, wide,
    if any((cx - q[0]) ** 2 + (cz - q[1]) ** 2 < (L + q[2] + 6.0) ** 2 for q in SCHOOLS):   # and away from the others
        continue
    SCHOOLS.append((cx, cz, L))
    cy = min(WATER_Y - 0.6 - 0.8 * sizes[1], ground(cx, cz) + 1.6 + 0.6 * h(6) * (WATER_Y - 2.6 - ground(cx, cz)))
    placed = 0
    for k in range(N * 8):
        if placed == N:
            break
        u, v, w = (hash2(n, k, 112) - 0.5) * 2 * L, (hash2(n, k, 113) - 0.5) * 2 * W, (hash2(n, k, 114) - 0.5) * 1.6 * sizes[1] * 2
        x, z = cx + u * add.cos(heading) - v * add.sin(heading), cz + u * add.sin(heading) + v * add.cos(heading)
        head, size = heading + (hash2(n, k, 115) - 0.5) * 0.3, sizes[0] + (sizes[1] - sizes[0]) * hash2(n, k, 116)
        balls = fish_clear(x, cy + w, z, head, size)
        if balls is None:
            continue
        for q in balls:
            _fish_cells.setdefault((int(q[0] // 1), int(q[1] // 1), int(q[2] // 1)), []).append(q)
        fish([x, cy + w, z], add.pi - head, colour, size)                                 # (its head to -x: turned so)
        placed += 1
    n_fish += placed
flush("fish (%d, in %d schools)" % (n_fish, len(SCHOOLS)), clean=False)


def surface_z(M, x, y, sz):
    """How far out along +z (``sz`` = 1) or -z (-1) the surface of the
    mesh ``M`` is over the point (x, y): the outermost of its faces there
    (None if it has none there)."""
    best = None
    for f in M.F:
        for k in range(1, len(f) - 1):
            a, b, c = M.V[f[0]], M.V[f[k]], M.V[f[k + 1]]
            d = (b[0] - a[0]) * (c[1] - a[1]) - (c[0] - a[0]) * (b[1] - a[1])
            if abs(d) < 1e-12:
                continue
            u = ((x - a[0]) * (c[1] - a[1]) - (c[0] - a[0]) * (y - a[1])) / d
            v = ((b[0] - a[0]) * (y - a[1]) - (x - a[0]) * (b[1] - a[1])) / d
            if u < -1e-9 or v < -1e-9 or u + v > 1 + 1e-9:
                continue
            z = a[2] + u * (b[2] - a[2]) + v * (c[2] - a[2])
            if z * sz > 0 and (best is None or z * sz > best * sz):
                best = z
    return best


def shark(at, heading, size=1.0):
    """A shark swimming ``heading`` (an angle in XZ), its middle at ``at``, ``size`` times 3 m long: a long body, blue-
    grey above and white below, its snout pointed and its mouth under it, five gill slits a side, black eyes; the tall
    fin on its back, the smaller one behind it, the long fins at its sides angled down, the fins under its belly, and the
    tail's upper lobe longer than the lower."""
    stations = ((1.5, 0.02, 0.015), (1.35, 0.1, 0.08), (1.1, 0.2, 0.17), (0.7, 0.28, 0.25), (0.2, 0.3, 0.27), (-0.3, 0.26, 0.22),
                (-0.8, 0.17, 0.14), (-1.15, 0.09, 0.08), (-1.3, 0.05, 0.045))   # (x, half height, half width)
    add.push()
    rings = [[[x, h * add.sin(2 * add.pi * j / 12) - 0.03 * (x > 1.0) * (1 - add.sin(2 * add.pi * j / 12)), w * add.cos(2 * add.pi * j / 12)]
              for j in range(12)] for x, h, w in stations]
    body = add.make(add.loft, rings, P["white"])
    add.mesh(add.fix_normals(add.color_by(body, lambda q: P["white"] if q[1] < -0.05 else P["mail"])))
    fin = lambda pts, t, c, col=None: add.mesh(add.make(add.prism, pts, t, col or P["mail"], c, (0, 0, 1)))
    fin([[0.2, 0.25], [-0.35, 0.25], [-0.2, 0.85]], 0.05, (0, 0, 0))                                        # the fins on its back
    fin([[-0.75, 0.15], [-0.95, 0.15], [-0.93, 0.36]], 0.03, (0, 0, 0))
    fin([[-1.25, 0.0], [-1.3, 0.06], [-1.85, 0.62], [-1.62, 0.02], [-1.75, -0.4], [-1.3, -0.05]], 0.04, (0, 0, 0))   # its tail
    for sz in (-1, 1):
        add.mesh(slab([[0.6, -0.12, sz * 0.2], [0.25, -0.14, sz * 0.22], [0.0, -0.36, sz * 0.72], [0.28, -0.3, sz * 0.62]][::sz], 0.03, P["mail"]))
        add.mesh(slab([[-0.55, -0.15, sz * 0.1], [-0.72, -0.14, sz * 0.09], [-0.8, -0.3, sz * 0.26], [-0.66, -0.28, sz * 0.24]][::sz], 0.02,
                      P["mail"]))
        add.sphere([1.18, 0.06, sz * 0.135], 0.022, 4, P["black"])                                       # the eyes,
        for k in range(5):                                                                                  # the gills: five
            gx = 0.88 - 0.07 * k                                                                            # slits lying on its
            secs = []                                                                                       # side, bent round it
            for i in range(13):                                                                             # (on the body's own
                y = -0.075 + 0.15 * i / 12                                                                  # facets, each corner
                sec = []                                                                                    # just proud of them)
                for x, dz in ((gx - 0.006, 0.001), (gx + 0.006, 0.001), (gx + 0.006, 0.005), (gx - 0.006, 0.005)):
                    sec.append([x, y, surface_z(body, x, y, sz) + sz * dz])
                secs.append(sec)
            add.mesh(add.fix_normals(add.make(add.loft, secs, P["black"])))
    add.cuboid([1.22, -0.15, 0], [0.14, 0.012, 0.16], P["black"])                                          # the mouth
    M = add.pop()
    add.mesh(add.move(add.rotateY(add.stretch(M, [size] * 3, (0, 0, 0)), -heading), at))


def reed_clump(x, z, seed):
    """A clump of reeds standing in the shallows at (x, z): five to nine
    stems from the bed up out of the water, tapering, leaning a little
    each its own way, some with a bulrush's brown head and a spike over
    it; long leaves arching off them, each a thin blade whole on both
    sides (see lens_leaf)."""
    y0 = ground(x, z) - 0.05
    LM = add.Mesh()
    for j in range(5 + int(hash2(seed, 1, 151) * 5)):
        a, rr = 2 * add.pi * hash2(seed, j, 152), 0.25 * hash2(seed, j, 153)
        bx, bz = x + rr * add.cos(a), z + rr * add.sin(a)
        top = WATER_Y + 0.9 + 1.2 * hash2(seed, j, 154)
        lx, lz = 0.18 * (hash2(seed, j, 155) - 0.5), 0.18 * (hash2(seed, j, 156) - 0.5)
        tip = [bx + lx, top, bz + lz]
        add.frustum([bx, y0, bz], tip, 0.014, 0.004, 6, (P["leaf_dark"], P["grass_dry"], P["leaf_dark"])[j % 3])
        if hash2(seed, j, 157) < 0.4:                                  # a bulrush head, a spike over it
            h0 = [bx + lx * 0.8, y0 + (top - y0) * 0.8, bz + lz * 0.8]
            h1 = [bx + lx * 0.9, y0 + (top - y0) * 0.9, bz + lz * 0.9]
            add.cylinder(h0, h1, 0.024, 7, P["wood_dark"])
        for k in range(j % 2):                                         # a leaf arching off every other one
            d = vunit([add.cos(a + 1.3 * k + 0.6) * 0.35, 1.0, add.sin(a + 1.3 * k + 0.6) * 0.35])
            f = 0.25 + 0.3 * hash2(seed, j * 3 + k, 158)
            p = [bx + lx * f, y0 + (top - y0) * f, bz + lz * f]
            w = vunit(vcross(d, [0, 1, 0])) if abs(d[1]) < 0.99 else [1, 0, 0]
            lens_leaf(LM, p, d, w, 0.7 + 0.5 * hash2(seed, j, 159), 0.045, P["leaf"] if k else P["grass"], 0.002)
    add.mesh(LM)


def lily_pad(x, z, size, seed):
    """A water lily's pad floating at (x, z), ``size`` round: a disc a
    centimetre thick, cut in to its middle by the notch where its stalk
    comes up, in one of three greens, its top a hair over the ripples; on
    one in five a flower open on it -- two rings of white or pink pointed
    petals, the inner ones standing up, round a yellow heart -- and on
    some a bud, closed."""
    y = max([ripple(x, z)] + [ripple(x + size * add.cos(k * 0.785), z + size * add.sin(k * 0.785)) for k in range(8)]) + 0.012
    turn = 2 * add.pi * hash2(seed, 1, 161)                            # (its top a centimetre over the highest ripple
    n = 20                                                             # under it)
    rim = [(x, z)]
    for k in range(n + 1):                                             # (the notch: 0.5 radians wide)
        a = turn + 0.25 + (2 * add.pi - 0.5) * k / n
        rim.append((x + size * add.cos(a), z + size * add.sin(a)))
    green = (P["leaf"], P["leaf_dark"], P["oak_leaf"])[seed % 3]
    add.mesh(solid(rim, y - 0.01, y, green))
    u = hash2(seed, 2, 161)
    if u < 0.2:                                                        # a flower, on the pad
        col = P["white"] if hash2(seed, 3, 161) < 0.6 else P["rose"]
        LM = add.Mesh()
        c = [x - 0.25 * size * add.cos(turn), y, z - 0.25 * size * add.sin(turn)]
        for ring, (cnt, L, W, up, ph) in enumerate(((10, 0.11, 0.05, 0.35, 0.0), (8, 0.085, 0.042, 0.95, 0.4))):
            for k in range(cnt):
                a = 2 * add.pi * (k + ph) / cnt + turn
                d = vunit([add.cos(a) * add.cos(up), add.sin(up), add.sin(a) * add.cos(up)])
                w = [-add.sin(a), 0.0, add.cos(a)]
                p = [c[0] + 0.018 * add.cos(a), c[1] + 0.006 + 0.012 * ring, c[2] + 0.018 * add.sin(a)]
                lens_leaf(LM, p, d, w, L, W, col, 0.0025)
        add.mesh(LM)
        add.cylinder([c[0], y, c[2]], [c[0], y + 0.035, c[2]], 0.024, 10, P["dandelion"])   # the heart
    elif u < 0.32:                                                     # a bud, closed, on its stalk just clear of the water
        bx, bz = x + (size + 0.08) * add.cos(turn), z + (size + 0.08) * add.sin(turn)
        by = ripple(bx, bz)
        add.cylinder([bx, by - 0.3, bz], [bx, by + 0.06, bz], 0.008, 5, P["leaf_dark"])
        add.ellipsoid([bx, by + 0.09, bz], [0.022, 0.045, 0.022], 3, P["rose"] if seed % 2 else P["white"])


def flag_iris(x, z, seed):
    """A clump of yellow flag at the water's edge: a fan of stiff sword
    leaves, each whole on both sides, and two or three stems over them
    with yellow flowers -- three falls hanging, three standards up."""
    y0 = ground(x, z) - 0.03
    LM = add.Mesh()
    a0 = 2 * add.pi * hash2(seed, 1, 171)
    for k in range(9):
        a = a0 + 0.35 * (k - 4) / 4.0
        d = vunit([add.cos(a0) * 0.25 * (k - 4) / 4.0 + 0.02, 1.0, add.sin(a0) * 0.25 * (k - 4) / 4.0])
        w = [-add.sin(a0), 0.0, add.cos(a0)]
        lens_leaf(LM, [x + 0.02 * (k - 4) * add.cos(a0), y0, z + 0.02 * (k - 4) * add.sin(a0)], d, w,
                  0.7 + 0.4 * hash2(seed, k, 172), 0.05, P["leaf"] if k % 2 else P["grass"], 0.003)
    for j in range(2 + seed % 2):
        top = [x + 0.08 * (j - 0.5), y0 + 1.05 + 0.15 * j, z + 0.05 * (j - 0.5)]
        add.cylinder([x, y0, z], top, 0.009, 5, P["leaf_dark"])
        for k in range(3):
            a = 2 * add.pi * k / 3 + j
            for up, L in ((-0.6, 0.075), (1.1, 0.055)):                # (a fall, a standard)
                d = vunit([add.cos(a) * add.cos(up), add.sin(up), add.sin(a) * add.cos(up)])
                lens_leaf(LM, top, d, [-add.sin(a), 0.0, add.cos(a)], L, 0.04, P["dandelion"], 0.002)
    add.mesh(LM)


def pondweed(x, z, seed):
    """Pondweed under the water: three or four stems waving up from the
    bed towards the light, leaves along them, all a hand under the
    surface."""
    y0, y1 = ground(x, z) - 0.02, ripple(x, z) - 0.2
    LM = add.Mesh()
    for j in range(2 + seed % 2):
        a = 2 * add.pi * hash2(seed, j, 181)
        pts = []
        for k in range(7):
            t = k / 6.0
            sway = 0.12 * add.sin(3.0 * t + j + seed)
            pts.append([x + 0.1 * j * add.cos(a) + sway * add.cos(a + 1), y0 + (y1 - y0) * t * (0.75 + 0.25 * hash2(seed, j, 182)),
                        z + 0.1 * j * add.sin(a) + sway * add.sin(a + 1)])
        add.polyline(pts, 0.006, 4, P["leaf_dark"])
        for k in range(1, 7, 2):
            p = pts[k]
            d = vunit([add.cos(a + 2.1 * k), 0.8, add.sin(a + 2.1 * k)])
            lens_leaf(LM, p, d, vunit(vcross(d, [0, 1, 0])), 0.07, 0.03, P["leaf"] if k % 2 else P["oak_leaf"], 0.0015)
    add.mesh(LM)


SHARKS = []                                            # two or three sharks in the deep water well out from the island,
for n in range(400):                                   # clear of the harbour, the sunken boat, the bed, the surface and
    if len(SHARKS) == 3:                               # the fish
        break
    a, r = 6.2832 * hash2(n, 1, 131), 112 + 25 * hash2(n, 2, 131)
    x, z = r * add.cos(a), r * add.sin(a)
    if abs(x) > W_EDGE - 10 or abs(z) > W_EDGE - 10 or by_jetty(x, z, 22.0) or (x - 71) ** 2 + (z - 83) ** 2 < 16 ** 2:
        continue
    if any((x - q[0]) ** 2 + (z - q[2]) ** 2 < 30 ** 2 for q in SHARKS):
        continue
    heading = a + add.pi / 2 + 0.4 * (hash2(n, 3, 131) - 0.5)          # (round the island)
    size = 0.9 + 0.25 * hash2(n, 4, 131)
    y = WATER_Y - 1.2 - 0.6 * hash2(n, 5, 131)
    c, sn = add.cos(heading), add.sin(heading)
    balls = [(x + c * d * size, y, z + sn * d * size, 0.95 * size) for d in (1.0, 0.0, -1.0)]
    if any(by - br < ground(bx, bz) + 0.3 or by + br > WATER_Y - 0.15 for bx, by, bz, br in balls):
        continue
    if any((bx - q[0]) ** 2 + (by - q[1]) ** 2 + (bz - q[2]) ** 2 < (br + q[3] + 0.3) ** 2 for bx, by, bz, br in balls
           for a_ in range(int(bx // 1) - 2, int(bx // 1) + 3) for b_ in range(int(by // 1) - 2, int(by // 1) + 3)
           for e_ in range(int(bz // 1) - 2, int(bz // 1) + 3) for q in _fish_cells.get((a_, b_, e_), ())):
        continue
    shark([x, y, z], heading, size)
    SHARKS.append((x, y, z, heading, size))
