# the road from the gate to the harbour, paved: a bed of stone along ROAD, fieldstones set close in rows across it, a
# kerb of stones on the side of the hill and a low wall of stones on the side where the hill falls away; the ground is
# cut and banked to it (see ground())
ROAD_LEN = [0.0]
for k in range(1, len(ROAD)):
    ROAD_LEN.append(ROAD_LEN[-1] + add.sqrt((ROAD[k][0] - ROAD[k - 1][0]) ** 2 + (ROAD[k][1] - ROAD[k - 1][1]) ** 2))
ROAD_T = [(0.0, 1.0)]                                  # the way the road goes at each point: off the bridge straight,
for k in range(1, len(ROAD)):                          # then along the line through its neighbours
    a, b = ROAD[k - 1], ROAD[min(len(ROAD) - 1, k + 1)]
    d = add.sqrt((b[0] - a[0]) ** 2 + (b[1] - a[1]) ** 2)
    ROAD_T.append(((b[0] - a[0]) / d, (b[1] - a[1]) / d))


def road(u, v):
    """The point at ``u`` (0 at the drawbridge .. 1 at the wharf) along the
    road and ``v`` (0 .. 1) across it, on its surface -- level across."""
    s_ = u * ROAD_LEN[-1]
    k = min(len(ROAD) - 2, max(0, next((i for i in range(len(ROAD) - 1) if ROAD_LEN[i + 1] >= s_), len(ROAD) - 2)))
    t = (s_ - ROAD_LEN[k]) / max(1e-9, ROAD_LEN[k + 1] - ROAD_LEN[k])
    (x0, z0, y0), (x1, z1, y1) = ROAD[k], ROAD[k + 1]
    tx, tz = ROAD_T[k][0] + (ROAD_T[k + 1][0] - ROAD_T[k][0]) * t, ROAD_T[k][1] + (ROAD_T[k + 1][1] - ROAD_T[k][1]) * t
    L = add.sqrt(tx * tx + tz * tz)
    x, z = x0 + (x1 - x0) * t + (-tz / L) * (v - 0.5) * 2 * ROAD_W, z0 + (z1 - z0) * t + (tx / L) * (v - 0.5) * 2 * ROAD_W
    return [x, y0 + (y1 - y0) * t + 0.12, z]


def on_road(x, z, margin=0.6):
    """Is (x, z) on the road to the harbour (its paved strip plus
    ``margin``), on the drawbridge, or on the landing before the gate?"""
    if abs(x) < 5.5 + margin and 50 < z < MOAT[3] + 1.5:
        return True
    q = road_at(x, z)
    return q is not None and q[0] < ROAD_W + margin


add.parametric(lambda u, v: [road(u, v)[k] - (0.125 if k == 1 else 0.0) for k in range(3)], 0, 1, int(ROAD_LEN[-1] * 2), 0, 1, 6, P["stone_dark"],
               thickness=0.25)                         # the bed: a slab whose top is the road's surface
FIELD = [shade_of("stone_dark", 0), shade_of("stone_dark", 1), shade_of("stone_dark", 2), shade_of("stone", 0), shade_of("stone", 2),
         P["rock"], P["granite"], P["granite"], P["earth_light"], P["spire"]]            # fieldstones: grey, pink, brown


def fieldstone(at, r, seed, squash=0.6):
    """A rounded fieldstone of radius ``r`` (squashed flat) at ``at``."""
    M = add.stretch(PEBBLE, [r * (1.0 + 0.3 * hash2(seed, 1, 81)), r * squash, r], (0, 0, 0))
    add.mesh(add.move(add.rotateY(add.color(M, FIELD[int(hash2(seed, 2, 81) * 10) % 10]), hash2(seed, 3, 81) * 6.28), at))


n = cobble_pack(lambda s_, t_: tuple(road(s_, 0.5 + (t_ - 0.5) * 4.1 / (2 * ROAD_W))[::2]), ROAD_LEN[-1] * 4.1,   # the cobbles:
                lambda x, z: (road_at(x, z) or (99, 0))[0] < 2.07 and (z > MOAT[3] + 1.05 or x > 8.0) and x * DOCK_C + z * DOCK_S < DOCK_U0 - 0.05,
                lambda x, z: road_at(x, z)[1] + 0.09, seed=71,  # fieldstones
                colours=FIELD)                         # of all colours and sizes, worn flat, set close between the kerb and
                                                       # the parapet


def along(v, s0, step):
    """Points on the road's surface at ``v`` across it, every ``step``
    metres along that line from ``s0`` metres along the road on."""
    pts = [road(min(1.0, (s0 + i * 0.05) / ROAD_LEN[-1]), v) for i in range(int((ROAD_LEN[-1] - s0) / 0.05) + 1)]
    out_, walk = [pts[0]], 0.0
    for i in range(1, len(pts)):
        walk += add.sqrt((pts[i][0] - pts[i - 1][0]) ** 2 + (pts[i][2] - pts[i - 1][2]) ** 2)
        if walk >= step:
            out_.append(pts[i])
            walk = 0.0
    return out_


for k, q in enumerate(along(0.5 - (ROAD_W - 0.2) / (2 * ROAD_W), ROAD_LEN[4] + 0.5, 0.4)):   # the kerb on the hill side:
    fieldstone([q[0], q[1] - 0.04, q[2]], 0.17 + 0.03 * hash2(k, 5, 82), k, 0.75)            # a row of stones half sunk
pts = along(0.5 + (ROAD_W - 0.27) / (2 * ROAD_W), 0.3, 0.6)      # on the side where the hill falls away, a parapet: a low
for k in range(len(pts) - 1):                                     # wall of fieldstones set in mortar, knee high
    A, B = pts[k], pts[k + 1]
    d = vunit([B[0] - A[0], 0.0, B[2] - A[2]])
    add.beam([A[0], A[1] + 0.15, A[2]], [B[0], B[1] + 0.15, B[2]], 0.54, 0.6, P["mortar"])
    for f in (0.25, 0.75):
        c = [A[j] + (B[j] - A[j]) * f for j in range(3)]
        fieldstone([c[0], c[1] + 0.47, c[2]], 0.22 + 0.04 * hash2(k, int(f * 4), 83), k * 4 + int(f * 4), 0.5)   # on top
        for sd in (-1, 1):                                                                                     # and in its faces
            fieldstone([c[0] + sd * d[2] * 0.25, c[1] + 0.22, c[2] - sd * d[0] * 0.25], 0.15 + 0.03 * hash2(k, sd, 84),
                       k * 8 + int(f * 4) + sd + 3, 0.7)
flush("the road to the harbour (%d cobbles)" % n)


# the moat's stonework.  Its bank: rough blocks of fieldstone laid in courses along the edge of the water from below
# its floor, each course set back a little, under big flat coping stones a hand over the grass.  Under each end of
# the drawbridge a seat of dressed stones that its planks rest on.  The landing before the gate: a pier of masonry
# with walls of the same blocks and a kerb round its edge.
COURSES = 9
COURSE_H = (G - 0.28 - (MOAT_Y - 0.2)) / COURSES        # from under the floor up to the seats of the bridge


def _crossing(a, b, keep):
    """The point between ``a`` (where ``keep`` fails) and ``b`` (where it holds) where it starts to hold."""
    for i in range(30):
        m = ((a[0] + b[0]) / 2, (a[1] + b[1]) / 2)
        a, b = (a, m) if keep(*m) else (m, b)
    return b


def runs(points, keep):
    """The runs of the polyline ``points`` where ``keep(x, z)`` holds, cut off where it stops or starts to hold."""
    out, run = [], []
    for k, p in enumerate(points):
        if keep(*p):
            if not run and k > 0:
                run.append(_crossing(points[k - 1], p, keep))
            run.append(p)
        elif run:
            out.append(run + [_crossing(p, points[k - 1], keep)])
            run = []
    return out + ([run] if run else [])


def course(points, y0, y1, front, depth, seed, colours, lengths=(0.55, 1.05), gap=GAP, stagger=False, coping=False,
           cuts=(None, None)):
    """A course of stone blocks from ``y0`` to ``y1`` along the polyline ``points`` (in XZ), end to end with joints of
    ``gap``, their faces ``front`` out from the line to its left -- the water's side -- and following its bends: dressed
    stones laid even, on a bed of mortar ``depth`` deep behind their faces that fills the joints up to JOINT under them
    (the bed one piece along the course, the stones on it JOINT thick).  ``coping``: the stones of a coping instead,
    the whole depth, their joints filled with mortar up to JOINT under their tops and faces.  ``cuts``: for the
    course's start and end, a plane (a, b, c) -- a*x + b*z = c, the line's end point on it -- that its first and last
    stones and the bed are cut on, to stop flush against a wall's face there (None: square to the line)."""
    keep = [points[0]]                                                       # (the line's points where it bends: where it
    for k in range(1, len(points) - 1):                                      #  runs straight on, none)
        (ax, az), (bx, bz), (cx_, cz_) = keep[-1], points[k], points[k + 1]
        u_, v_ = (bx - ax, bz - az), (cx_ - bx, cz_ - bz)
        lu, lv = add.sqrt(u_[0] ** 2 + u_[1] ** 2), add.sqrt(v_[0] ** 2 + v_[1] ** 2)
        if lu > 1e-9 and lv > 1e-9 and abs(u_[0] * v_[1] - u_[1] * v_[0]) / (lu * lv) > 0.004:
            keep.append(points[k])
    points = keep + [points[-1]]
    n_ = len(points)
    acc = [0.0]
    for k in range(1, n_):
        acc.append(acc[-1] + add.sqrt((points[k][0] - points[k - 1][0]) ** 2 + (points[k][1] - points[k - 1][1]) ** 2))
    nrm = []
    for k in range(n_ - 1):                                                  # (each piece's normal towards the water, and
        d = max(1e-9, acc[k + 1] - acc[k])                                   #  at the corners between them the mitre: the
        nrm.append(((points[k + 1][1] - points[k][1]) / d, -(points[k + 1][0] - points[k][0]) / d))   # faces stay parallel)

    def way(k, s):                                                           # (the way out at s, on piece k)
        for cut, at_, ke in ((cuts[0], 0.0, 0), (cuts[1], acc[-1], n_ - 2)):
            if cut and abs(s - at_) < 1e-9:                                  # (at a cut end: along the plane's trace,
                ux_, uz_ = -cut[1], cut[0]                                   #  so that every offset from the line ends
                f_ = ux_ * nrm[ke][0] + uz_ * nrm[ke][1]                     #  on the plane)
                return (ux_ / f_, uz_ / f_)
        if abs(s - acc[k]) < 1e-9 and 0 < k:
            a_, b_ = nrm[k - 1], nrm[k]
            c = 1.0 + a_[0] * b_[0] + a_[1] * b_[1]
            return ((a_[0] + b_[0]) / c, (a_[1] + b_[1]) / c)
        return nrm[k]

    def stations(a, b):                                                      # (a .. b: its ends and the corners between)
        out = []
        for s_ in [a] + [acc[k] for k in range(1, n_ - 1) if a + 1e-9 < acc[k] < b - 1e-9] + [b]:
            k = max(0, min(n_ - 2, next((i for i in range(n_ - 1) if acc[i + 1] > s_ + 1e-9), n_ - 2)))
            t = (s_ - acc[k]) / max(1e-9, acc[k + 1] - acc[k])
            P_ = (points[k][0] + (points[k + 1][0] - points[k][0]) * t, points[k][1] + (points[k + 1][1] - points[k][1]) * t)
            out.append((P_, way(k, s_)))
        return out

    def ribbon(sts, d0, d1, ya, yb, colour):                                 # a solid along the line between the offsets
        M = add.Mesh()                                                       # d0 (out) and d1 (in), from ya up to yb
        ids = []
        for (px, pz), (wx, wz) in sts:
            ids.append([M.add_vertex([px + wx * d, y_, pz + wz * d]) for d in (d0, d1) for y_ in (ya, yb)])
        for i in range(len(ids) - 1):                                        # (0: out low, 1: out high, 2: in low, 3: in high)
            a_, b_ = ids[i], ids[i + 1]
            for f in ((a_[0], b_[0], b_[1], a_[1]), (a_[2], a_[3], b_[3], b_[2]), (a_[1], b_[1], b_[3], a_[3]), (a_[0], a_[2], b_[2], b_[0])):
                M.add_face(f, colour)
        M.add_face((ids[0][0], ids[0][1], ids[0][3], ids[0][2]), colour)
        M.add_face((ids[-1][0], ids[-1][2], ids[-1][3], ids[-1][1]), colour)
        return add.fix_normals(M)

    add.mesh(ribbon(stations(0.0, acc[-1]), front - JOINT, front - depth, y0, y1 if not coping else y0 + gap / 2,
                    P["mortar"]))                                            # the bed (under a coping, thin)
    turns = {}                                                               # (the corners sharper than a stone can be bent
    for k in range(1, n_ - 1):                                               #  round: a joint on each, cut on the mitre --
        c_ = nrm[k - 1][0] * nrm[k][0] + nrm[k - 1][1] * nrm[k][1]           #  the stones either side of it square to it,
        if c_ < add.cos(0.1):                                                #  half a joint back from it)
            turns[k] = (gap / 2) / add.cos(add.acos(max(-1.0, min(1.0, c_))) / 2)
    sharp = sorted(acc[k] for k in turns)
    dir_ = lambda k: (-nrm[k][1], nrm[k][0])                                 # (piece k's way along the line)

    def piece(a, b):                                                         # (the stations of a stone from a to b: an end
        sts = stations(a, b)                                                 #  on a sharp corner set back on the mitre)
        for idx, s_, sg_ in ((0, a, 1), (-1, b, -1)):
            k = next((k for k in turns if abs(acc[k] - s_) < 1e-9), None)
            if k is not None:
                (px, pz), w_ = sts[idx]
                dx, dz = dir_(k if sg_ > 0 else k - 1)
                sts[idx] = ((px + sg_ * dx * turns[k], pz + sg_ * dz * turns[k]), w_)
        return sts

    def slant(end, d_):                                                      # (how far along the line from its end a
        if not cuts[end]:                                                    #  cut end's plane is, d_ out from the line)
            return 0.0
        ke = 0 if end == 0 else n_ - 2
        w_ = way(ke, 0.0 if end == 0 else acc[-1])
        return d_ * (w_[0] * dir_(ke)[0] + w_[1] * dir_(ke)[1])
    first = max([0.0] + [slant(0, d_) for d_ in (front, front - depth)])     # (no joint where it would run into the
    last = acc[-1] + min([0.0] + [slant(1, d_) for d_ in (front, front - depth)])   # slant of a cut end)
    s, k, a = (-(lengths[0] + lengths[1]) / 4 if stagger else 0.0), 0, 0.0
    while a < acc[-1] - 1e-9:
        L = lengths[0] + (lengths[1] - lengths[0]) * hash2(seed, k, 91)
        b, nxt = s + L - gap, s + L
        c = next((c for c in sharp if a + 1e-9 < c), None)                   # (the next sharp corner: the stone stops on
        stop = c is not None and b > c - 0.25                                #  it, if it would reach it or end just short
        if stop:                                                             #  -- and at the course's end the same)
            b = nxt = c
        elif b > last - 0.25:
            b, nxt, stop = acc[-1], acc[-1], True
        if not stop and (b - a < 0.25 or b < first + 0.25):                   # (too short a stone: it runs on, one with
            s, k = nxt, k + 1                                                 #  the next)
            continue
        colour = colours[int(hash2(seed, k, 95) * len(colours)) % len(colours)]
        add.mesh(ribbon(piece(a, b), front, front - (depth if coping else JOINT), y0 + gap / 2, y1 - gap / 2, colour))
        if coping and b < acc[-1] - 1e-9:                                    # (and the joint after it, filled)
            jt = [piece(a, b)[-1], stations(b, b)[0], piece(nxt, nxt + 0.2)[0]] if b == nxt else stations(b, b + gap)
            add.mesh(ribbon(jt, front - JOINT, front - depth, y0 + gap / 2, y1 - gap / 2 - JOINT, P["mortar"]))
        a = s = nxt
        k += 1


def inset(poly, d, keep=()):
    """The convex outline ``poly`` (counter-clockwise in XZ) with its edges moved in by ``d`` -- all but the ones
    numbered in ``keep``."""
    out = list(poly)
    for k in range(len(poly)):
        if k not in keep:
            (x0, z0), (x1, z1) = poly[k], poly[(k + 1) % len(poly)]
            L = add.sqrt((x1 - x0) ** 2 + (z1 - z0) ** 2)
            a, b = (z1 - z0) / L, -(x1 - x0) / L                                  # its outward normal
            out = clip_half(out, a, b, a * x0 + b * z0 - d)
    return out


BANK_STONE = FIELD[:6] + [P["granite"], shade_of("stone", 1)]
COPING = [shade_of("stone_dark", 0), shade_of("stone_dark", 1), shade_of("stone_dark", 2), P["rock"], P["granite"]]
SEAT_X = BRIDGE_X - 0.02                                                          # the bridge's seats: how far out their
NOTCH_X = SEAT_X + GAP                                                            # stones reach, and the courses either side
not_seat = lambda x, z: not (abs(x) < NOTCH_X and z > 62.0)                       # of them, a joint off: the far bank but
                                                                                  # for the bridge's seat
for j in range(COURSES):                                                          # the bank, battered 1 in 14
    y0 = MOAT_Y - 0.2 + j * COURSE_H
    for r, piece in enumerate(runs(MOAT_EDGE, not_seat) if j == COURSES - 1 else [MOAT_EDGE]):
        course(piece, y0, y0 + COURSE_H, (COURSES - 1 - j) * 0.035, 0.6, 100 * j + r, BANK_STONE, stagger=j % 2 == 1)
for r, piece in enumerate(runs(MOAT_EDGE, not_seat)):
    course(piece, G - 0.28, G + 0.15, 0.03, 0.9, 1000 + r, COPING, lengths=(0.8, 1.3), coping=True)
QZ = GATE_FRONT + 0.0005                                                         # round the landing, from the face of one
QUAY = [(LANDING[2][0] + (LANDING[3][0] - LANDING[2][0]) * (QZ - LANDING[2][1]) / (LANDING[3][1] - LANDING[2][1]), QZ)]   # gate
QUAY = QUAY + LANDING[3:-1] + [(-QUAY[0][0], QZ)]                                 # tower to the other's (the slanting sides
QUAY = [(a[0] + (b[0] - a[0]) * t / 10.0, a[1] + (b[1] - a[1]) * t / 10.0)        # run on straight into them, the courses
        for a, b in zip(QUAY, QUAY[1:]) for t in range(10)] + [QUAY[-1]]           # cut on their faces; every 10th of a side
QCUT = (0.0, 1.0, QZ)                                                              # a point, where the courses are cut for
quay_cuts = lambda piece: (QCUT if piece[0] == QUAY[0] else None, QCUT if piece[-1] == QUAY[-1] else None)   # the seat)
not_notch = lambda x, z: not (abs(x) < NOTCH_X and z > BRIDGE_Z0 + 0.5)           # (the landing's, for its seat)
for j in range(COURSES):                                                          # the landing's walls, upright
    y0 = MOAT_Y - 0.2 + j * COURSE_H
    for r, piece in enumerate(runs(QUAY, not_notch) if j == COURSES - 1 else [QUAY]):
        course(piece, y0, y0 + COURSE_H, 0.0, 0.3, 2000 + 100 * j + r, BANK_STONE, stagger=j % 2 == 1,   # (on to the core)
               cuts=quay_cuts(piece))
for r, piece in enumerate(runs(QUAY, not_notch)):
    course(piece, G - 0.28, G + 0.15, 0.02, 0.55, 3000 + r, COPING, lengths=(0.7, 1.1), coping=True, cuts=quay_cuts(piece))
SEAT_Z0, SEAT_Y0 = BRIDGE_Z0 + HINGE_R + 0.005, G - 0.28 - COURSE_H                # (where the seat under the hinge's end
CORE = inset(LANDING, 0.3, keep=(0,))                                             # begins, and its bed)  The pier's core:
add.mesh(solid(CORE, MOAT_Y - 0.25, SEAT_Y0, P["mortar"]))                        # mortar, a notch left in its top for the
for piece in [clip_half(CORE, 0, 1, SEAT_Z0 - 0.0005)] + [clip_half(clip_half(CORE, 0, -1, 0.0005 - SEAT_Z0), -sx, 0, -SEAT_X - 0.0005)
                                                         for sx in (-1, 1)]:    # seat's stones; on it the bed of the
    add.mesh(solid(piece, SEAT_Y0, G - 0.28, P["mortar"]))                       # paving, up to the hinge of the bridge
EARTH = inset(LANDING, 0.531, keep=(0,))                                          # and beside its deck and its seat: earth,
HINGE_GAP = BRIDGE_Z0 - HINGE_R - 0.005                                           # as the passage's floor and the yard's are,
add.mesh(solid(clip_half(EARTH, 0, 1, HINGE_GAP), G - 0.28, G + 0.02, P["earth_dark"]))   # inside the coping (the cobbles
for sx in (-1, 1):                                                                # on it theirs, laid on from them: see the
    side = clip_half(clip_half(EARTH, 0, -1, -HINGE_GAP), -sx, 0, -DECK - 0.005)  # gatehouse)
    for piece in (clip_half(side, 0, 1, SEAT_Z0), clip_half(clip_half(side, 0, -1, -SEAT_Z0), -sx, 0, -SEAT_X - 0.0005)):
        add.mesh(solid(piece, G - 0.28, G + 0.02, P["earth_dark"]))
for z0, z1, top, face, deep in ((SEAT_Z0, 56.0, G - 0.052, 1, (0.3, 0.53)), (MOAT[3], BRIDGE_Z1, G - 0.08, -1, (0.6, 0.87))):
    zf, zb = (z1, z0) if face > 0 else (z0, z1)                                   # the seats: three dressed stones each,
    zin = lambda d: sorted((zf - face * JOINT, zf - face * d))                    # right up under the bridge -- under the
    zj = sorted((zf - face * JOINT, zb + face * JOINT))                           # leaf of its hinge, and under the iron bar
    box_ = lambda x0, x1, ya, yb, za, zb_, colour: add.cuboid([(x0 + x1) / 2, (ya + yb) / 2, (za + zb_) / 2],
                                                            [x1 - x0, yb - ya, zb_ - za], colour)
    box_(-SEAT_X, SEAT_X, SEAT_Y0, SEAT_Y0 + GAP / 2, zj[0], zj[1], P["mortar"])  # across its far end -- on a bed of mortar
    for i in range(3):                                                            # in the course they stand in, a joint
        x0 = -BRIDGE_X + i * 2 * BRIDGE_X / 3                                     # between them, filled up to JOINT under
        box_(x0 + GAP / 2, x0 + 2 * BRIDGE_X / 3 - GAP / 2, SEAT_Y0 + GAP / 2, top, z0, z1, shade_of("stone", i + (z0 > 60)))
        if i:                                                                     # their faces and their tops; and the
            box_(x0 - GAP / 2 + 0.0005, x0 + GAP / 2 - 0.0005, SEAT_Y0 + GAP / 2, top - JOINT, zj[0], zj[1], P["mortar"])
    for sx in (-1, 1):                                                            # joints at their ends, to the stones
        xa, xb = sorted((sx * (SEAT_X + 0.0005), sx * (NOTCH_X - 0.0005)))        # of the course and of the coping
        za = zin(deep[0])                                                         # either side (as deep as their beds)
        box_(xa, xb, SEAT_Y0, G - 0.28, za[0] + (0.0005 if face > 0 else 0), za[1] - (0 if face > 0 else 0.0005), P["mortar"])
        za = zin(deep[1])
        box_(xa, xb, G - 0.28, top - JOINT, za[0] + (0.0005 if face > 0 else 0), za[1] - (0 if face > 0 else 0.0005), P["mortar"])
flush("the moat's stonework")


PIRANHA = [(-0.62, 0.035, 0.075, -0.065), (-0.58, 0.04, 0.08, -0.07), (-0.5, 0.06, 0.12, -0.11), (-0.4, 0.1, 0.22, -0.21),
           (-0.28, 0.135, 0.33, -0.32), (-0.14, 0.16, 0.41, -0.4), (0.0, 0.17, 0.44, -0.42), (0.14, 0.17, 0.43, -0.4),
           (0.26, 0.16, 0.39, -0.32), (0.36, 0.14, 0.33, -0.2), (0.45, 0.115, 0.25, -0.12), (0.52, 0.09, 0.17, -0.09),
           (0.58, 0.06, 0.09, -0.07), (0.62, 0.025, 0.02, -0.05)]   # (x, half-width, top, bottom): a piranha, tail to snout
PIRANHA_JAW = [(0.28, 0.12, -0.08, -0.33), (0.36, 0.115, -0.085, -0.27), (0.44, 0.1, -0.09, -0.22), (0.52, 0.08, -0.095, -0.17),
               (0.58, 0.055, -0.1, -0.14), (0.64, 0.025, -0.105, -0.125)]          # and its lower jaw, hinge to chin


def section(table, x):
    """(half-width, top, bottom) of a table of sections at ``x``, between its rows."""
    for (x0, *a), (x1, *b) in zip(table, table[1:]):
        if x <= x1:
            t = add.clamp((x - x0) / (x1 - x0))
            return [a[k] + (b[k] - a[k]) * t for k in range(3)]
    return list(table[-1][1:])


def fish_loft(table, n, m, e=1.0):
    """A body lofted through the sections of ``table``: ``n`` rings of ``m``
    points, each a rounded oval (exponent ``e``: 1 an ellipse, less a box)."""
    rings = []
    for i in range(n):
        x = table[0][0] + (table[-1][0] - table[0][0]) * i / (n - 1.0)
        w, top, bot = section(table, x)
        c, h = (top + bot) / 2, (top - bot) / 2
        rings.append([[x, c + h * abs(add.cos(2 * add.pi * j / m)) ** e * (1 if add.cos(2 * add.pi * j / m) >= 0 else -1),
                       w * abs(add.sin(2 * add.pi * j / m)) ** e * (1 if add.sin(2 * add.pi * j / m) >= 0 else -1)] for j in range(m)])
    return add.make(add.loft, rings, P["steel"])


def on_side(table, x, y, out=0.0):
    """How far out to the side the surface of a fish of ``table`` is at (x, y), plus ``out``."""
    w, top, bot = section(table, x)
    c, h = (top + bot) / 2, (top - bot) / 2
    return w * add.sqrt(max(0.0, 1 - ((y - c) / h) ** 2)) + out


def tooth_row(cx, rx, rz, a_max, n, h, colour, rim_y):
    """A row of ``n`` sharp teeth set edge to edge round the arc of a jaw
    (centre ``cx``, radii ``rx`` forwards and ``rz`` across, between the
    angles -a_max and a_max), standing on the rim at the height
    ``rim_y(x, z)``: each a thin triangular blade, its point ``h`` up
    (h < 0: down) and leaning a little into the mouth."""
    rim = lambda a: [cx + rx * add.cos(a), 0.0, rz * add.sin(a)]
    for i in range(n):
        a0, a1 = -a_max + 2 * a_max * i / n, -a_max + 2 * a_max * (i + 1) / n
        p, q, m = rim(a0), rim(a1), rim((a0 + a1) / 2)
        for v in (p, q, m):
            v[1] = rim_y(v[0], v[2])
        nx, nz = rz * add.cos((a0 + a1) / 2), rx * add.sin((a0 + a1) / 2)      # the rim's outward normal
        L = add.sqrt(nx * nx + nz * nz)
        nx, nz = nx / L, nz / L
        tip = [m[0] - 0.012 * nx, m[1] + h, m[2] - 0.012 * nz]
        front = [[v[0] + 0.005 * nx, v[1], v[2] + 0.005 * nz] for v in (p, q, tip)]
        back = [[v[0] - 0.005 * nx, v[1], v[2] - 0.005 * nz] for v in (p, q, tip)]
        M = add.Mesh()
        M.add_polygon(front, colour)
        M.add_polygon(back[::-1], colour)
        for j in range(3):
            M.add_polygon([back[j], back[(j + 1) % 3], front[(j + 1) % 3], front[j]], colour)
        add.mesh(add.fix_normals(M))


def piranha(at, facing, s=1.0, pitch=0.0, gape=0.3):
    """A red-bellied piranha: the deep, flat body of its kind, lofted
    through its sections -- a blunt head, the back rising to the dorsal
    fin, a deep belly, a slender tail stalk -- dark grey along the back,
    silver on the flanks, red on the belly and throat;
    the edge of the gill cover, big golden eyes with a glint, nostrils.
    The lower jaw, hinged down by ``gape``, reaches a little past the
    upper; round the rims of both a close row of small, sharp, triangular
    teeth, edge to edge like a saw -- the upper ones longer, pointing
    down, the lower ones up -- round the dark red mouth.  Dorsal and
    adipose fins, red anal, pelvic and pectoral fins, a forked tail dark
    at its base.  It swims towards +x, its nose ``pitch`` up; ``s`` = 1 is
    1.5 m long."""
    add.push()

    def skin(q):
        w, top, bot = section(PIRANHA, q[0])
        t = (q[1] - (top + bot) / 2) / ((top - bot) / 2)                        # -1 the belly .. 1 the back
        if t < -0.3 - 0.3 * add.clamp((q[0] - 0.25) / 0.2):                     # red below, up to the throat,
            return P["red"]
        return P["iron"] if t > 0.55 else P["mail"] if t > 0.3 else P["steel"]   # silver sides, the back dark

    add.mesh(add.color_by(fish_loft(PIRANHA, 56, 36), skin))
    add.ellipsoid([0.46, -0.1, 0], [0.11, 0.045, 0.06], 6, P["meat"])                       # the mouth, dark red inside
    tooth_row(0.5, 0.11, 0.055, 1.35, 13, -0.075, P["bone"],                                # the upper teeth
              lambda x, z: (section(PIRANHA, x)[1] + section(PIRANHA, x)[2]) / 2 + 0.008
              - (section(PIRANHA, x)[1] - section(PIRANHA, x)[2]) / 2 * add.sqrt(max(0.0, 1 - (z / section(PIRANHA, x)[0]) ** 2)))
    add.push()                                                                               # the lower jaw and its teeth
    add.mesh(add.color_by(fish_loft(PIRANHA_JAW, 12, 20, 0.7), lambda q: P["iron"] if q[1] > section(PIRANHA_JAW, q[0])[1] - 0.012 else P["red"]))
    tooth_row(0.5, 0.12, 0.06, 1.35, 13, 0.05, P["bone"], lambda x, z: section(PIRANHA_JAW, x)[1] - 0.006)
    add.mesh(add.rotateZ(add.pop(), -gape, (0.3, -0.09, 0)))
    for sz in (-1, 1):
        ez = on_side(PIRANHA, 0.4, 0.12)
        add.sphere([0.4, 0.12, sz * (ez - 0.018)], 0.052, 5, P["gold"])                     # big golden eyes,
        add.sphere([0.412, 0.12, sz * (ez + 0.022)], 0.027, 4, P["black"])                  # black pupils,
        add.sphere([0.418, 0.134, sz * (ez + 0.038)], 0.007, 2, P["white"])                 # a glint
        add.sphere([0.54, 0.1, sz * on_side(PIRANHA, 0.54, 0.1)], 0.011, 2, P["black"])      # the nostrils
        gill = [(0.27, 0.3), (0.22, 0.16), (0.2, 0.0), (0.21, -0.15), (0.26, -0.28)]         # the edge of the gill cover
        add.polyline([[x, y, sz * on_side(PIRANHA, x, y, 0.004)] for x, y in gill], 0.007, 5, P["iron"])
        for profile, z0, colour in (([[0.2, -0.17], [0.03, -0.3], [0.09, -0.15]], on_side(PIRANHA, 0.12, -0.2, 0.008), P["orange"]),   # pectoral
                                    ([[0.08, -0.37], [-0.08, -0.5], [0.0, -0.36]], 0.05, P["orange"])):                               # pelvic
            add.mesh(add.make(add.prism, profile, 0.015, colour, (0, 0, sz * z0), (0, 0, 1)))
    for profile, colour, t in (([[0.08, 0.4], [-0.04, 0.63], [-0.16, 0.62], [-0.2, 0.38]], P["iron"], 0.02),      # dorsal fin,
                               ([[-0.44, 0.17], [-0.47, 0.25], [-0.53, 0.24], [-0.52, 0.13]], P["iron"], 0.02),   # adipose fin,
                               ([[-0.1, -0.38], [-0.42, -0.19], [-0.44, -0.3], [-0.2, -0.52]], P["red"], 0.02),   # anal fin
                               ([[-0.58, 0.07], [-0.72, 0.01], [-0.9, 0.36]], P["iron"], 0.03),                   # and the two
                               ([[-0.58, -0.07], [-0.9, -0.36], [-0.72, -0.01]], P["iron"], 0.03),                # lobes of the
                               ([[-0.6, -0.12], [-0.64, -0.13], [-0.64, 0.13], [-0.6, 0.12]], P["black"], 0.045)): # tail, dark at its base
        add.mesh(add.make(add.prism, profile, t, colour, (0, 0, 0), (0, 0, 1)))
    M = add.rotateZ(add.stretch(add.pop(), [s] * 3, (0, 0, 0)), pitch)
    add.mesh(add.move(add.rotateY(M, facing), at))


LEAPS = ((-16.4, 58.6, 1.2, 0.6), (-9.6, 57.2, 1.75, 0.5), (-4.6, 60.4, 0.3, 0.8),      # piranhas leaping out of the
         (4.4, 59.6, 2.7, -0.5), (10.4, 57.4, -2.2, 0.6), (16.6, 60.2, -1.0, 0.35))       # moat, along it: x, z, way, pitch
shoal = []                                             # and under the water, spread evenly all over it from end to end:
PIRANHA_STEP = 2.6                                     # one in each cell of a grid (at a random spot in it), at all
for i in range(int(-22 // PIRANHA_STEP), int(22 // PIRANHA_STEP) + 1):   # depths but the bottom, circling round and round,
    for j in range(int(52 // PIRANHA_STEP), int(65 // PIRANHA_STEP) + 1):   # jaws open -- clear of the walls, the bank,
        if hash2(i, j, 130) > max(DENSITY, 0.3):                           # the leaping ones and each other
            continue
        x = (i + 0.2 + 0.6 * hash2(i, j, 131)) * PIRANHA_STEP
        z = (j + 0.2 + 0.6 * hash2(i, j, 132)) * PIRANHA_STEP
        y, size = MOAT_WATER - 0.75 - 2.0 * hash2(i, j, 133) ** 1.5, 0.6 + 0.15 * hash2(i, j, 134)   # (fins under the surface)
        if not in_moat_outline(x, z) or castle_depth(x, z) > -0.9 or landing_depth(x, z) > -0.8 or bank_gap(x, z) < 1.1:
            continue
        if any((x - q[0]) ** 2 + (y - q[1]) ** 2 + (z - q[2]) ** 2 < 1.3 ** 2 for q in shoal) or \
                any((x - q[0]) ** 2 + (z - q[1]) ** 2 < 1.8 ** 2 for q in LEAPS):
            continue
        d = add.atan2(z - 59.8, x) + add.pi / 2 + (hash2(i, j, 135) - 0.5) * 1.2                  # round and round
        piranha([x, y, z], -d, size, (hash2(i, j, 136) - 0.5) * 0.4, 0.18 + 0.15 * hash2(i, j, 137))
        shoal.append((x, y, z))
for x, z, d, pitch in LEAPS:
    assert in_moat_outline(x, z) and castle_depth(x, z) < -2 and landing_depth(x, z) < -2 and bank_gap(x, z) > 1.4 and abs(x) > DECK + 2
    y = MOAT_WATER + (0.6 if pitch > 0 else 0.4)                                                # jaws agape, rings
    piranha([x, y, z], -d, 0.75, pitch, 0.4)                                                    # where they broke
    add.torus([x - 0.45 * add.cos(d), MOAT_WATER + 0.01, z - 0.45 * add.sin(d)], 0.5, 0.035, 16, 4, P["white"])   # the
    for j in range(6):                                                                          # surface and drops
        a = j * 1.05 + d                                                                        # flying
        add.sphere([x + 0.55 * add.cos(a), MOAT_WATER + 0.12 + 0.15 * (j % 3), z + 0.55 * add.sin(a)], 0.04, 2, P["white"])
flush("piranhas in the moat (%d)" % (len(shoal) + len(LEAPS)))


LEAF_FILL = 1.4                                                         # how thick the single leaves stand out of the foliage:
                                                                        # 1 -- half as many as at first, a quarter longer (as from v10
                                                                        # on, to keep the archive small); 2 -- as many and as long as
                                                                        # at first; 1.4 -- 40 % more than 1, 12 % longer than at
                                                                        # first (the castle.obj archive still under 100 MiB)


def leafy(M, amp_side, amp_top, seed, cell=0.13, greens=("leaf_dark", "oak_leaf", "leaf_dark", "leaf", "oak_leaf"),
          dark=("needles", "leaf_dark"), jitter=0.025, sprigs=0.0, leaf=0.05, wide=0.3, lean=(0.35, 0.95), box=None,
          tint=("leaf", "oak_leaf", "leaf", "grass", "leaf_dark"), floor=0.08):
    """Clip a hedge or a topiary into leaves: every vertex of the welded mesh
    ``M`` is moved a little sideways (``jitter``) and pushed out or in along
    its normal by the tufts of foliage -- clusters round points scattered
    one to a ``cell`` of space, each one swelling out between the creases
    where it meets the next -- ``amp_side`` on the sides, ``amp_top`` on a
    flat clipped top (faces looking up); every face takes its tuft's green
    (or now and then another of the ``greens``), one of the ``dark`` ones
    down in a crease.  ``sprigs`` leaves a square metre stand out of it
    -- new shoots since the last clipping -- ``leaf`` long, ``wide`` times
    as wide at the foot, leaning ``lean`` (radians) off the normal, in the
    colours ``tint``, drawn at once (none lower than ``floor``, nor
    reaching out of ``box``, (x0, x1, z0, z1)).  Returns ``M``, changed."""
    F, C = [], []
    for f, col in zip(M.F, M.C):                                        # (in triangles: a quad pushed out of its plane
        for t in range(1, len(f) - 1):                                  # would be drawn one way or the other)
            F.append([f[0], f[t], f[t + 1]])
            C.append(col)
    M.F, M.C = F, C
    pts = {}

    def tuft(p):                                                        # (how far from a crease 0..1, which tuft 0..1)
        gx, gy, gz = p[0] / cell, p[1] / cell, p[2] / cell
        ix, iy, iz = int(add.floor(gx)), int(add.floor(gy)), int(add.floor(gz))
        d1 = d2 = 9.0
        best = 0.0
        for a in (ix - 1, ix, ix + 1):
            for b in (iy - 1, iy, iy + 1):
                for c in (iz - 1, iz, iz + 1):
                    q = pts.get((a, b, c))
                    if q is None:
                        key = a * 7919 + c * 104729
                        q = pts[(a, b, c)] = (a + hash2(key, b, seed), b + hash2(key, b, seed + 1), c + hash2(key, b, seed + 2),
                                              hash2(key, b, seed + 3))
                    dd = (gx - q[0]) ** 2 + (gy - q[1]) ** 2 + (gz - q[2]) ** 2
                    if dd < d1:
                        d1, d2, best = dd, d1, q[3]
                    elif dd < d2:
                        d2 = dd
        return min(1.0, 1.6 * (add.sqrt(d2) - add.sqrt(d1))), best

    N = [[0.0, 0.0, 0.0] for _ in M.V]                                  # the vertex normals, from the faces round them
    for f in M.F:
        a = M.V[f[0]]
        for t in range(1, len(f) - 1):
            n = vcross(vsub(M.V[f[t]], a), vsub(M.V[f[t + 1]], a))
            for k in (f[0], f[t], f[t + 1]):
                N[k] = [N[k][0] + n[0], N[k][1] + n[1], N[k][2] + n[2]]
    bump = []
    for i, p in enumerate(M.V):
        n = vunit(N[i])
        b = tuft(p)[0]
        bump.append(b)
        amp = (amp_side + (amp_top - amp_side) * add.clamp((n[1] - 0.55) / 0.35)) * (add.sqrt(b) - 0.6)
        j = [jitter * (hash2(i, k, seed + 5) - 0.5) for k in range(3)]
        jn = j[0] * n[0] + j[1] * n[1] + j[2] * n[2]
        M.V[i] = [p[k] + n[k] * amp + j[k] - n[k] * jn for k in range(3)]
    for j, f in enumerate(M.F):
        b = sum(bump[k] for k in f) / len(f)
        u = hash2(j, seed, 7)
        if b < 0.28 or u < 0.06:
            M.C[j] = add.rgb(P[dark[int(u * 97) % len(dark)]])
        else:
            w = tuft([sum(M.V[k][a] for k in f) / len(f) for a in range(3)])[1] if u < 0.72 else u
            M.C[j] = add.rgb(P[greens[int(w * len(greens) * 13) % len(greens)]])
    if sprigs > 0:
        LM = add.Mesh()                                                 # (all of them, one mesh)
        for j, f in enumerate(M.F):                                     # single leaves standing out of it
            a, b, c = M.V[f[0]], M.V[f[1]], M.V[f[2]]
            n = vcross(vsub(b, a), vsub(c, a))
            area = vlen(n) / 2
            if area < 1e-9 or (a[1] + b[1] + c[1]) / 3 < floor + 0.02:
                continue
            n = vunit(n)
            for s in range(int(area * sprigs * 0.5 * LEAF_FILL + hash2(j, seed, 11))):   # (see LEAF_FILL)
                u, v = hash2(j, s, seed + 12), hash2(j, s, seed + 13)
                if u + v > 1:
                    u, v = 1 - u, 1 - v
                p = [a[k] + (b[k] - a[k]) * u + (c[k] - a[k]) * v for k in range(3)]
                t = vunit(vcross(n, [hash2(j, s, seed + 14) - 0.5, hash2(j, s, seed + 15) - 0.5, hash2(j, s, seed + 16) - 0.5]))
                th = lean[0] + (lean[1] - lean[0]) * hash2(j, s, seed + 17)   # (leaning off the normal)
                d = [n[k] * add.cos(th) + t[k] * add.sin(th) for k in range(3)]
                w = vunit(vcross(d, n))
                L = 1.25 / LEAF_FILL ** 0.32 * leaf * (0.7 + 0.6 * hash2(j, s, seed + 18))
                p = [p[k] - d[k] * 0.008 for k in range(3)]              # (its foot in the leaves)
                tip = [p[k] + d[k] * L for k in range(3)]
                if tip[1] < floor or (box and not (box[0] < tip[0] < box[1] and box[2] < tip[2] < box[3])):
                    continue
                lens_leaf(LM, p, d, w, L, wide * L, P[tint[int(hash2(j, s, seed + 19) * len(tint)) % len(tint)]])
        add.mesh(LM)
    return M




def bark_trunk(pts, radii, k, seed, colours=("trunk", "wood_dark"), marks=False, moss=False):
    """A trunk along the polyline ``pts`` (``radii`` round at its points)
    in rings of furrowed bark a hand or so apart, ``k`` ridges round it
    winding a little up it -- all of one piece from end to end: where it
    bends, and where its foot runs on down into the ground, the rings and
    the ridges run on, no step, no turn -- its faces in the ``colours`` by
    turns, grey lichen here and there, and with ``moss`` patches of moss
    round its foot; or, with ``marks`` (a birch), white with bands of
    black."""
    segs = list(zip(pts, pts[1:]))
    dirs = [vunit(vsub(b, a)) for a, b in segs]
    stations = []                                                       # (segment, t): every point of it, and
    for si, (a, b) in enumerate(segs):                                  # between them about every 0.45 m
        n = max(1, int(round(vlen(vsub(b, a)) / 0.45)))
        stations += [(si, i / float(n)) for i in range(n)]
    stations.append((len(segs) - 1, 1.0))
    M = add.Mesh()
    rings = []
    for i, (si, t) in enumerate(stations):
        a, b = segs[si]
        c = [a[m] + (b[m] - a[m]) * t for m in range(3)]
        r = radii[si] + (radii[si + 1] - radii[si]) * t
        d = vunit([dirs[si][m] + dirs[si - 1][m] for m in range(3)]) if (t == 0.0 and si > 0) else dirs[si]   # (at a bend,
        u = vunit(vcross(d, [0, 0, 1] if abs(d[1]) > 0.9 else [0, 1, 0]))                                    #  halfway)
        w = vcross(d, u)
        ring = []
        for j in range(k):
            f = 2 * add.pi * j / k + 0.1 * i
            rr = r * (1.0 + (0.08 if j % 2 else -0.06) + 0.05 * (hash2(i, j, seed + 141) - 0.5))
            ring.append(M.add_vertex([c[m] + rr * (u[m] * add.cos(f) + w[m] * add.sin(f)) for m in range(3)]))
        rings.append(ring)
    for i in range(len(rings) - 1):
        band = marks and hash2(i, 0, seed + 143) < 0.3
        for j in range(k):
            if marks:
                col = P["black"] if band or hash2(i, j, seed + 144) < 0.08 else P["white"]
            else:
                col = P[colours[j % len(colours)]] if hash2(i, j, seed + 142) > 0.1 else P["rock"]
                if moss and i < 3 and hash2(i, j, seed + 145) < (0.6, 0.5, 0.25)[i]:
                    col = P["moss"]
            M.add_face([rings[i][j], rings[i][(j + 1) % k], rings[i + 1][(j + 1) % k], rings[i + 1][j]], col)
    M.add_face(rings[0][::-1], P[colours[0]] if not marks else P["white"])
    M.add_face(rings[-1], P[colours[0]] if not marks else P["white"])
    add.mesh(add.fix_normals(M))


# the forest on the slopes: low-poly trees of the northern woods, each species by its shape, growing in stands of one
# kind -- spruces narrow and dark in tiers of drooping branches, star-shaped from above and bare for a man's height;
# pines tall and straight, orange-red from the foot up, a few branches up top in flat bunches of needles; birches
# white and slender with black marks; oaks short and thick on crooked limbs under a broad crown; elms rising like a
# vase; limes round and dense.  Every limb runs from inside its trunk into a bunch of leaves, and every trunk ends inside
# its crown.  CROWN: how far a crown reaches out from its trunk, TRUNK: the trunk's radius at the ground -- in heights
CROWN = {"spruce": 0.41, "pine": 0.44, "birch": 0.3, "oak": 0.6, "elm": 0.5, "lime": 0.46}
TRUNK = {"spruce": 0.036, "pine": 0.046, "birch": 0.03, "oak": 0.1, "elm": 0.055, "lime": 0.055}
LEAVES = {"pine": ("needles", "leaf_dark", "needles", "needles_light"),                       # the greens of each kind
          "birch": ("birch_leaf", "grass", "birch_leaf", "leaf_light", "birch_leaf", "grass", "birch_leaf", "leaf_yellow"),
          "oak": ("oak_leaf", "leaf_dark", "leaf", "oak_leaf", "leaf_light"),                  # (and every tree a little lighter
          "elm": ("elm_leaf", "leaf", "elm_leaf", "leaf_dark", "grass"),                       #  or darker than the next: see
          "lime": ("lime_leaf", "leaf", "lime_leaf", "leaf_light", "leaf_dark", "lime_leaf", "grass", "leaf_yellow")}   # forest_tree)
BARKS = {"pine": ("bark_red", "wood_light"), "oak": ("bark_grey", "bark_dark"), "elm": ("trunk", "bark_grey", "bark_dark"),
         "lime": ("bark_grey", "bark_grey", "trunk")}                    # (the colours of each kind's bark, by turns)


def in_bark(M, colours, seed, marks=False, lichen=0.1):
    """``M`` -- a limb, a twig, a knot -- in the bark of its trunk (see
    bark_trunk): its faces in the ``colours`` by turns, grey lichen on
    ``lichen`` of them; or, with ``marks`` (a birch's), white with black."""
    for i in range(len(M.F)):
        if marks:
            M.C[i] = add.rgb(P["black"] if hash2(i, 0, seed + 144) < 0.12 else P["white"])
        else:
            M.C[i] = add.rgb(P[colours[i % len(colours)]] if hash2(i, 0, seed + 142) > lichen else P["rock"])
    return M


def forest_tree(at, h, kind, seed, bury=True):
    """A tree ``h`` tall of the given species, its foot at ``at``; returns
    how high over the foot the lowest of its leaves hang.  With ``bury``
    its trunk runs on down, the way it leans, until it is in the ground
    all round -- on a slope too."""
    x, y, z = at
    rnd = lambda j: hash2(seed, j, 41)
    low = [h]

    def rooted(pts, radii):                                               # the trunk's line and its radii, run on
        if not bury:                                                      # from the foot down into the ground (the
            return pts, radii                                             # way it leans), as the same trunk
        r = radii[0]
        deep = min(ground(x + (r + 0.05) * add.cos(a), z + (r + 0.05) * add.sin(a)) for a in (i * add.pi / 6 for i in range(12))) - 0.15
        if deep >= y:
            return pts, radii
        d = vunit(vsub(pts[1], pts[0]))
        return [[x - d[0] * (y - deep) / d[1], deep, z - d[2] * (y - deep) / d[1]]] + pts, [r] + radii

    tone = ("needles_light", None)[seed % 2] if kind == "pine" else ("leaf_light", "leaf_dark", None)[seed % 3]
    barks, nb = BARKS.get(kind, ("trunk",)), [0]                          # (the limbs, the knots and the twigs all in
                                                                          #  the trunk's own bark: see in_bark)
    def wood(M):
        nb[0] += 1
        add.mesh(in_bark(M, barks, seed * 53 + 11 * nb[0], kind == "birch"))

    def blob(c, r, st, j):                                                # a bunch of leaves: three masses of
        greens = LEAVES[kind] + ((tone, tone) if tone else ())            # foliage round the end of the twigs
        subs = [(c, 0.72)]                                                # that part there, each clipped into
        for m in range(2):                                                # tufts, single leaves (or sprays of
            a = 6.2832 * rnd(900 + 7 * j + m) + m * add.pi                # needles) standing out of it all round
            e = 0.5 * rnd(910 + 7 * j + m) - 0.1
            sc = [c[0] + 0.5 * r * st[0] * add.cos(a), c[1] + e * r * st[1], c[2] + 0.5 * r * st[2] * add.sin(a)]
            subs.append((sc, 0.56))
            wood(add.make(add.frustum, c, sc, 0.004 * h, 0.002 * h, 4))  # (the twig out to it)
        for m, (sc, f) in enumerate(subs):
            rr = r * f
            B = add.stretch(add.make(add.sphere, [0, 0, 0], 1.0, 4, P[greens[0]]), [rr * st[0], rr * st[1], rr * st[2]], (0, 0, 0))
            B = leafy(add.move(B, sc), 0.1 * rr, 0.1 * rr, seed * 37 + 3 * j + m, 0.3 * rr, greens,
                      ("leaf_dark",) if kind != "pine" else ("needles",), 0.05 * rr,
                      32.0 / (4 * add.pi * rr * rr * st[0] * st[2]) * (1.4 if kind == "birch" else 1.0),
                      0.1 + 0.08 * rr, 0.35 if kind == "pine" else 0.45, (0.55, 1.2), None, greens)
            add.mesh(B)
            low[0] = min(low[0], min(v[1] for v in B.V) - 0.2 - 0.1 * rr - y)

    def limb(a, b, r0, r1):
        wood(add.make(add.frustum, a, b, r0, r1, 6))

    def knot(c, r):                                                       # where a limb bends
        wood(add.make(add.sphere, c, r * 1.3, 2))

    if kind == "spruce":
        n, s, R0 = 9, 0.5, 0.34 * h                                       # tiers, their droop (per metre out), the reach
        up = max(0.0, max(ground(x + R0 * add.cos(a), z + R0 * add.sin(a)) - (y + 0.2) for a in (k * add.pi / 4 for k in range(8))))
        base, top = 1.4 + up, 0.82 * h                                    # the lowest tips a man's height over the ground
        step = (top - base) / (n - 1)
        K, rl = 16, 0.03 * h                                              # (sixteen sides to all of it; the leader's foot)
        rt = lambda yy: (0.036 + (0.01 - 0.036) * (yy - y) / (0.84 * h)) * h   # the trunk's radius at the height yy
        around = lambda r, yy: [[x + r * add.cos(2 * add.pi * j / K), yy, z + r * add.sin(2 * add.pi * j / K)] for j in range(K)]

        def solid_of(rings, cols, cap0, cap1, flat=()):                   # a closed solid from rings of K points, bottom
            M = add.Mesh()                                                # to top: the band between each two (in
            ids = [[M.add_vertex(p) for p in ring] for ring in rings]    # triangles, or quads where ``flat``), the caps
            for q, ((a_, b_), col) in enumerate(zip(zip(ids, ids[1:]), cols)):
                for j in range(K):
                    if q in flat:
                        M.add_face([a_[j], a_[(j + 1) % K], b_[(j + 1) % K], b_[j]], col)
                    else:
                        M.add_face([a_[j], a_[(j + 1) % K], b_[(j + 1) % K]], col)
                        M.add_face([a_[j], b_[(j + 1) % K], b_[j]], col)
            M.add_face(ids[0][::-1], cap0)
            M.add_face(ids[-1], cap1)
            return add.fix_normals(M)
        deep = y                                                          # the trunk on down into the ground (see rooted)
        if bury:
            deep = min(y, min(ground(x + (rt(y) + 0.05) * add.cos(a), z + (rt(y) + 0.05) * add.sin(a))
                              for a in (i * add.pi / 6 for i in range(12))) - 0.15)
        tiers, below = [], y
        for i in range(n):                                                # each tier a solid of its own: its sixteen
            yr = base + step * i                                          # points -- eight branches, the notches
            R = R0 * (h - yr) / (h - base) * (0.92 + 0.16 * rnd(i))       # between them -- drooping, s per metre out,
            apex = y + yr + s * R                                         # its top sloping down to them from the trunk
            m = int(rnd(10 + i) * K)                                      # (turned by sixteenths, so that its points
            rim = [R * (0.9 + 0.2 * rnd(20 + 16 * i + j)) if (j - m) % 2 == 0 else 0.7 * R for j in range(K)]   # and the trunk's
            ri = rl if i == n - 1 else rt(apex)                           # sides agree), under it a face parallel
            for _ in range(3):                                            # to the top, c lower by the trunk and dt at
                ri = rl if i == n - 1 else rt(apex - s * ri)             # the points' ends: every point a wedge with
            y_top = apex - s * ri                                         # a face of its own at the end; flat round
            c, dt = 0.4 * step, 0.24 * step                               # the trunk above and below, where the pieces
            c = max(dt + 0.05, min(c, apex - s * rt(apex - c) - (below + 0.05)))   # of the trunk stand on it and end
            rb = rt(apex - c)                                             # under it (and never down into the tier
            for _ in range(3):                                            # below)
                rb = rt(apex - c - s * rb)
            y_bot = apex - c - s * rb
            tiers.append((y_bot, y_top, rb, ri))
            below = y_top
            col = P["needles_light"] if i >= n - 2 else P["needles"] if i % 3 else P["leaf_dark"]   # (fresh at the top)
            TR = [[x + r * add.cos(2 * add.pi * j / K), apex - s * r, z + r * add.sin(2 * add.pi * j / K)] for j, r in enumerate(rim)]
            BR = [[p[0], p[1] - dt, p[2]] for p in TR]
            add.mesh(solid_of([around(rb, y_bot), BR, TR, around(ri, y_top)], [P["needles"], P["needles"], col], P["trunk"], col, (1,)))
            low[0] = min(low[0], min(p[1] for p in BR) - y)
        pieces = [(deep, tiers[0][0])] + [(tiers[i][1], tiers[i + 1][0]) for i in range(n - 1)]
        for y0_, y1_ in pieces:                                           # the trunk between the tiers, sixteen-sided,
            add.mesh(solid_of([around(rt(max(y0_, y)), y0_), around(rt(y1_), y1_)], [P["trunk"]], P["trunk"], P["trunk"], (0,)))
        M = add.Mesh()                                                    # and the leader on the top tier
        tip = M.add_vertex([x, y + h, z])
        foot = [M.add_vertex(p) for p in around(rl, tiers[-1][1])]
        for j in range(K):
            M.add_face([foot[j], foot[(j + 1) % K], tip], P["needles_light"])
        M.add_face(foot[::-1], P["needles_light"])
        add.mesh(add.fix_normals(M))
    elif kind == "pine":
        lx, lz = (rnd(1) - 0.5) * 0.12 * h, (rnd(2) - 0.5) * 0.12 * h    # a slight lean

        def on(t):                                                        # the point of the trunk's axis at t heights
            f = 0.5 * t / 0.55 if t <= 0.55 else 0.5 + 0.5 * (t - 0.55) / 0.35
            return [x + lx * f, y + t * h, z + lz * f]
        bark_trunk(*rooted([[x, y, z], on(0.55), on(0.9)], [0.046 * h, 0.034 * h, 0.014 * h]), 8, seed,   # (one bark from
                   barks)                                                                               #  the foot to the top)
        for j in range(3):                                                # dead stubs low down
            a, p0 = rnd(10 + j) * 6.28, on(0.32 + 0.08 * j)
            wood(add.make(add.cylinder, p0, [p0[0] + 0.1 * h * add.cos(a), p0[1] + 0.02 * h, p0[2] + 0.1 * h * add.sin(a)], 0.006 * h, 4))
        for j in range(6):                                                # branches up top, rising, each to its bunches
            a, p0 = j * 2.4 + rnd(20 + j), on(0.6 + 0.045 * j)
            L = (0.24 - 0.1 * j / 5.0 + 0.03 * rnd(30 + j)) * h
            e = [p0[0] + L * add.cos(a), p0[1] + 0.45 * L, p0[2] + L * add.sin(a)]
            limb(p0, e, 0.012 * h, 0.006 * h)
            blob(e, (0.09 + 0.03 * rnd(40 + j)) * h, [1.0, 0.45, 1.0], j)
            blob([p0[k] + 0.55 * (e[k] - p0[k]) for k in range(3)], 0.06 * h, [1.0, 0.5, 1.0], j + 1)
        blob(on(0.9), 0.1 * h, [1.0, 0.55, 1.0], 0)                      # and the top
    elif kind == "birch":
        for k in range(2 if seed % 3 == 0 else 1):                       # one stem or two
            a = rnd(60 + k) * 6.28
            lean = 0.06 * h * (1 + k)
            top = [x + lean * add.cos(a), y + 0.88 * h, z + lean * add.sin(a)]
            at_t = lambda t: [x + (top[0] - x) * t, y + (top[1] - y) * t, z + (top[2] - z) * t]
            bark_trunk(*rooted([[x, y, z], top], [0.03 * h, 0.01 * h]), 8, seed + k, marks=True)   # white, with black marks
            for j in range(4):                                            # thin branches rising to bunches of leaves
                b, p0 = a + j * 2.1 + rnd(90 + j + 9 * k), at_t(0.5 + 0.12 * j)
                L = 0.12 * h * (1 - 0.15 * j)
                e = [p0[0] + L * add.cos(b), p0[1] + 0.8 * L, p0[2] + L * add.sin(b)]
                limb(p0, e, 0.008 * h, 0.004 * h)
                blob(e, (0.085 + 0.03 * rnd(95 + j + 9 * k)) * h, [0.9, 1.3, 0.9], j)
            for j in range(3):                                            # the narrow crown round the top of the stem
                c = at_t(0.7 + 0.13 * j)
                blob([c[0] + (rnd(100 + j + 9 * k) - 0.5) * 0.06 * h, c[1], c[2] + (rnd(105 + j + 9 * k) - 0.5) * 0.06 * h],
                     (0.1 - 0.012 * j) * h, [0.85, 1.35, 0.85], j + 1)
            blob(top, 0.07 * h, [0.9, 1.3, 0.9], 0)
    elif kind == "oak":
        bark_trunk(*rooted([[x, y, z], [x, y + 0.1 * h, z], [x, y + 0.8 * h, z]], [0.1 * h, 0.075 * h, 0.02 * h]), 12, seed,   # flaring
                   barks, moss=True)
                                                                                                                              # at the foot
        for j in range(5):                                                # five crooked limbs
            a, t = (j + 0.6 * rnd(100 + j)) * 2 * add.pi / 5, 0.3 + 0.05 * j
            p0 = [x, y + t * h, z]
            e1 = [x + 0.17 * h * add.cos(a), y + (t + 0.14) * h, z + 0.17 * h * add.sin(a)]
            a2 = a + (rnd(105 + j) - 0.5) * 0.9
            e2 = [e1[0] + 0.16 * h * add.cos(a2), y + (t + 0.3) * h, e1[2] + 0.16 * h * add.sin(a2)]
            limb(p0, e1, 0.04 * h, 0.03 * h)
            knot(e1, 0.03 * h)
            limb(e1, e2, 0.03 * h, 0.018 * h)
            blob(e2, (0.17 + 0.05 * rnd(120 + j)) * h, [1.15, 0.75, 1.15], j)
            blob([(e1[0] + e2[0]) / 2, (e1[1] + e2[1]) / 2 + 0.05 * h, (e1[2] + e2[2]) / 2], 0.13 * h, [1.1, 0.8, 1.1], j + 1)
        blob([x, y + 0.8 * h, z], 0.2 * h, [1.2, 0.75, 1.2], 0)
        for j in range(3):
            a = rnd(130 + j) * 6.28
            blob([x + 0.15 * h * add.cos(a), y + 0.78 * h, z + 0.15 * h * add.sin(a)], 0.15 * h, [1.1, 0.8, 1.1], j + 2)
    elif kind == "elm":
        bark_trunk(*rooted([[x, y, z], [x, y + 0.88 * h, z]], [0.055 * h, 0.012 * h]), 10, seed, barks, moss=True)   # deeply
                                                                                                                               # furrowed
        for j in range(4):                                                # stems parting low, rising apart like a vase
            a = (j + 0.5 * rnd(140 + j)) * add.pi / 2
            p0 = [x, y + (0.28 + 0.03 * j) * h, z]
            e1 = [x + 0.12 * h * add.cos(a), y + 0.55 * h, z + 0.12 * h * add.sin(a)]
            e2 = [x + 0.26 * h * add.cos(a), y + 0.74 * h, z + 0.26 * h * add.sin(a)]
            limb(p0, e1, 0.03 * h, 0.024 * h)
            knot(e1, 0.024 * h)
            limb(e1, e2, 0.024 * h, 0.014 * h)
            blob([e2[0], e2[1] + 0.05 * h, e2[2]], 0.19 * h, [1.15, 0.7, 1.15], j)
            blob([e1[0] + 0.06 * h * add.cos(a), e1[1] + 0.08 * h, e1[2] + 0.06 * h * add.sin(a)], 0.12 * h, [1.1, 0.8, 1.1], j + 1)
        blob([x, y + 0.88 * h, z], 0.22 * h, [1.2, 0.6, 1.2], 0)
    else:                                                                 # a lime
        bark_trunk(*rooted([[x, y, z], [x, y + 0.78 * h, z]], [0.055 * h, 0.018 * h]), 10, seed, barks, moss=True)
        for j in range(5):
            a, t = (j + 0.5 * rnd(150 + j)) * 2 * add.pi / 5, 0.38 + 0.04 * j
            p0 = [x, y + t * h, z]
            e = [x + 0.22 * h * add.cos(a), y + (t + 0.25) * h, z + 0.22 * h * add.sin(a)]
            limb(p0, e, 0.025 * h, 0.012 * h)
            blob(e, (0.16 + 0.04 * rnd(160 + j)) * h, [1.0, 0.85, 1.0], j)
        for j in range(4):
            a = (j + 0.5) * add.pi / 2 + rnd(170 + j)
            blob([x + 0.13 * h * add.cos(a), y + (0.74 + 0.05 * rnd(180 + j)) * h, z + 0.13 * h * add.sin(a)],
                 0.17 * h, [1.0, 0.9, 1.0], j + 1)
        blob([x, y + 0.8 * h, z], 0.2 * h, [1.0, 0.9, 1.0], 0)
    return low[0]


def stand(x, z, pitch=14.0):
    """A number in 0..1, the same all over the stand of trees (x, z) is in:
    the stands are the cells round points scattered a ``pitch`` apart."""
    gx, gz, best = int(x // pitch), int(z // pitch), None
    for i in range(gx - 1, gx + 2):
        for j in range(gz - 1, gz + 2):
            d = (x - (i + hash2(i, j, 45)) * pitch) ** 2 + (z - (j + hash2(i, j, 46)) * pitch) ** 2
            if best is None or d < best[0]:
                best = (d, i, j)
    return hash2(best[1], best[2], 47)


def species(x, z, n):
    """Which tree grows at (x, z): stands of pines and oaks up on the dry brow of the hill, of spruces, birches, elms
    and limes lower down, of birches and elms by the water -- and here and there a tree of another kind among them."""
    r = add.sqrt(x * x + z * z)
    kinds = (("pine", "oak", "birch", "pine", "lime") if r < 69 else
             ("spruce", "birch", "spruce", "oak", "elm", "spruce", "lime", "pine") if r < 81 else
             ("birch", "spruce", "elm", "spruce", "birch", "lime"))
    u = hash2(n, 4, 43) if hash2(n, 3, 43) < 0.12 else stand(x, z)
    return kinds[int(u * len(kinds)) % len(kinds)]


HEIGHT = {"spruce": (6, 11), "pine": (8, 12), "birch": (6, 10), "oak": (6, 9), "elm": (8, 12), "lime": (5, 9)}
add.seed(11)
TREES = []                                             # where they stand: x, z, height, kind, reach, how low their leaves are
_tree_cells = {}                                       # (a grid of 6 m cells: the trees in each)


def trees_near(x, z):
    """The trees whose trunks stand within 12 m or so of (x, z)."""
    i, j = int(x // 6), int(z // 6)
    return [TREES[k] for a in range(i - 2, i + 3) for b in range(j - 2, j + 3) for k in _tree_cells.get((a, b), ())]


tries = 0
while len(TREES) < count(300) and tries < 40000:
    tries += 1
    a, r = add.uniform(0, 2 * add.pi), add.uniform(60, 90)
    x, z = r * add.cos(a), r * add.sin(a)
    if on_road(x, z, 5.0) or by_jetty(x, z, 3.0):      # keep the road and the harbour clear,
        continue
    y = ground(x, z)
    if y < WATER_Y + 1.5:
        continue
    kind = species(x, z, len(TREES))
    h = add.uniform(*HEIGHT[kind])
    reach = CROWN[kind] * h                            # the crowns clear of the walls, the towers and their roofs and
    if octagon_r(x, z) < 52.0 + reach or near_corner(x, z, 1.4 + reach) or by_terrace(x, z, reach + 0.5):   # the moat,
        continue
    if any((x - t[0]) ** 2 + (z - t[1]) ** 2 < (0.45 * (reach + t[4])) ** 2 for t in trees_near(x, z)):   # and apart
        continue
    low = forest_tree([x, y - 0.2, z], h, kind, len(TREES))
    _tree_cells.setdefault((int(x // 6), int(z // 6)), []).append(len(TREES))
    TREES.append((x, z, h, kind, reach, y - 0.2 + low))
    if len(TREES) % 150 == 0:
        flush("forest (%d trees)" % len(TREES), clean=False)
flush("forest", clean=False)


def mushroom(at, kind, s=1.0):
    """A mushroom standing on the ground at ``at``: a fly agaric (a red cap
    with white warts), a cep (a fat pale stem, a brown cap) or a
    chanterelle (a little orange funnel)."""
    x, y, z = at
    if kind == "agaric":
        add.cylinder([x, y - 0.03, z], [x, y + 0.2 * s, z], 0.025 * s, 8, P["white"])
        add.mesh(add.move(add.stretch(add.make(add.hemisphere, [0, 0, 0], 0.11 * s, 4, P["red"]), [1.0, 0.65, 1.0], (0, 0, 0)),
                          [x, y + 0.19 * s, z]))
        for j in range(5):                                                    # the white warts
            a, t = j * 2.4, 0.3 + 0.45 * hash2(j, int(x * 10), 31)
            add.cuboid([x + 0.11 * s * t * add.cos(a), y + 0.19 * s + 0.0715 * s * add.sqrt(1 - t * t),
                        z + 0.11 * s * t * add.sin(a)], [0.022 * s, 0.014 * s, 0.022 * s], P["white"])
    elif kind == "cep":
        lathe([[0.0, -0.03], [0.04, -0.03], [0.05, 0.06], [0.035, 0.15], [0.0, 0.15]], [x, y, z], 10, P["linen"], s)
        add.mesh(add.move(add.stretch(add.make(add.hemisphere, [0, 0, 0], 0.1 * s, 4, P["bread"]), [1.0, 0.7, 1.0], (0, 0, 0)),
                          [x, y + 0.14 * s, z]))
    else:
        lathe([[0.0, -0.02], [0.015, -0.02], [0.02, 0.06], [0.06, 0.1], [0.05, 0.11], [0.0, 0.085]], [x, y, z], 10, P["orange"], s)


add.seed(12)                                           # mushrooms in the forest: fewer than the fish,
mushrooms = 0                                          # in little groups round the trees, clear of their trunks and
MUSHROOMS = []                                         # of each other (where they stand: the grass keeps clear of them)
MUSHROOM_KINDS = []                                    # (and what each is, and how big)
while mushrooms < count(300):
    tx, tz, th, tk = TREES[int(add.random() * len(TREES)) % len(TREES)][:4]
    a, d = add.uniform(0, 2 * add.pi), add.uniform(0.7, 0.8 + 0.25 * th) + TRUNK[tk] * th
    x, z = tx + d * add.cos(a), tz + d * add.sin(a)
    kind = add.choice(["agaric", "cep", "cep", "chanterelle"])
    group = [(x + add.uniform(-0.3, 0.3), z + add.uniform(-0.3, 0.3), add.uniform(0.7, 1.3)) for j in range(3)]
    if on_road(x, z, 3.0) or by_terrace(x, z, 2.0) or by_jetty(x, z, 2.0) or ground(x, z) < WATER_Y + 1.2:
        continue
    kept = []
    for gx, gz, gs in group[:1 + mushrooms % 3]:
        if all((gx - t[0]) ** 2 + (gz - t[1]) ** 2 > (TRUNK[t[3]] * t[2] + 0.4) ** 2 for t in trees_near(gx, gz)) and \
                all((gx - mx) ** 2 + (gz - mz) ** 2 > 0.42 ** 2 for mx, mz in MUSHROOMS + [q[:2] for q in kept]):
            kept.append((gx, gz, gs))
    if not kept:
        continue
    for gx, gz, gs in kept:
        mushroom([gx, ground(gx, gz), gz], kind, gs * (1.6 if kind == "chanterelle" else 1.3))
        MUSHROOMS.append((gx, gz))
        MUSHROOM_KINDS.append((kind, gs * (1.6 if kind == "chanterelle" else 1.3)))
    mushrooms += 1
flush("mushrooms (%d)" % mushrooms, clean=False)

# the meadows: grass over all the green land outside the walls -- from the foot of the walls and the towers down to
# the sand of the shore, on the terrace, on the banks of the road, among the trees -- and on the earth of the yard.  A
# tuft of thin solid blades grows in every cell of a fine grid, at a random spot in it, but for a few cells left bare:
# never more than a quarter of them, where the grass thins out towards the edge of what it grows on and in patches; in
# other patches it grows taller, and it is greener or drier with the ground under it.  Flowers grow in it in clumps,
# each clump of one kind, and a few on their own: red poppies, blue cornflowers, yellow dandelions (some gone to
# seed), white daisies, purple clover and orange and pink tulips.
GRASS_STEP = 0.25 / add.sqrt(min(1.0, DENSITY))       # the grid (thinned out in a quick run)
LAND_CELL = WORLD / N_GROUND                           # the land's quads, as drawn:
_land_y, _land_colour = {}, {}                         # the heights of their corners, their colours


def land_y(x, z):
    """The height of the land as drawn at (x, z): its quad there, split
    into two triangles either way (the lower of the two)."""
    return min(_land_splits(x, z))


def land_top(x, z):
    """The height of the land as drawn at (x, z), the higher of the two
    ways its quad there may be split (see land_y): a foot or a bucket set
    down there on it is never in it."""
    return max(_land_splits(x, z))


def slope_at(x, z, d=0.3):
    """How steep the land is at (x, z): its rise per unit of run, over +-d."""
    return add.sqrt(((land_top(x + d, z) - land_top(x - d, z)) / (2 * d)) ** 2 +
                    ((land_top(x, z + d) - land_top(x, z - d)) / (2 * d)) ** 2)


def settle(M, y0, fade=(0.16, 0.5), keep=()):
    """``M`` -- already placed, standing on the height ``y0`` -- set down on
    the land as it slopes there: every vertex raised or lowered by as much
    as the land under it is above or below y0, in full up to fade[0] over
    y0 and less and less up to fade[1] (``fade`` None: all of it in full),
    so that soles, hems and the foot of a bucket follow the ground, neither
    in it nor standing off it, and what is above them stays as it was.
    ``keep``: balls (middle, r0, r1) in which nothing is moved -- a hand
    already where it holds something that stands on the land -- and less
    and less so out to r1."""
    def f(p):
        t = p[1] - y0
        if fade is None or t <= fade[0]:
            w = 1.0
        elif t >= fade[1]:
            return p
        else:
            u = (t - fade[0]) / (fade[1] - fade[0])
            w = 1.0 - u * u * (3.0 - 2.0 * u)
        for c, r0, r1 in keep:
            d = vlen(vsub(p, c))
            if d < r1:
                u = max(0.0, (d - r0) / (r1 - r0))
                w *= u * u * (3.0 - 2.0 * u)
        return [p[0], p[1] + w * (land_top(p[0], p[2]) - y0), p[2]]
    return add.deform(M, f)


def _land_splits(x, z):
    """The height of the land's quad at (x, z) split into two triangles
    along one diagonal, and along the other."""
    i, j = int((x + WORLD / 2) // LAND_CELL), int((z + WORLD / 2) // LAND_CELL)
    fx, fz = (x + WORLD / 2) / LAND_CELL - i, (z + WORLD / 2) / LAND_CELL - j
    h = []
    for key in ((i, j), (i + 1, j), (i, j + 1), (i + 1, j + 1)):
        if key not in _land_y:
            _land_y[key] = ground(-WORLD / 2 + key[0] * LAND_CELL, -WORLD / 2 + key[1] * LAND_CELL)
        h.append(_land_y[key])
    h00, h10, h01, h11 = h
    one = h00 + (h11 - h01) * fx + (h01 - h00) * fz if fz > fx else h00 + (h10 - h00) * fx + (h11 - h10) * fz
    two = h00 + (h10 - h00) * fx + (h01 - h00) * fz if fx + fz < 1 else h11 + (h01 - h11) * (1 - fx) + (h10 - h11) * (1 - fz)
    return one, two


def land_colour(x, z):
    """The colour of the land as drawn at (x, z): of its quad there, or of
    the piece of the quad that (x, z) is in, where colours meet in it."""
    i, j = int((x + WORLD / 2) // LAND_CELL), int((z + WORLD / 2) // LAND_CELL)
    if (i, j) not in _land_colour:
        cx, cz = -WORLD / 2 + (i + 0.5) * LAND_CELL, -WORLD / 2 + (j + 0.5) * LAND_CELL
        if moat_dug(cx, cz):
            _land_colour[(i, j)] = P["lakebed"]
        else:
            quad = []
            for n_, (a, b) in enumerate(((i, j), (i, j + 1), (i + 1, j + 1), (i + 1, j))):
                px, pz = -WORLD / 2 + a * LAND_CELL, -WORLD / 2 + b * LAND_CELL
                py = ground(px, pz)
                quad.append((n_, px, py, pz, land_fields(px, pz, py)))
            ids = [4]

            def cross(p, q, k):
                ids[0] += 1
                return land_at(p, q, k, ids[0])
            pieces = land_split(quad, cross)
            _land_colour[(i, j)] = pieces[0][1] if len(pieces) == 1 else ("pieces", [([(v[1], v[3]) for v in poly], c) for poly, c in pieces])
    got = _land_colour[(i, j)]
    if not isinstance(got, tuple):
        return got
    best = None
    for poly, c in got[1]:                                              # the piece it is in (or nearest to being in)
        worst = min(((b[0] - a[0]) * (z - a[1]) - (b[1] - a[1]) * (x - a[0])) * -1 for a, b in zip(poly, poly[1:] + poly[:1]))
        if best is None or worst > best[0]:
            best = (worst, c)
    return best[1]


def tuft(x, y, z, n, tall=1.0, dry=False, lush=0.5):
    """A tuft of grass rooted at (x, y, z): three blades (four, when it is
    tall), each a thin solid sheet leaning out; none reaches out more than
    0.15 from the root."""
    a = 6.2832 * hash2(n, 7, 64)
    for j in range(4 if tall > 1.3 else 3):
        b = a + j * 2.1 + hash2(n, j, 65)
        h = (0.22 + 0.3 * hash2(n, j, 66)) * tall
        lean = 0.08 + 0.06 * hash2(n, j, 67)
        u = hash2(n, j, 68)
        col = (P["grass_dry"] if u < 0.55 else P["grass"]) if dry else (P["leaf"] if u < 0.25 + 0.45 * lush else P["grass"])
        sheet([[x - 0.05 * add.cos(b), y, z - 0.05 * add.sin(b)], [x + 0.05 * add.cos(b), y, z + 0.05 * add.sin(b)],
               [x + lean * add.sin(b), y + h, z - lean * add.cos(b)]], col, 0.01, hinge=True)


FLOWERS = ("poppy", "cornflower", "dandelion", "daisy", "clover", "tulip")


def flower(x, y, z, kind, n, tall=1.0):
    """A flower rooted at (x, y, z): a stem, two leaves and its head, a
    little over the grass round it; nothing reaches out more than 0.13 from
    the root, nor higher than 0.1 over its stem, 0.62 * tall * 1.15."""
    h = (0.42 + 0.2 * hash2(n, 1, 73)) * tall * (1.15 if kind in ("tulip", "clover") else 1.0)
    a, b = 6.2832 * hash2(n, 2, 73), 6.2832 * hash2(n, 3, 73)
    c, s_ = add.cos(a), add.sin(a)
    tx, ty, tz = x + 0.035 * c, y + h, z + 0.035 * s_                   # the head, the stem leaning a little
    sheet([[x - 0.012 * s_, y, z + 0.012 * c], [x + 0.012 * s_, y, z - 0.012 * c], [tx, ty, tz]], P["leaf"], 0.006, hinge=True)
    for k in (0, 1):                                                    # two long leaves from the foot of the stem
        e = b + add.pi * k
        sheet([[x - 0.015 * add.sin(e), y, z + 0.015 * add.cos(e)], [x + 0.015 * add.sin(e), y, z - 0.015 * add.cos(e)],
               [x + 0.09 * add.cos(e), y + 0.1 + 0.05 * k, z + 0.09 * add.sin(e)]], P["grass"], 0.006, hinge=True)
    if kind == "poppy":                                                 # a red cup, black in the middle
        add.cone([tx, ty + 0.07, tz], [tx, ty - 0.01, tz], 0.09, 5, P["poppy"])
        add.octahedron([tx, ty + 0.07, tz], 0.025, P["black"])
    elif kind == "cornflower":                                          # a ragged blue ball
        add.mesh(add.rotateY(add.make(add.octahedron, [tx, ty + 0.05, tz], 0.07, P["cornflower"]), a, [tx, ty, tz]))
    elif kind == "dandelion" and hash2(n, 4, 73) < 0.2:                 # gone to seed: a white clock
        add.octahedron([tx, ty + 0.07, tz], 0.08, P["white"])
    elif kind == "dandelion":                                           # a flat yellow head
        add.mesh(add.stretch(add.make(add.octahedron, [tx, ty + 0.025, tz], 0.075, P["dandelion"]), [1.0, 0.45, 1.0], [tx, ty + 0.025, tz]))
    elif kind == "daisy":                                               # white petals round a yellow eye
        add.cone([tx, ty - 0.005, tz], [tx, ty + 0.03, tz], 0.085, 8, P["white"])
        add.octahedron([tx, ty + 0.03, tz], 0.03, P["dandelion"])
    elif kind == "clover":                                              # a round purple head
        add.mesh(add.stretch(add.make(add.octahedron, [tx, ty + 0.04, tz], 0.055, P["purple"]), [1.0, 1.25, 1.0], [tx, ty + 0.04, tz]))
    else:                                                               # a tulip: a cup, orange or pink
        add.frustum([tx, ty - 0.005, tz], [tx, ty + 0.1, tz], 0.04, 0.06, 5, P["orange"] if n % 2 else P["rose"])


def flower_spots(x0, x1, z0, z1, ok, seed, clumps=0.7):
    """Where flowers grow in the rectangle x0..x1, z0..z1 (and where ``ok``):
    clumps of one kind round points scattered 5 m apart (in some of the
    cells), and a few single ones round points 2.5 m apart -- all at least
    0.26 apart.  A list of (x, z, kind, n)."""
    out, taken = [], {}

    def free(x, z):
        i, j = int(x // 0.5), int(z // 0.5)
        return all((x - q[0]) ** 2 + (z - q[1]) ** 2 > 0.26 ** 2 for a in (i - 1, i, i + 1) for b in (j - 1, j, j + 1)
                   for q in taken.get((a, b), ()))

    def put(x, z, kind):
        if x0 < x < x1 and z0 < z < z1 and free(x, z) and ok(x, z):
            out.append((x, z, kind, len(out) + 1000 * seed))
            taken.setdefault((int(x // 0.5), int(z // 0.5)), []).append((x, z))
    for i in range(int(x0 // 5), int(x1 // 5) + 1):
        for j in range(int(z0 // 5), int(z1 // 5) + 1):
            if hash2(i, j, seed) > clumps * min(1.0, DENSITY * 3):
                continue
            cx, cz = (i + hash2(i, j, seed + 1)) * 5, (j + hash2(i, j, seed + 2)) * 5
            R = 0.6 + 1.2 * hash2(i, j, seed + 3)
            kind = FLOWERS[int(hash2(i, j, seed + 4) * 6) % 6]
            for k in range(int(4 + 8 * R * R)):
                r, a = R * add.sqrt(hash2(i * 97 + k, j, seed + 5)), 6.2832 * hash2(i * 97 + k, j, seed + 6)
                put(cx + r * add.cos(a), cz + r * add.sin(a), kind)
    for i in range(int(x0 // 2.5), int(x1 // 2.5) + 1):
        for j in range(int(z0 // 2.5), int(z1 // 2.5) + 1):
            if hash2(i, j, seed + 7) < 0.15 * min(1.0, DENSITY * 3):
                put((i + hash2(i, j, seed + 8)) * 2.5, (j + hash2(i, j, seed + 9)) * 2.5, FLOWERS[int(hash2(i, j, seed + 10) * 6) % 6])
    return out


class Spots(object):
    """Points on a grid of 0.5 m cells, to ask quickly what is near."""
    def __init__(self, points=()):
        self.cells = {}
        for p in points:
            self.add(p)

    def add(self, p):
        self.cells.setdefault((int(p[0] // 0.5), int(p[1] // 0.5)), []).append(p)

    def near(self, x, z, d):
        k = int(d // 0.5) + 1
        i, j = int(x // 0.5), int(z // 0.5)
        return any((x - p[0]) ** 2 + (z - p[1]) ** 2 < d * d for a in range(i - k, i + k + 1) for b in range(j - k, j + k + 1)
                   for p in self.cells.get((a, b), ()))


STAKES = [((shore_r(d * add.pi / 180) - 1.8) * add.cos(d * add.pi / 180), (shore_r(d * add.pi / 180) - 1.8) * add.sin(d * add.pi / 180))
          for d in BOAT_DEGS]                          # the stakes the boats are tied to (see "the rowing boats"), and the
ROCK_SEAT = (87.4 * add.cos(add.pi / 3), 87.4 * add.sin(add.pi / 3))   # fisherman's rock on the shore ("fishermen")
_mushrooms = Spots(MUSHROOMS)
_scree = Spots()                                       # (the stones and plants of the landslide: see below)
_beasts = Spots()                                      # (the circles (x, z, r) round the running beasts: see below)


def by_beast(x, z, margin=0.15):
    """Is (x, z) within ``margin`` of a running beast (of one of the circles round it)?  With the margin a blade of
    grass leans out from its root (0.15; a flower 0.13) nothing growing outside touches one."""
    i, j = int(x // 0.5), int(z // 0.5)                # (no circle is wider than 0.18 from its middle, so the middle of
    return any((x - c[0]) ** 2 + (z - c[1]) ** 2 < (c[2] + margin) ** 2      # any one near is in the cells round)
               for a in (i - 1, i, i + 1) for b in (j - 1, j, j + 1) for c in _beasts.cells.get((a, b), ()))


def meadow(x, z, top=0.0):
    """Can grass (or a flower ``top`` tall) grow at (x, z) outside the walls:
    on green land, clear of the walls, the towers, the moat, the road and its
    kerbs, the harbour, the boats' stakes, the fisherman's rock, the trunks of
    the trees (and under the spruces, their lowest branches) and the mushrooms?"""
    if octagon_r(x, z) < 51.62 or near_corner(x, z, 0.44) or (z > 40 and abs(x) < 25.5 and castle_depth(x, z) > -0.2):
        return False
    c = land_colour(x, z)
    if c is not P["grass"] and c is not P["grass_dry"]:
        return False
    if in_moat(x, z, 0.15) or on_road(x, z, 0.45) or on_wharf(x, z, 0.3) or by_boat(x, z):
        return False
    if any((x - p[0]) ** 2 + (z - p[1]) ** 2 < r * r for p, r in ((ROCK_SEAT, 1.6),) + tuple((q, 0.3) for q in STAKES)):
        return False
    for t in trees_near(x, z):
        d2 = (x - t[0]) ** 2 + (z - t[1]) ** 2
        if d2 < (TRUNK[t[3]] * t[2] + 0.2) ** 2 or (d2 < (t[4] + 0.2) ** 2 and land_y(x, z) + top > t[5] - 0.05):
            return False
    return not _mushrooms.near(x, z, 0.36) and not _scree.near(x, z, 0.55) and not by_beast(x, z)


def meadow_edge(x, z, y):
    """How far (x, z) is from the edge of the meadow at the lake's shore,
    0 .. 1 (1: 0.5 m or more above the water) -- where the grass thins out
    into the sand; up to the walls, the towers, the moat's bank and the
    road it grows as thick as anywhere."""
    return add.clamp((y - WATER_Y - 0.4) * 3.0 / 1.5)


def meadow_grass(x0, x1, z0, z1, ok, edge, root, dry, seed, flowers, step=GRASS_STEP):
    """Grass on the grid over x0..x1, z0..z1 where ``ok(x, z, top)``: with
    ``edge(x, z, y)`` how far from the edge it is, ``root(x, z)`` the height
    of the ground and ``dry(x, z)`` whether it is dry there; the flowers
    first (``flowers``: from flower_spots); ``step``: the grid.  Returns
    how many of each."""
    fl = Spots()
    for x, z, kind, n in flowers:
        tall = 1.0 + 0.7 * add.clamp((value_noise(x, z, 7.0, 63) - 0.55) / 0.3)
        if ok(x, z, 0.62 * tall * 1.15 + 0.1):
            flower(x, root(x, z), z, kind, n, tall)
            fl.add((x, z))
    n_f = sum(len(v) for v in fl.cells.values())
    n = 0
    for i in range(int(x0 // step), int(x1 // step) + 1):
        for j in range(int(z0 // step), int(z1 // step) + 1):
            x, z = (i + hash2(i, j, seed)) * step, (j + hash2(i, j, seed + 1)) * step
            tall = 1.0 + 0.7 * add.clamp((value_noise(x, z, 7.0, 63) - 0.55) / 0.3)
            if not ok(x, z, 0.52 * tall) or fl.near(x, z, 0.28):
                continue
            y = root(x, z)
            if hash2(i, j, seed + 2) > 0.75 + 0.25 * min(edge(x, z, y), 0.35 + 0.65 * value_noise(x, z, 4.5, 61)):
                continue                                                # (the grass a little thinner in places)
            tuft(x, y, z, n + seed * 1000003, tall, dry(x, z), value_noise(x, z, 5.0, 62))
            n += 1
            if n % 40000 == 0:
                flush("grass (%d tufts)" % n, clean=False)
    return n, n_f


# the landslide: on the steepest of the hill the grass has not held, and the ground is bare -- rock, scree and earth in
# patches -- strewn with stones fallen from above, of every size, bedded in it the way they came to rest, and gravel;
# ferns grow on it, a few bushes, and grass in the pockets of earth.  (Only there: each thing wholly on the landslide,
# clear of the trees, the mushrooms and one another.)
LANDSLIDE = (P["rock"], P["scree"], P["earth_dark"])
SCREE = (P["rock"], P["stone_dark"], shade_of("stone_dark", 1), P["scree"], shade_of("stone", 2), P["granite"])


def slope_frame(x, z):
    """Three axes at (x, z) of the ground: along it (x-ish), its normal, along it (z-ish)."""
    e = 0.3
    n = vunit([-(ground(x + e, z) - ground(x - e, z)) / (2 * e), 1.0, -(ground(x, z + e) - ground(x, z - e)) / (2 * e)])
    u = vunit(vcross(n, [0, 0, 1]))
    return u, n, vcross(u, n)


def on_landslide(x, z, r):
    """Is (x, z) on the landslide, and all round it ``r`` out?  (Not where
    the castle stands: beside the south front the land drops into the
    moat under the walls, the gate towers and the gate's passage, and is
    steep there too -- but nothing lies or grows under them.)"""
    if octagon_r(x, z) < 51.5 + r or (z > 45.0 and castle_depth(x, z) > -0.5 - r):
        return False
    return all(land_colour(x + r * dx, z + r * dz) in LANDSLIDE for dx, dz in ((0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)))


def scree_stone(x, z, r, seed, squash):
    """A stone ``r`` across, fallen and bedded in the slope at (x, z): flat side down, square to the ground, two fifths
    of it sunk."""
    u, n, w = slope_frame(x, z)
    M = add.stretch(PEBBLE, [r * (1.0 + 0.35 * hash2(seed, 1, 96)), r * squash, r * (0.85 + 0.3 * hash2(seed, 2, 96))], (0, 0, 0))
    M = add.color(add.rotateY(M, 6.2832 * hash2(seed, 3, 96)), SCREE[int(hash2(seed, 4, 96) * len(SCREE)) % len(SCREE)])
    c = [x + n[0] * r * squash * 0.35, land_y(x, z) + n[1] * r * squash * 0.35, z + n[2] * r * squash * 0.35]
    add.mesh(add.transform(M, [[u[0], n[0], w[0], c[0]], [u[1], n[1], w[1], c[1]], [u[2], n[2], w[2], c[2]]]))


def fern(x, z, seed):
    """A fern: seven to nine fronds from one root, each arching up and out and over, tapering to its tip."""
    y = land_y(x, z) - 0.02
    for i in range(7 + int(hash2(seed, 1, 91) * 3)):
        a = 2 * add.pi * (i + 0.4 * hash2(seed, i, 92)) / 8.0
        L, rise = 0.4 + 0.3 * hash2(seed, i, 93), 0.3 + 0.35 * hash2(seed, i, 94)
        c, s_ = add.cos(a), add.sin(a)
        mid = lambda t: [x + c * L * t, y + 0.02 + rise * (1.8 * t - 1.3 * t * t), z + s_ * L * t]
        half = lambda t: 0.05 * (1 - t) + 0.006
        for k in range(4):
            t0, t1 = k / 4.0, (k + 1) / 4.0
            p0, p1 = mid(t0), mid(t1)
            sheet([[p0[0] - s_ * half(t0), p0[1], p0[2] + c * half(t0)], [p0[0] + s_ * half(t0), p0[1], p0[2] - c * half(t0)],
                   [p1[0] + s_ * half(t1), p1[1], p1[2] - c * half(t1)], [p1[0] - s_ * half(t1), p1[1], p1[2] + c * half(t1)]],
                  P["leaf"] if (i + k) % 3 else P["leaf_dark"], 0.006)


def bush(x, z, r, seed):
    """A little bush: bunches of leaves, the lowest sunk a little into the slope wherever it is lowest."""
    for j in range(3 + int(hash2(seed, 2, 95) * 3)):
        a, d = 6.2832 * hash2(seed, j, 97), r * 0.45 * hash2(seed, j, 98)
        rr = r * (0.45 + 0.25 * hash2(seed, j, 99))
        bx, bz = x + d * add.cos(a), z + d * add.sin(a)
        low = min(ground(bx + rr * add.cos(b), bz + rr * add.sin(b)) for b in (0.0, 1.57, 3.14, 4.71))
        c = [bx, low + rr * 0.72 + j * 0.06 * r, bz]
        add.mesh(add.stretch(add.make(add.sphere, c, rr, 4, (P["leaf_dark"], P["leaf"], P["oak_leaf"])[j % 3]), [1.0, 0.8, 1.0], c))


def clear_of_trees(x, z, r):
    return all((x - t[0]) ** 2 + (z - t[1]) ** 2 > (TRUNK[t[3]] * t[2] + r + 0.15) ** 2 for t in trees_near(x, z))


n_st = n_pl = 0
STEP_S = 0.8
for i in range(int(-93 // STEP_S), int(93 // STEP_S) + 1):             # the plants first, then the stones round them
    for j in range(int(-93 // STEP_S), int(93 // STEP_S) + 1):
        x, z = (i + hash2(i, j, 81)) * STEP_S, (j + hash2(i, j, 82)) * STEP_S
        if x * x + z * z > 93 * 93 or land_colour(x, z) not in LANDSLIDE or on_road(x, z, 1.0) or by_jetty(x, z, 1.0):
            continue
        u, v = hash2(i, j, 83), hash2(i, j, 84)
        if u < 0.22:                                                   # a fern, or a bush
            r = 0.72 if u < 0.15 else 0.45
            if on_landslide(x, z, r) and clear_of_trees(x, z, r) and not _mushrooms.near(x, z, r + 0.2) and not _scree.near(x, z, r + 0.35):
                if u < 0.15:
                    fern(x, z, i * 7919 + j)
                else:
                    bush(x, z, 0.4 + 0.2 * v, i * 7919 + j)
                _scree.add((x, z))
                n_pl += 1
        elif u < 0.4 and land_colour(x, z) is P["earth_dark"]:       # grass in the earth
            grown = []
            for k in range(3):
                tx_, tz_ = x + 0.2 * add.cos(2.1 * k + v * 6), z + 0.2 * add.sin(2.1 * k + v * 6)
                if on_landslide(tx_, tz_, 0.18) and clear_of_trees(tx_, tz_, 0.15) and not _scree.near(tx_, tz_, 0.6):
                    tuft(tx_, land_y(tx_, tz_) - 0.02, tz_, i * 31 + j * 7 + k, 1.0, False, 0.6)
                    grown.append((tx_, tz_))
                    n_pl += 1
            for q in grown:                                            # (the stones keep clear of it)
                _scree.add(q)
for i in range(int(-93 // STEP_S), int(93 // STEP_S) + 1):
    for j in range(int(-93 // STEP_S), int(93 // STEP_S) + 1):
        x, z = (i + hash2(i, j, 85)) * STEP_S, (j + hash2(i, j, 86)) * STEP_S
        if hash2(i, j, 87) > 0.5 or x * x + z * z > 93 * 93 or land_colour(x, z) not in LANDSLIDE or on_road(x, z, 1.0):
            continue
        r = 0.07 + 0.38 * hash2(i, j, 88) ** 3                         # a stone
        if on_landslide(x, z, r) and clear_of_trees(x, z, r) and not _mushrooms.near(x, z, r + 0.2) and not _scree.near(x, z, r + 0.45):
            scree_stone(x, z, r, i * 7919 + j, 0.45 + 0.25 * hash2(i, j, 89))
            _scree.add((x, z))
            n_st += 1
for i in range(int(-93 // 0.4), int(93 // 0.4) + 1):                  # and gravel on the scree
    for j in range(int(-93 // 0.4), int(93 // 0.4) + 1):
        if hash2(i, j, 86) > 0.3:
            continue
        x, z = (i + hash2(i, j, 87)) * 0.4, (j + hash2(i, j, 88)) * 0.4
        if x * x + z * z > 93 * 93 or land_colour(x, z) is not P["scree"]:
            continue
        r = 0.03 + 0.04 * hash2(i, j, 89)
        if on_landslide(x, z, r) and clear_of_trees(x, z, r) and not _scree.near(x, z, r + 0.12) and not _mushrooms.near(x, z, 0.25):
            scree_stone(x, z, r, i * 104729 + j, 0.6)
            n_st += 1
flush("the landslide (%d stones, %d plants)" % (n_st, n_pl), clean=False)


LIFE = 1.15                                            # knights and horses are built life-size and scaled by this, like
                                                       # the archers: all the castle's people are one size


def ramp(values):
    """A function of t = 0..1 running straight through ``values``, evenly spaced."""
    n = len(values) - 1

    def f(t):
        i = min(n - 1, int(t * n))
        return values[i] + (values[i + 1] - values[i]) * (t * n - i)
    return f


def tube_at(spec, u, q, off=0.0):
    """A point on a horse's neck or head: ``spec`` is a path in the middle
    plane with half-heights above and below it and half-widths; ``u`` is
    the (fractional) number of the path point, ``q`` the angle round the
    path (0: the crest or the face, pi/2: the right side), ``off`` out."""
    path, top, bottom, half = spec
    n = len(path) - 1

    def at(i):
        a, b = path[max(0, i - 1)], path[min(n, i + 1)]
        t = vunit([b[0] - a[0], b[1] - a[1], 0])
        return path[i], [-t[1], t[0]], top[i], bottom[i], half[i]
    i = min(int(u), n - 1)
    f = u - i
    A, B = at(i), at(i + 1)
    c = [A[0][k] + (B[0][k] - A[0][k]) * f for k in (0, 1)]
    nrm = vunit([A[1][0] + (B[1][0] - A[1][0]) * f, A[1][1] + (B[1][1] - A[1][1]) * f, 0])
    ht, hb, hw = [A[k] + (B[k] - A[k]) * f for k in (2, 3, 4)]
    h = ht if add.cos(q) > 0 else hb
    cq, sq = add.cos(q), add.sin(q)
    g = vunit([nrm[0] * cq / h, nrm[1] * cq / h, sq / hw])
    return [c[0] + nrm[0] * h * cq + g[0] * off, c[1] + nrm[1] * h * cq + g[1] * off, hw * sq + g[2] * off]


# the cows of the castle, grazing outside its walls on the flat ground to the north-east, where the grass is dry: built
# life-size (head towards +x, the hooves on y = 0, z to her right) and scaled by LIFE, standing still with her head
# down in the grass.  One body lofted through slices of her side view (as the beasts of the wood are: see BEASTS) from
# the pins at her rump over the hooks, the straight back and the deep barrel to the withers and the brisket, on down
# the short deep neck with the dewlap under it to the head: the poll between the horns, the broad flat forehead, the
# face narrowing to the broad muzzle in the grass.  Each slice: (x, y) of the top line and of the under line -- on
# the neck and the head, the crest and the face, the dewlap, the throat and the jaw -- the half-width, how square it
# is, and how much narrower below (keel) and above (crown).
COW_SLICES = [(-0.965, 1.2, -0.945, 0.93, 0.07, 0.8, 0.0, 0.35), (-0.94, 1.265, -0.915, 0.79, 0.16, 0.65, 0.1, 0.3),
              (-0.86, 1.3, -0.845, 0.7, 0.24, 0.5, 0.15, 0.15), (-0.72, 1.31, -0.715, 0.645, 0.28, 0.4, 0.15, 0.05),
              (-0.55, 1.29, -0.55, 0.6, 0.29, 0.5, 0.12, 0.12), (-0.34, 1.28, -0.33, 0.55, 0.318, 0.5, 0.12, 0.18),
              (-0.1, 1.285, -0.1, 0.52, 0.338, 0.5, 0.1, 0.2), (0.15, 1.3, 0.15, 0.54, 0.33, 0.5, 0.14, 0.25),
              (0.35, 1.32, 0.37, 0.575, 0.295, 0.55, 0.22, 0.32), (0.52, 1.35, 0.56, 0.6, 0.255, 0.55, 0.32, 0.42),
              (0.66, 1.3, 0.72, 0.6, 0.22, 0.6, 0.4, 0.36), (0.82, 1.17, 0.84, 0.55, 0.19, 0.6, 0.55, 0.3),
              (0.97, 1.0, 0.93, 0.49, 0.16, 0.6, 0.6, 0.26), (1.1, 0.83, 0.99, 0.44, 0.14, 0.6, 0.45, 0.2),
              (1.19, 0.68, 1.03, 0.4, 0.13, 0.6, 0.3, 0.16), (1.26, 0.56, 1.05, 0.38, 0.13, 0.55, 0.25, 0.06),
              (1.31, 0.44, 1.1, 0.3, 0.132, 0.55, 0.3, 0.08), (1.35, 0.31, 1.18, 0.21, 0.1, 0.58, 0.25, 0.18),
              (1.38, 0.195, 1.245, 0.12, 0.095, 0.55, 0.12, 0.12), (1.395, 0.105, 1.3, 0.045, 0.087, 0.55, 0.08, 0.06)]
COW_POLL, COW_EYES, COW_NOSE = 15.0, 15.9, 18.6                                  # (slices: the horns, the eyes, the nose pad)
# the legs: a path from inside the body down to the hoof, and the half-depths (fore and aft) and half-widths along it,
# the hoof's toe; fore -- elbow, the forearm, the knee, the cannon, the fetlock, the pastern -- and hind -- the stifle,
# the gaskin, the hock (its point behind), the cannon, the fetlock, the pastern -- at |z|
COW_LEGS = (([(0.5, 0.8), (0.505, 0.62), (0.5, 0.47), (0.5, 0.37), (0.5, 0.3), (0.5, 0.17), (0.505, 0.12), (0.525, 0.075)],
             (0.14, 0.118, 0.082, 0.066, 0.05, 0.045, 0.053, 0.04), (0.105, 0.09, 0.065, 0.06, 0.043, 0.04, 0.047, 0.037), 0.165),
            ([(-0.52, 0.8), (-0.6, 0.64), (-0.7, 0.51), (-0.73, 0.44), (-0.71, 0.3), (-0.695, 0.17), (-0.69, 0.12), (-0.67, 0.075)],
             (0.18, 0.14, 0.092, 0.072, 0.05, 0.045, 0.053, 0.04), (0.12, 0.095, 0.064, 0.056, 0.043, 0.04, 0.047, 0.037), 0.18))
COW_HOOVES = [(leg[0][-1][0] + 0.035, sd * leg[3]) for leg in COW_LEGS for sd in (-1, 1)]   # (x, z) of each hoof's middle


def cow_slice(s):
    """The slice ``s`` (fractional) of COW_SLICES, between the given ones (Catmull-Rom)."""
    T, n = COW_SLICES, len(COW_SLICES)
    s = max(0.0, min(n - 1.0, s))
    i = min(int(s), n - 2)
    t = s - i
    a, b, c, d = T[max(i - 1, 0)], T[i], T[i + 1], T[min(i + 2, n - 1)]
    return [0.5 * (2 * b[k] + (c[k] - a[k]) * t + (2 * a[k] - 5 * b[k] + 4 * c[k] - d[k]) * t * t +
                   (3 * b[k] - a[k] - 3 * c[k] + d[k]) * t * t * t) for k in range(8)]


def cow_pt(s, th, off=0.0):
    """A point of the cow's body at slice ``s``, ``th`` degrees round it (90: the top line -- the back, the crest,
    the face; -90: the under line; 0: her right side, +z), ``off`` out from it."""
    def raw(s_, th_):
        tx, ty, bx, by, hw, e, keel, crown = cow_slice(s_)
        co, si = add.cos(th_ * add.pi / 180), add.sin(th_ * add.pi / 180)
        v = abs(si) ** e * (1 if si >= 0 else -1)
        w = hw * abs(co) ** e * (1 if co >= 0 else -1) * (1 - keel * max(0.0, -si) ** 2 - crown * max(0.0, si) ** 2)
        return [(tx + bx) / 2 + (tx - bx) / 2 * v, (ty + by) / 2 + (ty - by) / 2 * v, w]
    p = raw(s, th)
    if off:
        n = len(COW_SLICES) - 1.0
        a_ = vsub(raw(min(s + 0.02, n), th), raw(max(s - 0.02, 0.0), th))
        q = vunit(vcross(a_, vsub(raw(s, th + 1.0), raw(s, th - 1.0))))
        c_ = raw(s, th + 180.0)
        if sum(q[k] * (p[k] - c_[k]) for k in range(3)) < 0:
            q = [-v for v in q]
        p = [p[k] + q[k] * off for k in range(3)]
    return p


def cow_body(kind="pied", seed=0, step=0.0):
    """A cow grazing, life-size (see above): ``kind`` "pied" -- a Holstein,
    black in great patches on white, the belly, the legs below the knees
    and hocks, the switch of her tail and a blaze down her face white, the
    muzzle pink -- or "red", all red-brown but a white star on her forehead
    and a dark muzzle.  One body from the rump to the muzzle; the udder and
    its four teats; the legs jointed at the knee and the hock, each on a
    cloven hoof of two claws with the dewclaws behind; the tail with its
    switch; horns, ears out to the sides, eyes under their lids, the
    nostrils and the mouth.  ``step``: her near hind leg (-z) set back that
    far at the hoof, swung from the hip -- as a cow stands to be milked,
    out of the milker's way."""
    add.push()
    pied = kind == "pied"
    base = add.rgb(P["black"] if pied else P["spire"])
    white, pink, dark = add.rgb(P["white"]), add.rgb(P["pig"]), add.rgb(P["black"])
    n = len(COW_SLICES) - 1

    def field(p, s):                                                            # > 0 the dark of her coat, < 0 white:
        if not pied:                                                            # a red cow's star on her forehead,
            return 20 * (vlen(vsub(p, cow_pt(15.45, 90))) - 0.045) if s > 14.9 else 1.0
        if s > 14.3:                                                            # a Holstein's head black but for the blaze
            return 20 * (vlen(vsub(p, cow_pt(s, 90))) - (0.05 if s < 17.9 else 0.036))   # down her face,
        w = 0.55 * value_noise(p[0] + 3.1 * seed, p[1] + 1.7 * p[2], 0.42, 311) + \
            0.45 * value_noise(p[0] - 0.8 * p[1] + 2 * seed, p[2] + p[1], 0.3, 312) - 0.5   # the great patches of
        return min(w, 3.0 * (p[1] - 0.64)) if s < 10.5 else w                    # her body, the belly white
    ss = []
    for i in range(n):                                                          # (rings: closer on the head)
        for k in range(5 if i < 14 else 6):
            ss.append(i + k / (5.0 if i < 14 else 6.0))
    ss.append(float(n))
    K = 40
    rings = [[cow_pt(s_, 360.0 * (j + 0.5) / K - 90.0) for j in range(K)] for s_ in ss]
    vals = [[field(p, s_) for p in r] for r, s_ in zip(rings, ss)]
    M = add.Mesh()
    ids = [[M.add_vertex(p) for p in r] for r in rings]
    cross = {}

    def xpt(a_, b_, va, vb):                                                   # where the edge a-b crosses the patch's
        if a_ > b_:                                                             # edge (one point, whichever face asks)
            a_, b_, va, vb = b_, a_, vb, va
        if (a_, b_) not in cross:
            t = va / (va - vb)
            pa, pb = M.V[a_], M.V[b_]
            cross[(a_, b_)] = M.add_vertex([pa[k] + (pb[k] - pa[k]) * t for k in range(3)])
        return cross[(a_, b_)]

    def tri(tv, vv, colour):                                                    # a triangle of the skin, split along the
        pos = [v > 0 for v in vv]                                               # patch's edge where it crosses it: the
        if all(pos) or not any(pos):                                            # edges of the patches smooth, not stepped
            M.add_face(tv, colour(pos[0]))
            return
        k = next(i for i in range(3) if pos[i] != pos[(i + 1) % 3] and pos[i] != pos[(i + 2) % 3])
        a_, b_, c_ = tv[k], tv[(k + 1) % 3], tv[(k + 2) % 3]
        pab, pac = xpt(a_, b_, vv[k], vv[(k + 1) % 3]), xpt(a_, c_, vv[k], vv[(k + 2) % 3])
        M.add_face([a_, pab, pac], colour(pos[k]))
        M.add_face([pab, b_, c_, pac], colour(not pos[k]))
    for i in range(len(rings) - 1):
        nose = (ss[i] + ss[i + 1]) / 2 > COW_NOSE
        colour = (lambda d: pink if pied else dark) if nose else (lambda d: base if d else white)
        for j in range(K):
            j1 = (j + 1) % K
            q = [(ids[i][j], vals[i][j]), (ids[i][j1], vals[i][j1]), (ids[i + 1][j1], vals[i + 1][j1]), (ids[i + 1][j], vals[i + 1][j])]
            for t_ in ((q[0], q[1], q[2]), (q[0], q[2], q[3])):
                tri([v for v, _ in t_], [w for _, w in t_], colour)
    for r, e in ((0, 0), (len(rings) - 1, 1)):                                  # the ends closed (the rump, the nose pad)
        c = M.add_vertex([sum(p[k] for p in rings[r]) / K for k in range(3)])
        for j in range(K):
            f = [ids[r][j], ids[r][(j + 1) % K], c]
            M.add_face(f if e else f[::-1], (pink if pied else dark) if e else (base if vals[r][j] > 0 else white))
    add.mesh(add.fix_normals(M))
    for sd in (-1, 1):
        h0 = cow_pt(COW_POLL, 90 - sd * 62, -0.012)                              # a horn: out from the poll, curving
        f = vunit(vsub(cow_pt(COW_POLL + 1.0, 90), cow_pt(COW_POLL, 90)))         # forward and up at the tip
        up = vunit(vsub(cow_pt(COW_POLL, 90), cow_pt(COW_POLL, -90)))
        hp = [h0, [h0[0] + 0.01 * up[0], h0[1] + 0.01 * up[1], h0[2] + sd * 0.07],
              [h0[0] + 0.05 * up[0] + 0.03 * f[0], h0[1] + 0.05 * up[1] + 0.03 * f[1], h0[2] + sd * 0.12],
              [h0[0] + 0.1 * up[0] + 0.07 * f[0], h0[1] + 0.1 * up[1] + 0.07 * f[1], h0[2] + sd * 0.14]]
        add.polyline(hp, ramp((0.03, 0.024, 0.016, 0.006)), 10, P["bone"], smooth=2)
        e0 = cow_pt(COW_POLL + 0.45, 5 if sd > 0 else 175, -0.01)
        ear = add.make(add.ellipsoid, [0, 0, 0], [0.05, 0.016, 0.095], 5, base if not pied else dark)   # an ear, out to the
        ear.extend(add.make(add.ellipsoid, [0, 0.008, 0.01], [0.036, 0.01, 0.07], 4, P["pig"]))     # side, its hollow to
        ear = add.rotateX(ear, -sd * 0.35)
        ear = add.rotateZ(ear, 0.5)
        add.mesh(add.move(ear, [e0[0] - 0.02, e0[1] + 0.01, e0[2] + sd * 0.09]))
        ey = cow_pt(COW_EYES, 90 - sd * 55, -0.012)                              # the eye, under its lid
        add.ellipsoid(ey, [0.022, 0.022, 0.016], 4, P["black"])
        lid = cow_pt(COW_EYES - 0.12, 90 - sd * 52, -0.004)
        add.ellipsoid(lid, [0.026, 0.012, 0.018], 3, base)
        nz = cow_pt(len(COW_SLICES) - 1.08, 90 - sd * 40, -0.006)                # a nostril
        add.ellipsoid(nz, [0.012, 0.018, 0.012], 3, P["black"])
    add.polyline([cow_pt(n - 0.55, a_, 0.002) for a_ in (-150, -120, -90, -60, -30)], 0.006, 4, P["black"])   # the mouth
    for (pts0, fa, sw, zz), fore in zip(COW_LEGS, (True, False)):               # the legs: lofted round their paths,
        for sd in (-1, 1):                                                      # white below the knee on a pied cow
            back = step if (sd < 0 and not fore) else 0.0                       # (the near hind leg set back, from the hip)
            pts = [(x - back * (pts0[0][1] - y) / (pts0[0][1] - pts0[-1][1]), y) for x, y in pts0]
            rings = []
            for i, (x, y) in enumerate(pts):
                a_ = vsub([pts[min(i + 1, len(pts) - 1)][0], pts[min(i + 1, len(pts) - 1)][1], 0], [pts[max(i - 1, 0)][0], pts[max(i - 1, 0)][1], 0])
                t = vunit(a_)
                nx, ny = -t[1], t[0]                                            # (fore and aft, square to the leg)
                rings.append([[x + nx * fa[i] * add.cos(2 * add.pi * j / 14), y + ny * fa[i] * add.cos(2 * add.pi * j / 14),
                               sd * zz + sw[i] * add.sin(2 * add.pi * j / 14)] for j in range(14)])
            L = add.make(add.loft, rings, P["black"])
            for i, fc in enumerate(L.F):
                c = [sum(L.V[v][k] for v in fc) / len(fc) for k in range(3)]
                L.C[i] = (white if c[1] < (0.4 if fore else 0.45) else base) if pied else base
            add.mesh(add.fix_normals(L))
            if not fore:                                                        # the point of the hock
                add.ellipsoid([pts[3][0] - 0.035, pts[3][1] + 0.035, sd * zz], [0.04, 0.05, 0.034], 4, P["white"] if pied else P["spire"])
            hx, hy = pts[-1]
            for c in (-1, 1):                                                   # the two claws, their toes forward
                add.frustum([hx + 0.028, hy, sd * zz + c * 0.0215], [hx + 0.044, 0.001, sd * zz + c * 0.0215], 0.028, 0.034, 10, P["black"])
                add.ellipsoid([hx - 0.035, hy + 0.035, sd * zz + c * 0.018], [0.012, 0.01, 0.01], 2, P["black"])   # dewclaws
    add.ellipsoid([-0.52, 0.53, 0], [0.19, 0.12, 0.155], 6, P["pig"])           # the udder, and its four teats
    for dx in (-0.07, 0.07):
        for dz in (-0.06, 0.06):
            add.cylinder([-0.52 + dx, 0.45, dz], [-0.52 + dx * 1.1, 0.37, dz * 1.1], 0.016, 8, P["pig"])
            add.sphere([-0.52 + dx * 1.1, 0.37, dz * 1.1], 0.016, 3, P["pig"])
    add.polyline([[-0.93, 1.23, 0], [-0.975, 1.15, 0], [-0.99, 0.95, 0], [-0.985, 0.72, 0], [-0.975, 0.55, 0]],
                 ramp((0.032, 0.024, 0.019, 0.016, 0.014)), 8, P["black"] if pied else P["spire"], smooth=2)   # the tail
    add.cone([-0.975, 0.6, 0], [-0.972, 0.34, 0], 0.045, 8, P["white"] if pied else P["black"])       # and its switch
    return add.pop()


COWS = []                                                                       # (where they graze)
COW_FRAMES = []                                                                 # (how each was put there: see on_cow)


def cow(x, z, heading, kind="pied", seed=0, step=0.0):
    """A cow grazing at (x, z) on the land, her head towards ``heading``
    (an angle in XZ): sheared to the lie of the land (her legs upright), so
    that every hoof stands on it, none in it (``step``: see cow_body).
    Returns circles (x, z, r) on the ground round her, for the grass to
    keep out of (she has grazed it down and trodden it)."""
    M = add.stretch(cow_body(kind, seed, step), [LIFE] * 3, (0, 0, 0))
    ca, sa = add.cos(heading), add.sin(heading)
    world = lambda lx, lz: (x + lx * ca - lz * sa, z + lx * sa + lz * ca)
    hooves = [((hx - (step if k == 2 else 0.0)) * LIFE, hz * LIFE) for k, (hx, hz) in enumerate(COW_HOOVES)]   # (the near hind
                                                                                                              #  one set back)
    g = [land_y(*world(hx, hz)) for hx, hz in hooves]
    kx = ((g[0] + g[1]) - (g[2] + g[3])) / 2 / (hooves[0][0] - hooves[2][0])      # the slope along her and across
    kz = ((g[1] + g[3]) - (g[0] + g[2])) / 2 / (hooves[1][1] - hooves[0][1])
    y0 = sum(g) / 4 - kx * sum(h[0] for h in hooves) / 4
    y0 += max(gi - (y0 + kx * hx + kz * hz) for gi, (hx, hz) in zip(g, hooves)) + 0.002
    M = add.deform(M, lambda p: [p[0], p[1] + kx * p[0] + kz * p[2], p[2]])
    add.mesh(add.move(add.rotateY(M, -heading), [x, y0, z]))
    COW_FRAMES.append((x, z, heading, y0, kx, kz))
    mx, mz = world(1.33 * LIFE, 0.0)                                                # (her muzzle clear of the land)
    assert y0 + kx * 1.33 * LIFE + 0.05 * LIFE > land_y(mx, mz) + 0.01, (x, z)
    return [world(lx * LIFE, 0.0) + (r * LIFE,) for lx, r in ((-0.75, 0.42), (-0.25, 0.45), (0.25, 0.45), (0.75, 0.4), (1.25, 0.3))]


