def along(a, b, s):
    """The point ``s`` units from ``a`` towards ``b`` (in XZ)."""
    L, d, n = outward(a, b)
    return [a[0] + d[0] * s, 0, a[2] + d[2] * s]


WALL_GAPS = {}                                         # the middles of the embrasures along each wall, from its start
