for sz in (-1, 1):                                     # the cradle: two sleepers on the floor, on them two chocks
    add.cuboid([tx, CY + 0.07, tz + sz * 0.6], [1.7, 0.14, 0.16], P["wood_dark"])   # hollowed to the tun between its
