def to_frame(p, at, facing):
    """The world point ``p`` in the frame of a figure placed by :func:`figure` at ``at`` facing ``facing``."""
    q = add.rotateY(add.Mesh([[(p[0] - at[0]) / LIFE, (p[1] - at[1]) / LIFE, (p[2] - at[2]) / LIFE]], [], []), -facing).V[0]
    return list(q)


