# --------------------------------------------------------------------------
#  7. Upstairs: the soldiers' dormitory, and the attic full of old things
# --------------------------------------------------------------------------
# the dormitory is laid out like a real one that has grown over the years rather than in rows: bays between plank
# partitions under the windows of the long walls, each furnished its own way (bunks, beds, a sergeant's table, lockers,
# a washstand); beds against the end walls, the warmest by the chimney breast and the stove; and in the middle groups
# of their own round the attic stair and the tables -- bunks head to head behind a partition, a table for dice, a rack
# of weapons -- every piece checked clear of the walls, the towers' doors, the ways to the balconies and each other
DX0, DX1, DZ0, DZ1 = HX0, HX1, HZ0, HZ1
add.seed(17)


def screen(a, b, h=1.6, seed=0):
    """A partition of boards between two sleeping places, from ``a`` to
    ``b`` (x, z) on the dormitory floor: a post at each end, a rail along
    the foot and one along the top between them, and upright boards
    between the rails, a finger's breadth apart -- each part butting the
    next, none through another."""
    L = vlen([b[0] - a[0], 0, b[1] - a[1]])
    d = [(b[0] - a[0]) / L, 0.0, (b[1] - a[1]) / L]
    add.push()
    for u in (0.05, L - 0.05):                                                   # the posts
        add.cuboid([u, h / 2, 0], [0.1, h, 0.1], P["wood_dark"])
    for y0, y1 in ((0.06, 0.16), (h - 0.1, h)):                                  # the rails, post to post
        add.cuboid([L / 2, (y0 + y1) / 2, 0], [L - 0.2, y1 - y0, 0.08], P["wood_dark"])
    n = max(2, int((L - 0.2) / 0.24))
    for i in range(n):                                                           # the boards, rail to rail
        u0, u1 = 0.1 + (L - 0.2) * i / n + 0.004, 0.1 + (L - 0.2) * (i + 1) / n - 0.004
        add.cuboid([(u0 + u1) / 2, (0.16 + h - 0.1) / 2, 0], [u1 - u0, h - 0.26, 0.025], pick("wood", seed + i, 23))
    M = add.pop()
    add.mesh(frame_to(M, [a[0], FLOOR2, a[1]], d, [-d[2], 0.0, d[0]]))


def washstand(at, facing=0.0):
    """A washstand: a round top on three turned legs with a shelf low down,
    a basin of brass sunk in the top, a jug of water on the shelf and a
    towel over the rail."""
    x, y, z = at
    add.push()
    add.pipe([0, 0.76, 0], [0, 0.8, 0], 0.26, 0.17, k_(10), P["wood"])           # the top, a ring round the basin
    lathe([[0.0, 0.64], [0.1, 0.65], [0.155, 0.71], [0.166, 0.8], [0.215, 0.802], [0.215, 0.814], [0.2, 0.814],
           [0.152, 0.73], [0.09, 0.672], [0.0, 0.662]], [0, 0, 0], k_(10), P["steel"])    # the basin, its rim on the ring
    add.cylinder([0, 0.2, 0], [0, 0.24, 0], 0.207, k_(10), P["wood"])            # the shelf
    for i in range(3):
        a = 2 * add.pi * i / 3 + 0.5
        add.cylinder([0.232 * add.cos(a), 0.0, 0.232 * add.sin(a)], [0.232 * add.cos(a), 0.76, 0.232 * add.sin(a)], 0.022, 6,
                     P["wood_dark"])
    jug([0.02, 0.24, 0.02], P["white"], 0.3)
    M = add.pop()
    add.mesh(add.move(add.rotateY(M, facing), at))


def dorm_rect(fp, at, facing):
    """The box (x0, x1, z0, z1) on the floor of a thing whose footprint is
    ``fp`` = (x0, x1, z0, z1) in its own frame, standing on ``at`` turned
    by ``facing`` (a quarter turn at a time)."""
    c, s = round(add.cos(facing)), round(add.sin(facing))
    pts = [(at[0] + u * c + w * s, at[2] - u * s + w * c) for u in fp[:2] for w in fp[2:]]
    return (min(p[0] for p in pts), max(p[0] for p in pts), min(p[1] for p in pts), max(p[1] for p in pts))


DORM_BUSY = [(FX0, FX0 + 1.4, HALL_MID - 1.7, HALL_MID + 3.3),                  # the chimney breast and the stove
             (HOLE[0] - 0.4, HOLE[0] + 8.4, HOLE[2] - 0.3, HOLE[3] + 0.3),        # the attic stair, and room at its foot
             (FX1 - 2.7, FX1, KZ0 + 12.4, KZ0 + 15.6),                            # the door to the chapel's attic
             (FX1 - 0.7, FX1, KZ0 + 6.8, KZ0 + 9.2)]                              # the spears on the east wall
DORM_BUSY += [(bx - 1.3, bx + 1.3, FZ1 - 3.4, FZ1) for bx in BALCONY_X]           # the ways out onto the balconies,
MESS = HALL_MID + 4.0                                                            # the long tables where the men eat
DORM_BUSY += [(x - 3.25, x + 3.25, MESS - 1.4, MESS + 1.4) for x in (-12.5, 0.0, 12.5)]
for cx, cz in PALACE_TOWERS + [DON]:                                             # and to the towers' doors
    a = add.atan2((KZ0 + KZ1) / 2 - cz, (KX0 + KX1) / 2 - cx) if (cx, cz) != DON else add.pi / 4
    r = TOWER_R2 if (cx, cz) != DON else DON_R
    px, pz = cx + (r + 1.0) * add.cos(a), cz + (r + 1.0) * add.sin(a)
    DORM_BUSY.append((px - 1.5, px + 1.5, pz - 1.5, pz + 1.5))
DORM_BUSY += [(x - 0.45, x + 0.45, z - 0.23, z + 0.23) for x, z in HALL_COLS]   # the posts over the hall's columns
DORM_FIXED = len(DORM_BUSY)


def dorm_post(x, z):
    """An oak post of the dormitory, over a column of the hall: the attic
    floor's beam rests on it, and its load goes down through the floor's
    beam to the column and the ground.  A sole on the boards, the post, a
    bolster along the underside of the beam and one along the girder that
    crosses it there, and four knee braces from the post up to them -- two
    along the beam, two along the girder, a cross seen from below -- their
    ends cut square to the post and to the bolsters."""
    top = EAVE - 0.4 - 0.45 - 0.001                                            # (the beam's underside)
    y_ = FLOOR2 - TREAD + 0.001                                                # the sole, let into the floor: on the
    add.cuboid([x, (y_ + FLOOR2 + 0.1) / 2, z], [0.84, FLOOR2 + 0.1 - y_, 0.4], P["wood_dark"])   # joists, the boards round it
    add.cuboid([x, top - 0.1, z], [1.6, 0.2, 0.3], P["wood_dark"])            # the bolsters: along the beam, and
    for s in (-1, 1):                                                          # along the girder, butting against it
        add.cuboid([x, top - 0.1, z + s * 0.475], [0.3, 0.2, 0.65], P["wood_dark"])
    y0, y1 = FLOOR2 + 0.101, top - 0.201
    add.cuboid([x, (y0 + y1) / 2, z], [0.3, y1 - y0, 0.3], shade_of("wood_dark", 1))   # the post
    yb, L, c = top - 0.202, 0.55, 0.12 * add.sqrt(2)                           # the braces: at 45 degrees,
    add.push()                                                                 # 0.12 thick
    for s in (-1, 1):
        pts = [(s * u, y) for u, y in ((0.152, yb - L), (0.152 + L, yb), (0.152 + L - c, yb), (0.152, yb - L + c))]
        add.prism(pts if s > 0 else pts[::-1], 0.12, shade_of("wood_dark", 2), (0, 0, 0), (0, 0, 1))
    B = add.pop()
    add.mesh(add.move(B, [x, 0, z]))                                           # (along the beam, and the same a
    add.mesh(add.move(add.rotateY(B, add.pi / 2), [x, 0, z]))                  #  quarter turn round: along the girder)


for x, z in HALL_COLS:
    dorm_post(x, z)
FOOT = {"bed": (-0.56, 0.56, -1.1, 1.1), "bunk": (-0.56, 0.56, -1.1, 1.16), "chest": (-0.56, 0.56, -0.33, 0.33),
        "locker": (-0.5, 0.5, -0.31, 0.31), "stand": (-0.32, 0.32, -0.32, 0.32), "wash": (-0.27, 0.27, -0.27, 0.27),
        "stool": (-0.2, 0.2, -0.2, 0.2), "rack": (-2.25, 2.25, -0.45, 0.36), "arrows": (-0.36, 0.36, -0.36, 0.36)}
DORM_SLEEPERS = []


def dorm(kind, x, z, facing=0.0, **kw):
    """Put a thing of ``kind`` on the dormitory floor at (x, z), turned by
    ``facing``, if its footprint is clear of the walls, the towers and
    everything put before it (else stop: a plan that does not fit is a
    mistake); "bed" and "bunk" count the sleeping places."""
    fp = (-kw["w"] / 2, kw["w"] / 2, -kw["d"] / 2, kw["d"] / 2) if kind == "table" else \
        (-kw["w"] / 2, kw["w"] / 2, -0.16, 0.16) if kind == "bench" else FOOT[kind]
    r = dorm_rect(fp, [x, 0, z], facing)
    edge = [(r[0] + (r[1] - r[0]) * i / 6, r[2] + (r[3] - r[2]) * j / 6) for i in range(7) for j in range(7)]
    assert FX0 + 0.05 <= r[0] and r[1] <= FX1 - 0.05 and FZ0 + 0.05 <= r[2] and r[3] <= FZ1 - 0.05, (kind, x, z, r)
    assert not any(near_tower(px, pz, 0.15) for px, pz in edge), (kind, x, z)
    for k, b in enumerate(DORM_BUSY):
        assert r[1] <= b[0] or r[0] >= b[1] or r[3] <= b[2] or r[2] >= b[3], (kind, x, z, r, k, b)
    DORM_BUSY.append(r)
    at = [x, FLOOR2, z]
    if kind == "bed":
        bed(at, facing, **kw)
        DORM_SLEEPERS.append(1)
    elif kind == "bunk":
        bunk(at, facing, **kw)
        DORM_SLEEPERS.append(2)
    elif kind == "chest":
        chest(at, facing, s=0.6, **kw)
    elif kind == "locker":
        wardrobe(at, facing, w=0.9, d=0.55, h=1.85, doors=1, **kw)
    elif kind == "stand":                                                         # armour on its stand
        armour([x, FLOOR2 + 0.1, z], facing, weapon="none", shield=False, plume=False)
        add.cuboid([x, FLOOR2 + 0.05, z], [0.6, 0.1, 0.6], P["wood_dark"])
    elif kind == "wash":
        washstand(at, facing)
    elif kind == "stool":
        stool(at)
    elif kind == "rack":
        weapon_rack(at, facing)
    elif kind == "arrows":                                                        # a half barrel of arrows
        arrow_barrel(at, **kw)
    elif kind == "table":
        plank_table(at, kw["w"], kw["d"], facing=facing, seed=kw.get("seed", 0))
    elif kind == "bench":
        bench(at, kw["w"], facing)
    return r


def boots(x, z, facing=0.0):
    """A pair of old leather boots set down side by side on the floor, toes out (towards +z before ``facing``
    turns them): each on a sole of black leather with a low heel, the foot rounded and a little pointed at the
    toe, the shaft up to the middle of the calf, its top turned down in a cuff showing the paler flesh side of the
    leather, a strap round the ankle with an iron buckle on the outside; the right one standing, the left one's
    shaft slumped over outwards."""
    PH = [2 * add.pi * j / 12 for j in range(12)]
    HEEL, SOLE = 0.012, 0.011                                               # (the heel's height, the sole's thickness)
    FOOT = [(-0.106, 0.02, 0.042), (-0.1, 0.034, 0.062), (-0.09, 0.042, 0.08), (-0.075, 0.046, 0.095), (-0.05, 0.047, 0.1),
            (0.0, 0.047, 0.085), (0.05, 0.047, 0.066), (0.1, 0.045, 0.05), (0.14, 0.036, 0.036), (0.16, 0.022, 0.024),
            (0.172, 0.008, 0.013)]                                          # (z, half width, height over the sole)
    SHAFT = [(0.06, 0.042, 0.05), (0.13, 0.041, 0.049), (0.19, 0.044, 0.052), (0.25, 0.047, 0.055), (0.3, 0.049, 0.057)]
    ZC = -0.048                                                             # (the shaft stands over the heel)
    rim = [(hw + 0.004, z_) for z_, hw, h in FOOT]                          # the sole's outline, a little wider
    sole = [(0.0, -0.11)] + rim + [(0.0, 0.18)] + [(-s, z_) for s, z_ in rim[::-1]]

    def boot(slump):
        def ring(y, d):                                                     # the shaft's ring at y, ``d`` out from its
            i = max(k for k in range(len(SHAFT) - 1) if SHAFT[k][0] <= y)   # outside -- slumped over outwards above
            t = (y - SHAFT[i][0]) / (SHAFT[i + 1][0] - SHAFT[i][0])         # the strap, each ring tipped over with it
            hx, hz = [SHAFT[i][k] + (SHAFT[i + 1][k] - SHAFT[i][k]) * t for k in (1, 2)]
            u = max(0.0, (y - 0.15) / 0.15)
            c, s = add.cos(slump * 0.75 * u), add.sin(slump * 0.75 * u)
            return [[slump * 0.05 * u * u + (hx + d) * add.cos(p) * c, y - slump * 0.02 * u * u - (hx + d) * add.cos(p) * s,
                     ZC + (hz + d) * add.sin(p)] for p in PH]

        def loft(rings, colour):                                            # (a closed band of rings: a hollow solid)
            add.mesh(add.fix_normals(add.make(add.loft, rings, colour, closed=True)))
        add.push()
        add.mesh(extrude([[u, HEEL, v] for u, v in sole], [0, SOLE, 0], P["black"]))            # the sole, and under it the
        for a, lim in ((1, -0.06), (-1, -0.02)):                                                # heel and the forefoot's
            add.mesh(extrude([[0.97 * u, 0.0, v] for u, v in clip_half(sole, 0, a, lim)], [0, HEEL, 0], P["black"]))   # tread
        add.mesh(skin([[[hw * add.cos(p), HEEL + SOLE - 0.001 + h * max(0.0, add.sin(p)) ** 0.75, z_] for p in PH] for z_, hw, h in FOOT],
                      P["wood_dark"]))                                      # the foot, a hair into the sole
        R = [ring(y, 0.0) for y, hx, hz in SHAFT] + [ring(0.3, -0.006), ring(0.225, -0.006)]    # the shaft: up its outside,
        c = [sum(q[k] for q in R[-1]) / 12 for k in range(3)]                                   # over its rim and down its
        R.append([[c[0] + 0.2 * (q[0] - c[0]), c[1] - 0.005, c[2] + 0.2 * (q[2] - c[2])] for q in R[-1]])   # inside to the
        loft(R, P["wood_dark"])                                                                 # bottom
        loft([ring(0.302, 0.007), ring(0.252, 0.011), ring(0.252, -0.003), ring(0.302, -0.003)], P["wood"])   # the cuff,
        loft([ring(0.132, 0.004), ring(0.152, 0.004), ring(0.152, -0.002), ring(0.132, -0.002)], P["black"])  # the strap
        bx = ring(0.142, 0.0)[0][0] + 0.0055                                                    # and its buckle: a frame
        for (y1, z1), (y2, z2) in (((0.131, -0.011), (0.131, 0.011)), ((0.153, -0.011), (0.153, 0.011)), ((0.1295, -0.0095), (0.1545, -0.0095)),
                                   ((0.1295, 0.0095), (0.1545, 0.0095)), ((0.142, -0.0095), (0.142, 0.006))):   # and its tongue
            add.beam([bx, y1, ZC + z1], [bx, y2, ZC + z2], 0.003, 0.003, P["iron"], up=[1, 0, 0])
        return add.pop()
    add.push()
    add.mesh(add.move(add.rotateY(boot(0.0), -0.08), [0.078, 0.0, 0.0]))
    add.mesh(add.move(add.rotateY(add.mirror(boot(1.0), [0, 0, 0], [1, 0, 0]), 0.12), [-0.08, 0.0, -0.025]))
    add.mesh(add.move(add.rotateY(add.pop(), facing), [x, FLOOR2 + 0.001, z]))


