# --------------------------------------------------------------------------
#  8. Easter egg 2: the donjon inside -- the treasury with the dragon,
#     the armoury above it, the lord's chamber above that
# --------------------------------------------------------------------------
def hoard_chest(at, facing=0.0, s=1.0, seed=0):
    """The dragon's chest of gold, ``at`` the middle of its foot on the floor, its front towards +z turned by
    ``facing``, all ``s`` times the size (1.5 x 0.9, 0.68 to the brim).  On four block feet, its front and back of
    four boards laid long, its ends of upright boards, the joints tongued; bound with iron: angles down its four
    corners, two bands round it, two straps down the front and up the back to the hinges, all riveted; a lock
    plate on the front with its keyhole and the staple for the hasp, a drop handle on each end.  The lid a barrel
    top: a skirt all round and seven staves over the ends, two battens across its inside, iron over it where the
    straps come up, its hasp folded back on the skirt -- thrown back on its two strap hinges and held a little past
    upright by a chain at each end.  In it the gold: a bed heaped a little in the middle, a hand below the brim at
    the sides, and on it coins in four layers, one over another along its slope (none in another), jewels lying
    on them, a crown, a goblet standing in the gold and a string of pearls over the brim hanging down the front."""
    add.push()
    W, D, FH, HB, T, I = 1.5 * s, 0.9 * s, 0.06 * s, 0.62 * s, 0.04 * s, 0.006 * s   # (outside; feet, boards; the iron)
    RIM = FH + HB                                                                   # (the brim)
    wood = lambda i: pick("wood_dark", i, seed + 7)
    SX, SW = 0.45 * s, 0.08 * s                                                     # (the straps: where, how wide)
    AW = 0.07 * s                                                                   # (the angles' leaves)
    LOCK = (0.075 * s, RIM - 0.2 * s, RIM - 0.015 * s)                              # (the lock plate: half width, y0, y1)
    BANDS = ((FH + 0.03 * s, FH + 0.08 * s), (RIM - 0.13 * s, RIM - 0.08 * s))

    def rivet(p, n, r=0.009 * s):                                                   # a rivet's head on the face at p (normal n)
        add.cylinder(p, [p[0] + n[0] * 0.004 * s, p[1] + n[1] * 0.004 * s, p[2] + n[2] * 0.004 * s], r, 6, P["iron"])
    for sx in (-1, 1):                                                              # the feet, under the corners
        for sz in (-1, 1):
            add.cuboid([sx * (W / 2 - 0.06 * s), FH / 2, sz * (D / 2 - 0.06 * s)], [0.12 * s, FH, 0.12 * s], wood(50 + sx + 2 * sz))
    for sz in (-1, 1):                                                              # front and back: four boards laid long,
        for i in range(4):                                                          # each tongued into the one under it
            y0, y1 = FH + HB * i / 4 + (0.0015 if i else 0.0), FH + HB * (i + 1) / 4 - (0.0015 if i < 3 else 0.0)
            add.cuboid([0, (y0 + y1) / 2, sz * (D / 2 - T / 2)], [W, y1 - y0, T], wood(i + 4 * (sz > 0)))
            if i:
                add.cuboid([0, FH + HB * i / 4, sz * (D / 2 - T / 2)], [W - 0.01 * s, 0.006 * s, T / 3], wood(i + 4 * (sz > 0)))
    for sx in (-1, 1):                                                              # the ends: three upright boards between
        for i in range(3):
            z0 = -D / 2 + T + (D - 2 * T) * i / 3 + (0.0015 if i else 0.0)
            z1 = -D / 2 + T + (D - 2 * T) * (i + 1) / 3 - (0.0015 if i < 2 else 0.0)
            add.cuboid([sx * (W / 2 - T / 2), FH + HB / 2, (z0 + z1) / 2], [T, HB, z1 - z0], wood(10 + i + 3 * (sx > 0)))
            if i:
                add.cuboid([sx * (W / 2 - T / 2), FH + HB / 2, z0 - 0.0015], [T / 3, HB - 0.01 * s, 0.006 * s], wood(10 + i))
    add.cuboid([0, FH + T / 2, 0], [W - 2 * T, T, D - 2 * T], wood(20))           # the bottom, between them
    for sx in (-1, 1):                                                              # the iron: angles down the corners, both
        for sz in (-1, 1):                                                          # leaves riveted
            add.cuboid([sx * (W / 2 - AW / 2 + I / 2), FH + HB / 2, sz * (D / 2 + I / 2)], [AW + I, HB, I], P["iron"])
            add.cuboid([sx * (W / 2 + I / 2), FH + HB / 2, sz * (D / 2 - AW / 2)], [I, HB, AW], P["iron"])
            for k in range(4):
                y = FH + HB * (0.1 + 0.8 * k / 3)
                rivet([sx * (W / 2 - AW / 2), y, sz * (D / 2 + I)], [0, 0, sz])
                rivet([sx * (W / 2 + I), y, sz * (D / 2 - AW / 2)], [sx, 0, 0])
        for sz in (-1, 1):                                                          # the straps, front and back (at the back
            add.cuboid([sx * SX, FH + HB / 2, sz * (D / 2 + I / 2)], [SW, HB, I], P["iron"])   # up into the hinges' knuckles)
            for k in range(5):
                rivet([sx * SX, FH + HB * (0.08 + 0.21 * k), sz * (D / 2 + I)], [0, 0, sz])
    for y0, y1 in BANDS:                                                            # the bands round it: on the faces between
        for sz in (-1, 1):                                                          # the angles, the straps (and the lock
            cuts = [-W / 2 + AW, -SX - SW / 2, -SX + SW / 2, SX - SW / 2, SX + SW / 2, W / 2 - AW]   # plate)
            if sz > 0 and y1 > LOCK[1]:
                cuts[3:3] = [-LOCK[0], LOCK[0]]
            for a_, b_ in zip(cuts[::2], cuts[1::2]):
                add.cuboid([(a_ + b_) / 2, (y0 + y1) / 2, sz * (D / 2 + I / 2)], [b_ - a_, y1 - y0, I], P["iron"])
                for x in (a_ + 0.025 * s, b_ - 0.025 * s):
                    rivet([x, (y0 + y1) / 2, sz * (D / 2 + I)], [0, 0, sz], 0.007 * s)
        for sx in (-1, 1):
            add.cuboid([sx * (W / 2 + I / 2), (y0 + y1) / 2, 0], [I, y1 - y0, D - 2 * AW], P["iron"])
            for z in (-D / 2 + AW + 0.025 * s, 0.0, D / 2 - AW - 0.025 * s):
                rivet([sx * (W / 2 + I), (y0 + y1) / 2, z], [sx, 0, 0], 0.007 * s)
    ZF = D / 2 + 1.5 * I                                                            # the lock plate, its corners cut, and on
    q = [(-LOCK[0], LOCK[1] + 0.02 * s), (-LOCK[0] + 0.02 * s, LOCK[1]), (LOCK[0] - 0.02 * s, LOCK[1]), (LOCK[0], LOCK[1] + 0.02 * s),
         (LOCK[0], LOCK[2]), (-LOCK[0], LOCK[2])]
    add.mesh(extrude([[x, y, D / 2] for x, y in q], [0, 0, 1.5 * I], P["iron"]))
    add.cylinder([0, LOCK[1] + 0.07 * s, ZF], [0, LOCK[1] + 0.07 * s, ZF + 0.001], 0.012 * s, 8, P["black"])   # it the keyhole,
    add.cuboid([0, LOCK[1] + 0.05 * s, ZF + 0.0005], [0.008 * s, 0.03 * s, 0.001], P["black"])
    for x in (-LOCK[0] + 0.015 * s, LOCK[0] - 0.015 * s):                                                   # its rivets
        for y in (LOCK[1] + 0.03 * s, LOCK[2] - 0.02 * s):
            rivet([x, y, ZF], [0, 0, 1], 0.007 * s)
    ys = LOCK[2] - 0.05 * s                                                         # and the staple the hasp drops over
    add.polyline([[0, ys + 0.012 * s, ZF - 0.001], [0, ys + 0.012 * s, ZF + 0.018 * s], [0, ys - 0.012 * s, ZF + 0.018 * s],
                  [0, ys - 0.012 * s, ZF - 0.001]], 0.0035 * s, 6, P["iron"])
    for sx in (-1, 1):                                                              # the handles: a plate on each end with
        yh, xo = FH + 0.56 * HB, sx * (W / 2 + I)                                   # two eyes, a bail hanging down from them
        add.cuboid([sx * (W / 2 + I / 2), yh, 0], [I, 0.07 * s, 0.2 * s], P["iron"])
        for sz in (-1, 1):
            add.torus([xo + sx * 0.006 * s, yh, sz * 0.075 * s], 0.009 * s, 0.003 * s, 8, 4, P["iron"], axis=(0, 0, 1))
        bail = [[xo + sx * 0.012 * s, yh - 0.004 * s, -0.075 * s], [xo + sx * 0.012 * s, yh - 0.06 * s, -0.075 * s],
                [xo + sx * 0.012 * s, yh - 0.08 * s, -0.05 * s], [xo + sx * 0.012 * s, yh - 0.08 * s, 0.05 * s],
                [xo + sx * 0.012 * s, yh - 0.06 * s, 0.075 * s], [xo + sx * 0.012 * s, yh - 0.004 * s, 0.075 * s]]
        add.polyline(bail, 0.0055 * s, 6, P["iron"], smooth=1)
    # the lid, built closed on the brim (y from the brim), its back edge on the hinges' axis
    LS, HD, NST = 0.07 * s, 0.2 * s, 7                                              # (the skirt, the dome's rise, the staves)
    O = [(D / 2, 0.0), (D / 2, LS)] + [(D / 2 * add.sin(add.pi / 2 - add.pi * i / NST), LS + HD * add.cos(add.pi / 2 - add.pi * i / NST))
                                       for i in range(1, NST)] + [(-D / 2, LS), (-D / 2, 0.0)]   # (its outside, round from the front)

    def offset(poly, d):                                                            # (the outline ``d`` further in, mitred)
        out = []
        for k, (z, y) in enumerate(poly):
            ns = []
            for a_, b_ in ((k - 1, k), (k, k + 1)):
                if 0 <= a_ and b_ < len(poly):
                    dz, dy = poly[b_][0] - poly[a_][0], poly[b_][1] - poly[a_][1]
                    L_ = add.sqrt(dz * dz + dy * dy)
                    ns.append((-dy / L_, dz / L_))
            if len(ns) == 1:
                out.append((z + d * ns[0][0], y + d * ns[0][1]))
            else:
                m = 1.0 + ns[0][0] * ns[1][0] + ns[0][1] * ns[1][1]
                out.append((z + d * (ns[0][0] + ns[1][0]) / m, y + d * (ns[0][1] + ns[1][1]) / m))
        return out
    Iin, Iout = offset(O, T), offset(O, -I)                                         # (its inside; the iron's outside)
    Ibat = offset(O, T + 0.025 * s)                                                 # (the battens' inner edge)

    def along(sec, x0, x1, colour):                                                 # a board or a bar along x, its section
        add.mesh(extrude([[x0, y, z] for z, y in sec], [x1 - x0, 0, 0], colour))  # (z, y) points
    add.push()
    for k in range(len(O) - 1):                                                     # the skirt boards and the staves, over
        sec = [O[k], O[k + 1], Iin[k + 1], Iin[k]]                                  # the full length, a shade each
        along(sec, -W / 2, W / 2, wood(30 + k))
        for sx in (-1, 1):                                                          # the iron over it where the straps come
            along([O[k], O[k + 1], Iout[k + 1], Iout[k]], sx * SX - SW / 2, sx * SX + SW / 2, P["iron"])   # up, and round its
            along([O[k], O[k + 1], Iout[k + 1], Iout[k]], sx * (W / 2 - 0.045 * s), sx * W / 2, P["iron"])  # ends
            zm, ym = (Iout[k][0] + Iout[k + 1][0]) / 2, (Iout[k][1] + Iout[k + 1][1]) / 2
            nz, ny = zm - (O[k][0] + O[k + 1][0]) / 2, ym - (O[k][1] + O[k + 1][1]) / 2
            L_ = add.sqrt(nz * nz + ny * ny)
            rivet([sx * SX, ym, zm], [0, ny / L_, nz / L_])
            rivet([sx * (W / 2 - 0.0225 * s), ym, zm], [0, ny / L_, nz / L_], 0.007 * s)
        if 0 < k < len(O) - 2:                                                      # two battens across its inside
            for sx in (-1, 1):
                along([Iin[k], Iin[k + 1], Ibat[k + 1], Ibat[k]], sx * W / 4 - 0.03 * s, sx * W / 4 + 0.03 * s, wood(40 + k))
    for sx in (-1, 1):                                                              # its ends, shaped to the inside of the
        along(Iin, sx * (W / 2 - T / 2) - T / 2, sx * (W / 2 - T / 2) + T / 2, wood(45 + sx))   # boards
    RK = 0.013 * s                                                                  # the hinges' knuckles on the axis
    ZA = -D / 2 - RK
    for sx in (-1, 1):
        add.cylinder([sx * SX - SW / 2, 0, ZA], [sx * SX + SW / 2, 0, ZA], RK, 8, P["iron"])
    add.cylinder([-0.03 * s, 0.006 * s, D / 2 + 0.006 * s], [0.03 * s, 0.006 * s, D / 2 + 0.006 * s], 0.006 * s, 6, P["iron"])   # the
    add.cuboid([0, 0.006 * s + 0.032 * s, D / 2 + I / 2], [0.05 * s, 0.064 * s, I], P["iron"])   # hasp, folded back on the skirt,
    add.cuboid([0, 0.045 * s, D / 2 + I + 0.0005], [0.012 * s, 0.03 * s, 0.001], P["black"])      # its slot
    CZ, CY = -D / 2 + 0.2 * s, RIM - 0.03 * s                                       # (the stays: where they are made fast)
    for sx in (-1, 1):                                                              # the eyes of the chains, driven into its
        add.torus([sx * (W / 2 - T - 0.006 * s), 0.035 * s, CZ], 0.008 * s, 0.0025 * s, 8, 4, P["iron"], axis=(0, 0, 1))   # ends
    OPEN = 1.85                                                                     # (thrown back a little past upright)
    lid = add.rotateX(add.pop(), -OPEN, (0, 0, ZA))
    add.mesh(add.move(lid, [0, RIM, 0]))

    def lidpt(x, y, z):                                                             # (a point of the lid, as it lies open)
        c, sn = add.cos(OPEN), add.sin(OPEN)
        dz, dy = z - ZA, y
        return [x, RIM + dz * sn + dy * c, ZA + dz * c - dy * sn]
    for sx in (-1, 1):                                                              # the stays: a chain at each end, from an
        xc = sx * (W / 2 - T - 0.0105 * s)                                          # eye driven into the chest's end to the
        a_, b_ = [xc, CY, CZ], lidpt(xc, 0.035 * s, CZ)                             # lid's, 1 cm in from the boards
        add.torus([sx * (W / 2 - T - 0.006 * s), CY, CZ], 0.008 * s, 0.0025 * s, 8, 4, P["iron"], axis=(0, 0, 1))
        L_, u_ = vlen(vsub(b_, a_)), vunit(vsub(b_, a_))
        n_ = int(L_ / (0.0125 * s))
        ang = add.atan2(u_[2], u_[1])
        for k in range(1, n_):                                                      # (oval links, every other one turned,
            link = add.make(add.torus, [0, 0, 0], 0.006 * s, 0.002 * s, 8, 4, P["iron"], axis=(0, 0, 1) if k % 2 else (1, 0, 0))
            link = add.rotateX(add.stretch(link, [1.0, 1.5, 1.0], (0, 0, 0)), ang)  #  each through the ones either side, a
            add.mesh(add.move(link, [a_[j] + u_[j] * L_ * k / n_ for j in range(3)]))   # hair clear of them)
    # the gold: a bed heaped a little, cut to the inside of the boards, its top YC in the middle, 6 cm lower at the
    # middles of the sides; and coins on it in layers (see sea_chest), their centres clear of the boards
    XI, ZI = W / 2 - T - 0.002 * s, D / 2 - T - 0.002 * s
    YC, DROP = RIM + 0.03 * s, 0.06 * s

    def bed(x, z):                                                                  # its height and its normal at (x, z)
        return YC - DROP * ((x / XI) ** 2 + (z / ZI) ** 2), vunit([2 * DROP * x / XI ** 2, 1.0, 2 * DROP * z / ZI ** 2])
    NX, NZ = 16, 10
    G_ = add.Mesh()
    top = [[G_.add_vertex([XI * (2.0 * i / NX - 1), bed(XI * (2.0 * i / NX - 1), ZI * (2.0 * j / NZ - 1))[0], ZI * (2.0 * j / NZ - 1)])
            for j in range(NZ + 1)] for i in range(NX + 1)]
    for i in range(NX):
        for j in range(NZ):
            G_.add_face([top[i][j], top[i][j + 1], top[i + 1][j + 1], top[i + 1][j]], P["gold"])
    rim_ = [top[i][0] for i in range(NX)] + [top[NX][j] for j in range(NZ)] + [top[i][NZ] for i in range(NX, 0, -1)] + \
        [top[0][j] for j in range(NZ, 0, -1)]
    low = [G_.add_vertex([G_.V[v][0], FH + T + 0.001, G_.V[v][2]]) for v in rim_]
    for k in range(len(rim_)):
        G_.add_face([rim_[k], low[k], low[(k + 1) % len(low)], rim_[(k + 1) % len(rim_)]], P["gold"])
    G_.add_face(low[::-1], P["gold"])
    add.mesh(add.fix_normals(G_))
    RC, TC, GAP, LAY, NL = 0.045 * s, 0.008 * s, 0.004 * s, 0.011 * s, 4            # (a coin; the layers, 3 mm apart)
    X_, Z_ = XI - RC - 0.016 * s, ZI - RC - 0.016 * s                            # (their rims well clear of the boards)

    def on_bed(M, x, z, off):                                                       # (a thing made standing on y = 0, set on
        y, n = bed(x, z)                                                            #  the bed ``off`` out along its normal)
        if n[1] < 0.99999:
            M = add.rotate(M, vunit(vcross([0, 1, 0], n)), add.acos(max(-1.0, min(1.0, n[1]))))
        return add.move(M, [x + n[0] * off, y + n[1] * off, z + n[2] * off])
    coin = add.make(add.cylinder, [0, 0, 0], [0, TC, 0], RC, 10, P["gold"])
    coins, tops = [], []                                                            # (each coin's middle underneath, normal)
    for layer in range(NL):
        grid = {}
        for k in range(2400):
            x, z = X_ * (2 * hash2(k, layer, seed + 61) - 1), Z_ * (2 * hash2(k, layer, seed + 62) - 1)
            g_ = (int(x // (0.1 * s)), int(z // (0.1 * s)))
            if abs(x) > X_ - 0.07 * s and abs(z - CZ) < 0.1 * s:                    # (none by the stays' feet)
                continue
            if any((x - p_) ** 2 + (z - q_) ** 2 < (2 * RC + GAP) ** 2 for i in (-1, 0, 1) for j in (-1, 0, 1)
                   for p_, q_ in grid.get((g_[0] + i, g_[1] + j), ())):
                continue
            grid.setdefault(g_, []).append((x, z))
            off = 0.001 * s + LAY * layer
            add.mesh(on_bed(add.rotateY(coin, 6.28 * hash2(k, layer, seed + 63)), x, z, off))
            y, n = bed(x, z)
            coins.append(([x + n[0] * off, y + n[1] * off, z + n[2] * off], n))
            if layer == NL - 1:
                tops.append((x, z))

    def above(c0, n, R):                                                            # how far the coins within R of c0 come
        d = 0.0                                                                     # up over the plane through c0 square to n
        for c, m in coins:
            if (c[0] - c0[0]) ** 2 + (c[2] - c0[2]) ** 2 > (R + RC) ** 2:
                continue
            t1 = vunit(vcross(m, [0, 0, 1]))
            t2 = vcross(m, t1)
            for j in range(9):
                a_ = 2 * add.pi * j / 8
                e = [0.0, 0.0, 0.0] if j == 8 else [RC * (add.cos(a_) * t1[i] + add.sin(a_) * t2[i]) for i in range(3)]
                p = [c[i] + m[i] * TC + e[i] for i in range(3)]
                d = max(d, (p[0] - c0[0]) * n[0] + (p[1] - c0[1]) * n[1] + (p[2] - c0[2]) * n[2])
        return d

    def set_on(M, x, z, R):                                                         # (a thing standing on y = 0, R across its
        y, n = bed(x, z)                                                            #  foot, set down on the coins under it)
        return on_bed(M, x, z, above([x, y, z], n, R) + 0.0005 * s)

    def pearl_y(x, z):                                                              # (where a pearl lying at (x, z) is)
        y = bed(x, z)[0] + PR
        for c, m in coins:
            if (c[0] - x) ** 2 + (c[2] - z) ** 2 < (RC + PR) ** 2:
                y = max(y, c[1] + (TC - m[0] * (x - c[0]) - m[2] * (z - c[2])) / m[1] + PR / m[1])
        return y + 0.0005 * s
    CROWN, CUP = (-0.3 * s, -0.12 * s), (0.36 * s, -0.16 * s)                      # a crown lying on it, a goblet standing
    add.mesh(set_on(add.move(crown_kind(0.12 * s, 1), [0, 0.018 * s, 0]), CROWN[0], CROWN[1], 0.16 * s))   # in it
    add.push()
    goblet([0, 0, 0], s=1.3 * s)
    add.mesh(set_on(add.pop(), CUP[0], CUP[1], 0.06 * s))
    PR = 0.009 * s                                                                  # a string of pearls: over the gold, taut
    RB, ZB = PR + 0.001 * s, D / 2 - T / 2                                          # over the gap by the boards to the brim,
    edge = lambda x, k: [x, RIM + RB * add.cos(add.pi / 12 * k), D / 2 + RB * add.sin(add.pi / 12 * k)]   # round its edge, down

    def lying(x0, z0, x1, z1, n):                                                   # (on the coins from (x0, z0) to (x1, z1))
        pts = [(x0 + (x1 - x0) * i / n, z0 + (z1 - z0) * i / n) for i in range(n + 1)]
        return [[x, pearl_y(x, z), z] for x, z in pts]

    def taut(p, x):                                                                 # (from p on the gold to the brim)
        q = [x, RIM + RB, ZB]
        out = []
        for i in range(1, 41):
            c = [p[k] + (q[k] - p[k]) * i / 40 for k in range(3)]
            out.append([c[0], max(c[1], pearl_y(c[0], c[2])) if c[2] < D / 2 - T - PR else max(c[1], RIM + RB), c[2]])
        return out + [[x, RIM + RB, ZB + (D / 2 - ZB) * i / 10] for i in range(1, 10)]
    go, back = lying(0.1 * s, -0.12 * s, 0.2 * s, Z_, 240), lying(0.3 * s, Z_, 0.4 * s, -0.02 * s, 200)
    loop = [[0.2 * s + 0.1 * s * (1 - add.cos(add.pi * u)) / 2, RIM - 0.06 * s * add.sin(add.pi * u), D / 2 + RB]
            for u in (i / 90.0 for i in range(91))]                                 # (the loop down the front)
    path = go + taut(go[-1], 0.2 * s) + [edge(0.2 * s, k) for k in range(7)] + loop + [edge(0.3 * s, k) for k in range(6, -1, -1)] + \
        taut(back[0], 0.3 * s)[::-1][1:] + back
    beads = [path[0]]                                                               # (a pearl wherever the string has come
    for q in path[1:]:                                                              #  its width and a hair from the last
        if all(vlen(vsub(q, b_)) >= 2 * PR + 0.001 * s for b_ in beads[-4:]):     #  ones, where it steps from coin to coin)
            beads.append(q)
    for q in beads:
        add.sphere(q, PR, 4, P["white"])
    gems, placed = (P["red"], P["blue"], P["leaf"], P["purple"], P["white"]), []   # jewels lying on coins of the top layer,
    for i, (x, z) in enumerate(tops):                                               # clear of the rest
        if len(placed) >= 9 or hash2(i, seed, 71) < 0.55:
            continue
        if any((x - a_) ** 2 + (z - b_) ** 2 < 0.2 ** 2 for a_, b_ in placed + [CROWN, CUP]) or 0.05 * s < x < 0.45 * s:
            continue
        placed.append((x, z))
        r = (0.02 + 0.012 * hash2(i, seed, 73)) * s
        gem = add.make(add.octahedron, [0, 0, 0], r, gems[len(placed) % len(gems)])
        gem = add.rotate(gem, vunit([1, 0, -1]), add.acos(1 / add.sqrt(3)))       # (lying on a face)
        gem = add.move(gem, [0, r / add.sqrt(3), 0])
        add.mesh(set_on(add.rotateY(gem, 6.28 * hash2(i, seed, 74)), x, z, 0.85 * r))
    add.mesh(add.move(add.rotateY(add.pop(), facing), at))


def skeleton(at, facing=0.0):
    """What is left of the last thief: a man's skeleton, life-size, lying on
    its back on the floor (built along +x, the head that way, face up) --
    the skull resting on its back, eye sockets, the nasal opening and the
    cheekbones, rows of teeth, the lower jaw fallen a little open; the
    spine, vertebra by vertebra, the ribs curving up round from it to the
    breastbone, the collarbones; the pelvis; arms and legs, every long
    bone with its knobbed ends, the kneecaps, and the small bones of the
    hands and feet splayed out.  ``at`` is the middle of its back on the
    floor, ``facing`` the way the skull lies from there."""
    add.push()
    B_, K_ = P["bone"], P["black"]

    def long_bone(a, b, r, knob=1.8):
        """A long bone from ``a`` to ``b``: a shaft ``r`` round, knobs at the ends."""
        add.cylinder(a, b, r, 6, B_)
        for e in (a, b):
            add.ellipsoid(e, [r * knob, r * knob * 0.85, r * knob], 4, B_)

    # the skull, on the back of its head, the face up, the crown towards +x
    add.ellipsoid([0.95, 0.1, 0.0], [0.095, 0.1, 0.075], 6, B_)                    # the cranium
    add.ellipsoid([0.875, 0.145, 0.0], [0.055, 0.06, 0.06], 5, B_)                 # the face: brow to jaw,
    for sz in (-1, 1):
        add.ellipsoid([0.905, 0.195, sz * 0.031], [0.02, 0.012, 0.019], 4, K_)    # the eye sockets,
        add.ellipsoid([0.885, 0.165, sz * 0.063], [0.026, 0.02, 0.016], 4, B_)    # the cheekbones
    add.cone([0.874, 0.203, 0.0], [0.856, 0.2, 0.0], 0.011, 3, K_)               # the nasal opening
    for i in range(7):                                                            # the upper teeth on their arc
        a = (i - 3) * 0.32
        add.cuboid([0.836 + 0.012 * (1 - add.cos(a)), 0.172, 0.03 * add.sin(a)], [0.012, 0.016, 0.011], P["linen"])
    jaw = [[0.86, 0.105, -0.055], [0.815, 0.15, -0.042], [0.8, 0.158, 0.0], [0.815, 0.15, 0.042], [0.86, 0.105, 0.055]]
    add.polyline(jaw, 0.011, 6, B_, smooth=1)                                     # the lower jaw, fallen open,
    for i in range(5):                                                            # and its teeth
        a = (i - 2) * 0.35
        add.cuboid([0.812 + 0.01 * (1 - add.cos(a)), 0.166, 0.03 * add.sin(a)], [0.011, 0.014, 0.01], P["linen"])
    # the spine, from the base of the skull to the sacrum, lying on the floor; the breastbone over the ribs
    for i in range(22):
        x = 0.83 - 0.026 * i
        add.cylinder([x - 0.009, 0.026, 0.0], [x + 0.009, 0.026, 0.0], 0.019 + 0.006 * (i > 7), 6, B_)
        add.cuboid([x, 0.012, 0.0], [0.012, 0.024, 0.05], B_)                   # (each with its wings)
    add.beam([0.715, 0.226, 0.0], [0.52, 0.212, 0.0], 0.032, 0.012, B_)          # the breastbone
    for k in range(11):                                                           # the ribs, pair by pair: out from
        x = 0.72 - 0.026 * k                                                      # the spine, round and up to the
        w = 0.1 + 0.05 * add.sin(add.pi * min(1.0, (k + 2) / 9.0))                 # breastbone -- the lower ones short,
        reach = 1.0 if k < 7 else 0.75 - 0.08 * (k - 7)                           # floating
        for sz in (-1, 1):
            pts = []
            for j in range(9):
                t = j / 8.0 * reach
                th = add.pi * t
                pts.append([x - 0.05 * t, 0.03 + 0.1 * (1 - add.cos(th)) * 0.95, sz * (0.02 + w * add.sin(th) + 0.012 * t)])
            add.polyline(pts, 0.0075, 5, B_, smooth=1)
    for sz in (-1, 1):                                                            # the collarbones,
        add.polyline([[0.725, 0.22, sz * 0.02], [0.735, 0.2, sz * 0.09], [0.75, 0.16, sz * 0.165]], 0.009, 5, B_, smooth=1)
        add.ellipsoid([0.31, 0.085, sz * 0.095], [0.085, 0.065, 0.028], 5, B_)    # the hip bones,
        add.polyline([[0.25, 0.04, sz * 0.03], [0.21, 0.09, sz * 0.07], [0.2, 0.125, sz * 0.03]], 0.012, 5, B_, smooth=1)
    add.ellipsoid([0.27, 0.035, 0.0], [0.07, 0.03, 0.045], 4, B_)                 # the sacrum
    # the arms: one along the side, the other thrown out towards the gold
    sh = [[0.745, 0.12, s_ * 0.19] for s_ in (-1, 1)]
    elbows = [[0.47, 0.055, -0.25], [0.6, 0.05, 0.47]]
    wrists = [[0.22, 0.045, -0.3], [0.38, 0.04, 0.64]]
    for s_, a, e, w in zip((-1, 1), sh, elbows, wrists):
        long_bone(a, e, 0.014)                                                    # the upper arm,
        for off in (-0.012, 0.012):                                               # the two bones of the forearm,
            d = vunit(vsub(w, e))
            n = vunit(vcross(d, [0, 1, 0]))
            long_bone(_plus(e, _times(n, off)), _plus(w, _times(n, off)), 0.008, 1.6)
        d = vunit(vsub(w, e))
        n = vunit(vcross(d, [0, 1, 0]))
        for f in range(5):                                                        # the hand: five fingers' bones
            spread = (f - 2) * 0.28
            fd = vunit([d[0] * add.cos(spread) + n[0] * add.sin(spread), 0.0, d[2] * add.cos(spread) + n[2] * add.sin(spread)])
            q0 = _plus(w, _times(d, 0.03))
            L_ = 0.06 + 0.02 * (f in (1, 2, 3))
            pts = [q0, _plus(q0, _times(fd, L_ * 0.5)), _plus(q0, _times(fd, L_))]
            add.polyline([[p_[0], 0.02 + 0.006 * j, p_[2]] for j, p_ in enumerate(pts)], 0.0055, 4, B_)
    # the legs, a little apart, the feet fallen outwards
    for sz in (-1, 1):
        hip, knee, ank = [0.22, 0.065, sz * 0.095], [-0.22, 0.055, sz * 0.13], [-0.62, 0.045, sz * 0.16]
        long_bone(hip, knee, 0.017)                                               # the thigh bone,
        add.ellipsoid([-0.215, 0.1, sz * 0.13], [0.025, 0.012, 0.022], 4, B_)    # the kneecap,
        long_bone(knee, ank, 0.015)                                               # the shin bone
        long_bone([-0.24, 0.05, sz * 0.155], [-0.6, 0.04, sz * 0.18], 0.007, 1.6)   # and the fibula
        add.ellipsoid([-0.66, 0.04, sz * 0.17], [0.045, 0.028, 0.032], 4, B_)    # the heel and the ankle,
        for f in range(5):                                                        # the toes' bones, splayed
            a0 = [-0.68, 0.05, sz * (0.15 + 0.012 * f)]
            add.polyline([a0, [-0.75, 0.065, sz * (0.17 + 0.03 * f)], [-0.79, 0.075, sz * (0.18 + 0.038 * f)]], 0.006, 4, B_)
    add.mesh(add.move(add.rotateY(add.pop(), facing), at))


TR = [DON[0], G + 0.1, DON[1]]
add.seed(42)
HEAP = [TR[0] + 0.3, TR[1], TR[2] - 0.3]
HEAP_R = 2.6
add.mesh(add.move(add.stretch(add.make(add.hemisphere, [0, 0, 0], HEAP_R, 14, P["gold"]), [1.0, 0.45, 1.0], (0, 0, 0)), HEAP))


def heap_y(x, z):
    d2 = (x - HEAP[0]) ** 2 + (z - HEAP[2]) ** 2
    return HEAP[1] + (0.45 * add.sqrt(max(0.0, HEAP_R * HEAP_R - d2)) if d2 < HEAP_R * HEAP_R else 0.0)


HOARD = ([TR[0] - 2.8, TR[1], TR[2] + 2.4], 0.6)                                   # (the chest of gold: where, turned)
THIEF = ([TR[0] - 2.9, TR[1], TR[2] - 2.1], add.atan2(2.1, 3.7) + add.pi)          # (the thief's bones: the middle of his
                                                                                   #  back, the way his skull lies -- away
                                                                                   #  from the gold he reached for)


def on_thief(x, z, m=0.12):
    """Is (x, z) within ``m`` of the thief's bones (see skeleton)?"""
    dx, dz = x - THIEF[0][0], z - THIEF[0][2]
    u, v = dx * add.cos(THIEF[1]) - dz * add.sin(THIEF[1]), dx * add.sin(THIEF[1]) + dz * add.cos(THIEF[1])
    return -0.85 - m < u < 1.06 + m and abs(v) < (0.7 if u > 0.3 else 0.27) + m


for i in range(count(1500)):                                                       # coins
    a, rr = add.uniform(0, 2 * add.pi), add.uniform(0, 3.4)
    x, z = HEAP[0] + rr * add.cos(a), HEAP[2] + rr * add.sin(a)
    tilt_ = add.uniform(-0.5, 0.5)
    dx, dz = x - HOARD[0][0], z - HOARD[0][2]                                      # (none where the chest stands)
    if abs(dx * add.cos(HOARD[1]) - dz * add.sin(HOARD[1])) < 0.9 and abs(dx * add.sin(HOARD[1]) + dz * add.cos(HOARD[1])) < 0.6:
        continue
    if on_thief(x, z):                                                             # (nor under the thief's bones)
        continue
    coin = add.make(add.cylinder, [0, 0, 0], [0, 0.025, 0], 0.09, 10, P["gold"])
    coin = add.rotateX(coin, tilt_)
    add.mesh(add.move(add.rotateY(coin, a), [x, heap_y(x, z) + 0.02, z]))
for i in range(count(60)):                                                         # gems
    a, rr = add.uniform(0, 2 * add.pi), add.uniform(0, 2.4)
    x, z = HEAP[0] + rr * add.cos(a), HEAP[2] + rr * add.sin(a)
    add.sphere([x, heap_y(x, z) + 0.08, z], add.uniform(0.07, 0.14), 4, add.choice([P["red"], P["blue"], P["purple"], P["leaf"]]))
for i in range(4):
    a = 1.1 + i * 1.5
    x, z = HEAP[0] + 2.1 * add.cos(a), HEAP[2] + 2.1 * add.sin(a)
    goblet([x, heap_y(x, z), z], s=1.8)
SWORD_A = 4.5                                                                      # a knight's sword stuck in the gold at the
sx, sz = HEAP[0] + 2.1 * add.cos(SWORD_A), HEAP[2] + 2.1 * add.sin(SWORD_A)       # foot of the heap, leaning out -- a good
sword([sx, heap_y(sx, sz) - 0.12, sz], (0.22 * add.cos(SWORD_A), 1, 0.22 * add.sin(SWORD_A)),   # metre clear of the dragon on top
      (-add.sin(SWORD_A), 0, add.cos(SWORD_A)))
hoard_chest(*HOARD)                                                                # an open chest, full of gold
add.torus([TR[0] + 3.3, TR[1] + 0.06, TR[2] + 2.6], 0.35, 0.06, k_(16), 8, P["gold"])      # a crown that rolled away
skeleton(*THIEF)                                                                   # ... and the last thief
flush("treasury")


def dragon_head(fire=True):
    """The dragon's head, built looking along +x with +y up, the back of the
    skull at the origin: a long wedge of skull and snout under heavy brows,
    glowing eyes with slit pupils, a ridged nose with flared nostrils and a
    horn on it; the lower jaw dropped wide open on rows of fangs, the long
    canines top and bottom, a dark red mouth and a forked tongue; a pair of
    great horns swept back and a smaller pair under them, spikes along the
    crown, frills of spines behind the jaws; scales in two greens, a pale
    throat -- and a jet of fire out of the open jaws."""
    add.push()
    G_, D_, B_, M_ = P["dragon"], P["dragon_wing"], P["bone"], P["cushion"]

    def sgnpow(v, e):
        return abs(v) ** e * (1 if v >= 0 else -1)

    def ring(x, w, top, bot, n=20):
        """A cross-section: a rounded box ``w`` either side, from ``bot`` up to ``top``."""
        c, h = (top + bot) / 2, (top - bot) / 2
        return [[x, c + h * sgnpow(add.cos(2 * add.pi * j / n), 0.7), w * sgnpow(add.sin(2 * add.pi * j / n), 0.7)] for j in range(n)]

    def at(table, x, k):
        """Column ``k`` of a table of sections, at ``x`` (between its rows)."""
        for (x0, *a), (x1, *b) in zip(table, table[1:]):
            if x <= x1:
                t = add.clamp((x - x0) / (x1 - x0))
                return a[k - 1] + (b[k - 1] - a[k - 1]) * t
        return table[-1][k]

    def gum(table, x, f, under):
        """A point on the section of ``table`` at ``x`` (see ring): ``f`` of its
        half-width out, on its underside (``under``) or its top -- where a
        tooth is rooted, along the rim of the jaw: (y, z)."""
        w, top, bot = at(table, x, 1), at(table, x, 2), at(table, x, 3)
        c, h = (top + bot) / 2, (top - bot) / 2
        v = (1.0 - f ** (2 / 0.7)) ** 0.35
        return (c - h * v if under else c + h * v), f * w

    def scales(q, pale):
        """Two greens in patches like scales; ``pale`` parts in plates."""
        if pale(q):
            return P["dragon_belly"] if int(q[0] * 11) % 2 else P["grass_dry"]
        return D_ if hash2(int(q[0] * 16), int(q[2] * 16 + q[1] * 11 + 40), 23) < 0.3 else G_

    SKULL = [(-0.1, 0.19, 0.21, -0.17), (0.05, 0.27, 0.31, -0.19), (0.25, 0.29, 0.35, -0.15), (0.45, 0.23, 0.29, -0.06),
             (0.62, 0.17, 0.19, -0.05), (0.85, 0.15, 0.14, -0.05), (1.05, 0.14, 0.12, -0.05), (1.18, 0.13, 0.14, -0.045),
             (1.28, 0.1, 0.11, -0.04), (1.34, 0.04, 0.06, -0.03)]          # (x, half-width, top, bottom): the skull and snout
    head = add.make(add.loft, [ring(*r) for r in SKULL], G_)
    add.mesh(add.color_by(head, lambda q: M_ if q[0] > 0.45 and q[1] < -0.035 else scales(q, lambda q: q[1] < -0.1)))   # palate red,
                                                                                              # the throat pale
    for s in (-1, 1):
        brow = add.make(add.ellipsoid, [0, 0, 0], [0.25, 0.07, 0.09], 4, D_)                     # the heavy brows,
        add.mesh(add.move(add.rotateZ(brow, -0.4), [0.37, 0.3, s * 0.18]))                       # frowning over the eyes
        add.cone([0.2, 0.35, s * 0.21], [-0.02, 0.44, s * 0.29], 0.045, 6, B_)                   # a spine back from each brow
        add.ellipsoid([0.1, 0.03, s * 0.25], [0.2, 0.1, 0.07], 4, D_)                            # the cheek over the jaw
        add.ellipsoid([0.425, 0.21, s * 0.19], [0.1, 0.06, 0.04], 4, P["black"])                 # the eyes, glowing deep
        add.ellipsoid([0.435, 0.21, s * 0.205], [0.085, 0.048, 0.04], 4, P["orange"])            # in their sockets,
        add.ellipsoid([0.45, 0.21, s * 0.243], [0.01, 0.042, 0.007], 3, P["black"])              # with slit pupils
        ridge = add.make(add.ellipsoid, [0, 0, 0], [0.26, 0.03, 0.035], 4, D_)                  # the ridges of the nose,
        add.mesh(add.move(add.rotateZ(ridge, -0.05), [0.95, 0.13, s * 0.075]))
        nostril = add.make(add.ellipsoid, [0, 0, 0], [0.04, 0.022, 0.026], 4, P["black"])        # the nostrils, flared
        add.mesh(add.move(add.rotateY(nostril, s * 0.5), [1.255, 0.085, s * 0.058]))
        add.torus([1.25, 0.09, s * 0.06], 0.03, 0.012, 8, 4, D_, axis=(0.5, 0.3, s * 0.8))
        horn = [[0.02, 0.27, s * 0.15], [-0.18, 0.42, s * 0.21], [-0.4, 0.55, s * 0.27], [-0.66, 0.58, s * 0.31],
                [-0.86, 0.5, s * 0.33], [-0.97, 0.38, s * 0.33]]
        add.polyline(horn, lambda t: 0.1 * (1 - 0.93 * t), 10, B_, smooth=2)                     # the great horns,
        d0 = vunit(vsub(horn[1], horn[0]))                                                        # their roots sunk deep
        add.cylinder(_at(horn[0], d0, -0.13), _at(horn[0], d0, 0.01), 0.1, 10, B_)                # into the skull
        for j in range(4):                                                                        # ridged at the root
            c = [horn[0][k] + (horn[1][k] - horn[0][k]) * (0.3 + 0.35 * j) for k in range(3)]
            d = vunit(vsub(horn[1], horn[0]))
            add.torus(c, 0.093 - 0.009 * j, 0.013, 10, 4, P["linen"], axis=d)
        small = [[-0.02, 0.1, s * 0.22], [-0.23, 0.16, s * 0.32], [-0.45, 0.16, s * 0.4], [-0.6, 0.1, s * 0.44]]
        add.polyline(small, lambda t: 0.065 * (1 - 0.9 * t), 8, B_, smooth=2)                    # and a smaller pair, rooted
        d0 = vunit(vsub(small[1], small[0]))                                                      # the same way
        add.cylinder(_at(small[0], d0, -0.1), _at(small[0], d0, 0.01), 0.065, 8, B_)
        add.cone([0.0, -0.05, s * 0.22], [-0.17, -0.08, s * 0.32], 0.045, 6, B_)                 # a spine behind each jaw,
                                                                                                  # out of the cheek (the
                                                                                                  # frill on down the neck:
                                                                                                  # see dragon)
        for i in range(9):                                                                        # the upper teeth, fangs
            x = 0.5 + 0.09 * i                                                                   # among them, rooted in
            y, w = gum(SKULL, x, 0.72, True)                                                     # the rim of the upper
            L, r = (0.24, 0.035) if i == 6 else (0.08 + 0.03 * (i % 2), 0.024)                   # jaw's underside (their
            add.cone([x, y + 0.012, s * (w - 0.01)], [x - 0.02, y - L, s * (w - 0.025)], r, 6, B_)   # roots in it)
        add.cone([1.29, -0.035, s * 0.03], [1.28, -0.09, s * 0.03], 0.015, 5, B_)
    add.cone([1.12, 0.13, 0], [1.21, 0.27, 0], 0.035, 6, B_)                                     # the horn on the nose
    for j in range(5):                                                                            # spikes along the crown
        x = 0.52 - 0.14 * j
        y = at(SKULL, x, 2) - 0.01
        add.cone([x, y, 0], [x - 0.05, y + 0.07 + 0.025 * j, 0], 0.035 + 0.006 * j, 6, P["red"])
    add.push()                                                                                    # the lower jaw, hinged
    JAW = [(0.27, 0.2, -0.03, -0.16), (0.45, 0.17, -0.035, -0.17), (0.7, 0.14, -0.035, -0.14),        # under the eyes
           (0.95, 0.125, -0.035, -0.12), (1.12, 0.105, -0.035, -0.12), (1.22, 0.075, -0.04, -0.11), (1.28, 0.03, -0.05, -0.085)]
    jaw = add.make(add.loft, [ring(*r, n=16) for r in JAW], G_)

    def in_mouth(q):                                                                              # (the inside: the jaw's
        if q[0] <= 0.3:                                                                           #  top, between its rows of
            return False                                                                          #  teeth -- the green skin
        top, bot = at(JAW, q[0], 2), at(JAW, q[0], 3)                                             #  of its sides up to them,
        return (q[1] - (top + bot) / 2) / ((top - bot) / 2) > 0.8                                 #  all along)
    add.mesh(add.color_by(jaw, lambda q: M_ if in_mouth(q) else scales(q, lambda q: q[1] < -0.1)))
    add.ellipsoid([0.66, -0.03, 0], [0.34, 0.022, 0.07], 4, P["red"])                            # the tongue,
    for s in (-1, 1):
        add.cone([0.97, -0.028, s * 0.012], [1.1, -0.018, s * 0.065], 0.02, 5, P["red"])           # forked
        for i in range(8):                                                                        # the lower teeth, rooted
            x = 0.48 + 0.1 * i                                                                   # in the rim of the lower
            y, w = gum(JAW, x, 0.72, False)                                                      # jaw
            L, r = (0.17, 0.03) if i == 6 else (0.07 + 0.025 * (i % 2), 0.021)
            add.cone([x, y - 0.012, s * (w - 0.01)], [x + 0.015, y + L, s * (w - 0.022)], r, 6, B_)
    add.mesh(add.rotateZ(add.pop(), -0.55, (0.32, -0.08, 0)))                                     # dropped wide open
    if fire:                                                                                      # fire: a widening jet,
        mouth, end = [0.8, -0.18, 0], [1.9, -0.5, 0]                                              # a hot core, billows at
        add.cone(end, mouth, 0.27, 14, FLAME)                                                     # its end, and sparks
        add.cone([1.55, -0.4, 0], mouth, 0.11, 10, P["flame_core"])
        for i, (dx, dy, dz, r) in enumerate(((0.0, 0.0, 0.0, 0.27), (0.1, 0.08, 0.14, 0.18), (0.08, -0.07, -0.15, 0.19), (0.2, 0.04, 0.02, 0.14))):
            add.sphere([end[0] + dx, end[1] + dy, end[2] + dz], r, 8, FLAME)
        for i in range(6):
            add.sphere([1.3 + 0.11 * i, -0.28 - 0.05 * i + 0.1 * add.sin(i * 2.3), 0.17 * add.cos(i * 1.7)], 0.022, 4, P["flame_core"])
    return add.pop()


def catmull(keys, step=0.12):
    """Points along a smooth curve through the ``keys`` (a Catmull-Rom
    spline), about ``step`` apart, and for each the index of the segment
    and the fraction along it."""
    out = []
    n = len(keys)
    for i in range(n - 1):
        p0, p1, p2, p3 = keys[max(0, i - 1)], keys[i], keys[i + 1], keys[min(n - 1, i + 2)]
        m = max(2, int(vlen(vsub(p2, p1)) / step))
        for j in range(m + (1 if i == n - 2 else 0)):
            t = j / float(m)
            out.append(([0.5 * (2 * p1[k] + (p2[k] - p0[k]) * t + (2 * p0[k] - 5 * p1[k] + 4 * p2[k] - p3[k]) * t * t
                                + (3 * p1[k] - p0[k] - 3 * p2[k] + p3[k]) * t * t * t) for k in range(3)], i, t))
    return out


def dragon(at, facing=0.0, size=1.0):
    """A green dragon standing guard on the heap of gold: one smooth body
    from the head down the neck, over the back and along the tail, which
    drapes off the heap and lies curled on the floor; four legs with claws
    planted on the gold; great wings half raised, each an arm and three
    long fingers with the skin stretched between them and back to the
    flank -- clear of the body and of everything round it; a red crest from
    the crown to the tail; and the head turned to the door of the hall,
    jaws open on a jet of fire."""
    add.push()

    def ground(x, z):                                                      # the gold (or the floor) under a point
        return 0.45 * add.sqrt(max(0.0, HEAP_R * HEAP_R - (x * x + z * z) * size * size)) / size

    F = vunit([0.9, -0.3, 0.42])                                           # where the head looks: the door of the hall
    nape = [2.8, 3.85, 0.4]
    keys = [nape, [2.35, 3.55, 0.22], [2.0, 3.05, 0.1], [1.75, 2.65, 0.03], [1.3, 2.4, 0.0], [0.0, 2.3, 0.0],
            [-1.4, 2.2, 0.0], [-2.15, 1.75, -0.15], [-2.65, 1.05, -0.55], [-2.9, 0.3, -1.25], [-2.75, 0.24, -2.05],
            [-2.15, 0.19, -2.7], [-1.35, 0.14, -3.0], [-0.7, 0.07, -3.05]]
    key_r = [0.2, 0.26, 0.33, 0.42, 0.62, 0.56, 0.5, 0.42, 0.34, 0.28, 0.22, 0.17, 0.12, 0.05]
    line = catmull(keys)
    pts = [q for q, i, t in line]
    rads = [key_r[i] + (key_r[min(i + 1, len(key_r) - 1)] - key_r[i]) * t for q, i, t in line]
    body = add.make(add.polyline, pts, lambda t: rads[min(len(rads) - 1, int(round(t * (len(rads) - 1))))], k_(14), P["dragon"])

    frames = []                                                            # at each point: along, up (square to it), side
    for i in range(len(pts)):
        tan = vunit(vsub(pts[min(i + 1, len(pts) - 1)], pts[max(i - 1, 0)]))
        up = vunit([-tan[0] * tan[1], 1 - tan[1] * tan[1], -tan[2] * tan[1]])
        frames.append((tan, up, vcross(tan, up)))

    def scales(p):
        """Plates across the belly, in two shades; above, green scales, a
        few of them darker."""
        j = min(range(len(pts)), key=lambda i: (pts[i][0] - p[0]) ** 2 + (pts[i][1] - p[1]) ** 2 + (pts[i][2] - p[2]) ** 2)
        d = vsub(p, pts[j])
        tan, up, side = frames[j]
        u, v = d[0] * up[0] + d[1] * up[1] + d[2] * up[2], d[0] * side[0] + d[1] * side[1] + d[2] * side[2]
        if u < -0.4 * rads[j]:
            return P["dragon_belly"] if j % 2 else P["grass_dry"]
        a = int((add.atan2(v, u) + add.pi) / (2 * add.pi) * 14)
        return P["dragon_wing"] if hash2(j, a, 13) < 0.28 else P["dragon"]

    add.mesh(add.color_by(body, scales))
    last = 0.0                                                             # the red crest along the top, from the neck to the tail
    for i in range(2, len(pts) - 3):
        last += vlen(vsub(pts[i], pts[i - 1]))
        if last < 0.3 or 0.8 < pts[i][0] < 1.0:                          # (spaced; none between the wings' roots)
            continue
        last = 0.0
        tan, up = frames[i][0], frames[i][1]
        base = [pts[i][k] + up[k] * rads[i] * 0.85 for k in range(3)]
        h = 0.1 + 0.45 * rads[i]
        add.cone(base, [base[k] + up[k] * h - tan[k] * h * 0.3 for k in range(3)], 0.05 + 0.08 * rads[i], 6, P["red"])
    add.mesh(add.move(add.make(add.prism, [[0, 0], [0.45, -0.28], [0.45, 0.28]], 0.06, P["red"], (0, 0, 0)),
                      [pts[-1][0], pts[-1][1], pts[-1][2]]))                   # the spade at the tip of the tail
    for i in range(1, 6):                                                  # a frill of spines down either side of the
        q, (tan, up, side), r = pts[i], frames[i], rads[i]                 # neck behind the jaws, each rooted in it,
        L = 0.37 - 0.035 * i                                               # swept back along it
        for sg in (-1, 1):
            n = vunit([side[k] * sg * 0.95 - up[k] * 0.3 for k in range(3)])
            add.cone([q[k] + n[k] * r * 0.7 for k in range(3)], [q[k] + n[k] * (r + 0.7 * L) + tan[k] * L for k in range(3)],
                     0.065 - 0.005 * i, 6, P["bone"])
    U = vunit(vcross(vcross(F, [0, 1, 0]), F))                             # the head, placed on the neck
    S = vcross(F, U)
    base = [nape[k] - F[k] * 0.14 for k in range(3)]
    head = add.stretch(dragon_head(), [1.3, 1.3, 1.3], (0, 0, 0))
    add.mesh(add.transform(head, [[F[0], U[0], S[0], base[0]], [F[1], U[1], S[1], base[1]], [F[2], U[2], S[2], base[2]]]))
    for i in range(3):                                                     # a wisp of smoke from the nostrils
        add.sphere([base[k] + F[k] * (1.63 - 0.05 * i) + U[k] * (0.28 + 0.27 * i) for k in range(3)], 0.08 + 0.05 * i, 6, SMOKE)

    def claws(tip, fwd, spread):
        """Three toes ending in claws, from ``tip`` along ``fwd``."""
        side = vunit(vcross([0, 1, 0], fwd))
        for j in (-1, 0, 1):
            t0 = [tip[k] + side[k] * spread * j for k in range(3)]
            t1 = [t0[k] + fwd[k] * 0.2 + side[k] * spread * j * 0.4 for k in range(3)]
            add.capsule(t0, t1, 0.055, 8, P["dragon"])
            add.cone(t1, [t1[k] + fwd[k] * 0.17 - (0.07 if k == 1 else 0.0) for k in range(3)], 0.045, 6, P["bone"])

    for s in (-1, 1):                                                      # the legs, standing on the gold
        sh, el = [1.05, 2.1, s * 0.5], [0.85, 1.55, s * 0.72]              # front: shoulder, elbow (bent back), wrist
        wr = [1.25, ground(1.25, s * 0.72) + 0.3, s * 0.72]
        add.capsule(sh, el, 0.2, 12, P["dragon"])
        add.capsule(el, wr, 0.15, 12, P["dragon"])
        toe = [1.45, ground(1.45, s * 0.74) + 0.07, s * 0.74]
        add.capsule(wr, toe, 0.12, 12, P["dragon"])
        claws(toe, vunit([1.0, -0.15, s * 0.1]), 0.09)
        hp, kn = [-1.3, 2.1, s * 0.4], [-0.85, 1.55, s * 0.78]             # hind: hip, knee (forward), hock (back), foot
        hk = [-1.55, ground(-1.55, s * 0.78) + 0.33, s * 0.78]
        add.capsule(hp, kn, 0.26, 12, P["dragon"])
        add.capsule(kn, hk, 0.17, 12, P["dragon"])
        toe = [-1.12, ground(-1.12, s * 0.8) + 0.07, s * 0.8]
        add.capsule(hk, toe, 0.12, 12, P["dragon"])
        claws(toe, vunit([1.0, -0.1, s * 0.05]), 0.1)
        # the wing: arm and forearm up to the wrist, three fingers fanning back, the skin between them
        s0, e, w = [0.8, 2.8, s * 0.35], [0.35, 3.75, s * 1.05], [-0.25, 4.55, s * 1.9]
        tips = [[-1.25, 4.2, s * 3.0], [-1.75, 3.35, s * 2.55], [-1.95, 2.8, s * 1.75]]
        root = [-1.3, 2.45, s * 0.42]                                      # where the skin meets the flank, at the hip
        add.capsule(s0, e, 0.11, 12, P["dragon"])
        add.capsule(e, w, 0.09, 12, P["dragon"])
        add.cone(w, [w[0] + 0.28, w[1] + 0.12, w[2] + s * 0.05], 0.06, 6, P["bone"])     # the thumb claw
        for tip in tips:                                                   # (straight: the skin runs along them)
            add.polyline([w, [(w[k] + tip[k]) / 2 for k in range(3)], tip], lambda t: 0.065 - 0.04 * t, 8, P["dragon"])
        add.cone(tips[0], [tips[0][0] - 0.2, tips[0][1] - 0.08, tips[0][2] + s * 0.08], 0.035, 6, P["bone"])
        edges = [(tips[0], tips[1]), (tips[1], tips[2]), (tips[2], root), (root, s0), (s0, e)]   # (and down to the body
        on = lambda p, q, f: [p[k] + (q[k] - p[k]) * f for k in range(3)]                        # along the arm)
        for n_e, (a, b) in enumerate(edges):                               # between the fingers, the edge in a scallop;
            m = 8                                                          # the skin darkest by the wrist and thinner,
            rim = []                                                       # lighter, towards the edge, mottled, with
            for j in range(m + 1):                                         # veins running out from the wrist
                q = [a[k] + (b[k] - a[k]) * j / m for k in range(3)]
                pull = 0.2 * add.sin(add.pi * j / m) if n_e < 3 else 0.0
                rim.append([q[k] + (w[k] - q[k]) * pull for k in range(3)])
            for j in range(m):
                for i, (f0, f1) in enumerate(((0.0, 0.3), (0.3, 0.55), (0.55, 0.8), (0.8, 1.0))):
                    u = hash2(j + 9 * n_e, i + 5 * s, 17)
                    tone = min(2, max(0, i - 1 + (u > 0.82) - (u < 0.14)))
                    cell = [w] if f0 == 0.0 else [on(w, rim[j], f0)]
                    cell += [on(w, rim[j], f1), on(w, rim[j + 1], f1)] + ([] if f0 == 0.0 else [on(w, rim[j + 1], f0)])
                    sheet(cell, shade_of("dragon_wing", tone, spread=0.24), 0.02)
            for j in ((2, 4, 6) if n_e < 4 else ()):
                add.polyline([w, on(w, rim[j], 0.5), on(w, rim[j], 0.93)], lambda t: 0.03 - 0.018 * t, 6, P["dragon"])
    M = add.pop()
    M = add.stretch(M, [size, size, size], (0, 0, 0))
    add.mesh(add.move(add.rotateY(M, facing), at))


dragon([HEAP[0], HEAP[1], HEAP[2]], -0.35, 1.0)
for aa in (1.6, 2.5, 3.4, 4.0):                                             # torches on the wall, clear of the stair
    torch([TR[0] + (DON_IN - 0.05) * add.cos(aa), TR[1] + 2.6, TR[2] + (DON_IN - 0.05) * add.sin(aa)], -aa - add.pi / 2)
flush("dragon")

# the armoury on the first floor of the donjon
AY = F1
for aa in (4.1, 4.8):                                                       # racks of spears along the wall (the stair
    rack = add.make(add.cuboid, [0, 0.9, 0], [3.0, 0.12, 0.12], P["wood_dark"])   # takes the other half of the room's wall):
    rack.extend(add.make(add.cuboid, [0, 1.9, 0], [3.0, 0.12, 0.12], P["wood_dark"]))   # the knights' spears, a hair off
    for j in range(6):                                                                  # the rails
        rack.extend(add.make(spear, [-1.25 + j * 0.5, 0.0, 0.082]))
    add.mesh(add.move(add.rotateY(rack, add.pi / 2 - aa), [DON[0] + (DON_IN - 0.35) * add.cos(aa), AY, DON[1] + (DON_IN - 0.35) * add.sin(aa)]))
for aa in (5.3, 5.55, 5.8, 6.05, 6.3):                                      # the knights' shields on pegs, high (over the
    hung_shield([DON[0] + DON_IN * add.cos(aa), 0.0, DON[1] + DON_IN * add.sin(aa)], (-add.cos(aa), 0, -add.sin(aa)),   # window's
                AY + 4.0)                                                                                               # head)
for i, aa in enumerate((5.4, 5.75, 6.1)):
    x, z = DON[0] + (DON_IN - 0.6) * add.cos(aa), DON[1] + (DON_IN - 0.6) * add.sin(aa)
    armour([x, AY + 0.1, z], -aa - add.pi / 2, weapon="none", shield=(i == 1), plume=False)
    add.cuboid([x, AY + 0.05, z], [0.6, 0.1, 0.6], P["wood_dark"])
table([DON[0], AY, DON[1]], 2.4, 1.2, 0.8)
for i in range(3):                                                          # great helms on the table
    helm = add.stretch(great_helm(False), [LIFE] * 3, (0, 0, 0))
    add.mesh(add.move(add.rotateY(helm, 0.6 * i - 0.6), [DON[0] - 0.7 + i * 0.7, AY + 0.802 - 1.525 * LIFE, DON[1]]))
arrow_barrel([DON[0] + 2.0, AY, DON[1] + 2.0])                             # a half barrel of arrows, points down
def grindstone(r=0.45, w=0.14, h=0.75, colour=None):
    """A grindstone in its frame, its axle along z, the middle of the stone
    ``h`` over the ground (y = 0): the stone, ``r`` round and ``w`` thick, on
    a square iron axle, held on it by iron washers and wedges either side;
    the axle turning in bearing blocks, capped with iron, on the two side
    rails of the frame; the rails on four legs splayed out, joined by
    cross-rails at the ends and stretchers low down, and on two bearers
    between the stretchers the trough of boards the stone runs in, water
    in it; on the axle's +z end the crank, its wooden handle."""
    add.push()
    colour = colour or P["stone_dark"]
    zr = w / 2 + 0.08                                                           # (the rails' middles)
    add.cylinder([0, h, -w / 2], [0, h, w / 2], r, k_(20), colour)             # the stone,
    add.cuboid([0, h, 0.02], [0.04, 0.04, 2 * zr + 0.2], P["iron"])            # the axle,
    for sz in (-1, 1):
        add.cuboid([0, h, sz * (w / 2 + 0.006)], [0.15, 0.15, 0.012], P["iron"])   # the washers,
        for dx, dy in ((0.0, 0.035), (0.0, -0.035), (0.035, 0.0), (-0.035, 0.0)):  # the wedges
            add.cuboid([dx, h + dy, sz * (w / 2 + 0.018)], [0.012 if dx else 0.03, 0.03 if dx else 0.012, 0.012], P["wood_dark"])
        add.cuboid([0, h - 0.07, sz * zr], [2 * r + 0.4, 0.08, 0.07], P["wood_dark"])   # the rails,
        add.cuboid([0, h, sz * zr], [0.14, 0.06, 0.09], P["wood"])                     # the bearings on them
        add.cuboid([0, h + 0.035, sz * zr], [0.16, 0.01, 0.1], P["iron"])
        for sx in (-1, 1):                                                      # the legs, splayed out
            add.beam([sx * (r + 0.13), h - 0.1, sz * zr], [sx * (r + 0.23), 0.0, sz * (zr + 0.07)], 0.065, 0.065, P["wood_dark"])
        add.cuboid([0, h - r - 0.095, sz * (zr + 0.045)], [2 * r + 0.33, 0.05, 0.05], P["wood_dark"])   # the stretchers
    for sx in (-1, 1):                                                          # the cross-rails at the ends
        add.cuboid([sx * (r + 0.15), h - 0.07, 0], [0.07, 0.08, 2 * zr - 0.07], P["wood_dark"])
    d = 0.1                                                                     # the trough: the stone dips d into
    wl = h - r + d                                                              # its water
    half = add.sqrt(r * r - (r - d) ** 2) + 0.08                                # (half its length inside)
    tb, tw = h - r - 0.05, w + 0.1                                              # (its bottom inside; its width inside)
    for sx in (-1, 1):                                                          # two bearers under it
        add.cuboid([sx * (half - 0.05), tb - 0.045, 0], [0.06, 0.04, 2 * zr + 0.04], P["wood_dark"])   # (from one to the other)
    add.cuboid([0, tb - 0.0125, 0], [2 * half + 0.05, 0.025, tw + 0.05], P["wood"])   # its bottom, sides and ends
    for sz in (-1, 1):
        add.cuboid([0, (tb + wl + 0.05) / 2, sz * (tw / 2 + 0.0125)], [2 * half + 0.05, wl + 0.05 - tb, 0.025], P["wood"])
    for sx in (-1, 1):
        add.cuboid([sx * (half + 0.0125), (tb + wl + 0.05) / 2, 0], [0.025, wl + 0.05 - tb, tw], P["wood"])
    add.cuboid([0, wl - 0.005, 0], [2 * half, 0.01, tw], WATER)                # the water
    zc = zr + 0.1                                                               # the crank on the axle's end
    add.cuboid([0, h - 0.1, zc], [0.035, 0.24, 0.025], P["iron"])
    add.cylinder([0, h - 0.2, zc + 0.0125], [0, h - 0.2, zc + 0.15], 0.02, 8, P["wood"])
    return add.pop()



# a grindstone in its trough of water, turned by a crank, and a man grinding a sword on it: his right hand on the
