def turn_off(a, b):
    """How far the angle ``a`` is from ``b``, either way round."""
    return abs((a - b + add.pi) % (2 * add.pi) - add.pi)


def snap(angles, a, ok=lambda e: True, taken=()):
    """Of the embrasures at ``angles`` the one nearest the angle ``a`` that
    is ``ok`` and not ``taken``."""
    return min((e for e in angles if ok(e) and all(turn_off(e, t) > 0.05 for t in taken)), key=lambda e: turn_off(e, a))


TOP_MEN = {}                                                                                 # (where the men stand on each)
XBOW_A = []                                                                                  # every tower top has a gun (see
for k, c in enumerate(CORNERS):                                                              # "the guns on the walls"), and
    aa = snap(EMBRASURES[(c[0], c[2])], PHI[k] + (-0.7 if k % 2 else 0.7),                   # a crossbowman at an embrasure,
              lambda e: (e - (ARRIVE[k] - HEADROOM - 0.35)) % (2 * add.pi) >= HEADROOM + 0.95, (GUN_A[k],))   # on the other
    XBOW_A.append(aa)                                                                        # side of it, clear of the stairwell
    TOP_MEN.setdefault(k, []).append((c[0] + 2.3 * add.cos(aa), c[2] + 2.3 * add.sin(aa)))
    bowman([c[0] + 2.3 * add.cos(aa), TOWER_TOP, c[2] + 2.3 * add.sin(aa)], add.atan2(add.cos(aa), add.sin(aa)), "crossbow",
           pose=("aim", "load", "shoulder", "aim", "span", "load", "aim", "shoulder")[k], seed=k, aim=-0.15)
for k in (2, 3, 4, 5, 6):                                                                    # archers on the wall walk, each at an
    a, b = CORNERS[k], CORNERS[(k + 1) % 8]                                                  # embrasure between two merlons
    L, d, n = outward(a, b)
    for t in (0.3, 0.7):
        x = TOWER_R - 0.5 + min(WALL_GAPS[k], key=lambda g: abs(g - t * (L - 2 * (TOWER_R - 0.5))))
        bow = (k + int(t * 10)) % 2                                                           # (each in a pose of his own)
        bowman([a[0] + d[0] * x + n[0] * 0.25, WALK, a[2] + d[2] * x + n[2] * 0.25], add.atan2(n[0], n[2]),
               "bow" if bow else "crossbow", pose=("draw", "nock", "quiver", "rest")[k % 4] if bow else ("aim", "load", "shoulder")[k % 3],
               seed=10 + 2 * k + int(t * 2), aim=-0.1)
def _seg_dist(p1, q1, p2, q2):
    """The least distance between the segments p1-q1 and p2-q2."""
    d1, d2, r = vsub(q1, p1), vsub(q2, p2), vsub(p1, p2)
    a, e, f = _dot(d1, d1), _dot(d2, d2), _dot(d2, r)
    c = _dot(d1, r)
    b = _dot(d1, d2)
    den = a * e - b * b
    s = add.clamp((b * f - c * e) / den) if den > 1e-12 else 0.0
    t = (b * s + f) / e
    if t < 0.0:
        t, s = 0.0, add.clamp(-c / a)
    elif t > 1.0:
        t, s = 1.0, add.clamp((b - c) / a)
    return vlen(vsub(_plus(p1, _times(d1, s)), _plus(p2, _times(d2, t))))


def ammo_box(at, facing, kind, seed=0, open_side=-1):
    """A box of spare shot for the bowmen, standing on ``at`` with its long
    side the way ``facing`` turns +x: an open box of boards nailed
    together, battens on its long sides and rope handles at its ends, full
    of arrows (``kind`` "bow": forty-two, feathered, three to each, the cock
    feather red or blue) or of bolts ("crossbow": thirty-two, shorter, two
    vanes each, in a smaller box), each standing on the point of its
    steel head on the bottom and leaning over the rim of the long side
    ``open_side`` (-1: towards -z; the other is against a wall), resting on
    its edge -- in a sheaf, fanned out along the box, packed close but none
    touching the next, head or shaft or feathers."""
    add.push()
    if kind == "bow":
        L, D, H, n, length, fl, vanes, r = 0.7, 0.26, 0.26, 42, 0.74, (0.03, 0.165, 0.018), 3, 0.005
    else:
        L, D, H, n, length, fl, vanes, r = 0.58, 0.22, 0.16, 32, 0.36, (0.02, 0.1, 0.012), 2, 0.0065
    t = 0.02                                                                    # (the boards' thickness)
    wood = lambda i: shade_of("wood", i + seed)
    add.cuboid([0, t / 2, 0], [L, t, D], wood(0))                               # the bottom, the long sides on it,
    for sz in (-1, 1):                                                          # the ends between them
        add.cuboid([0, t + (H - t) / 2, sz * (D / 2 - t / 2)], [L, H - t, t], wood(1))
        add.cuboid([sz * (L / 2 - t / 2), t + (H - t) / 2, 0], [t, H - t, D - 2 * t], wood(2))
        for sx in (-1, 1):                                                      # battens on the long sides
            add.cuboid([sx * (L / 2 - 0.07), t + (H - t) / 2, sz * (D / 2 + 0.006)], [0.05, H - t - 0.02, 0.012], shade_of("wood_dark", sz))
        hy = H * 0.62                                                           # a rope handle at each end, a loop out of
        add.polyline([[sz * L / 2, hy - 0.035, 0.0], [sz * (L / 2 + 0.012), hy - 0.035, 0.0], [sz * (L / 2 + 0.027), hy - 0.024, 0.0],
                      [sz * (L / 2 + 0.031), hy, 0.0], [sz * (L / 2 + 0.027), hy + 0.024, 0.0], [sz * (L / 2 + 0.012), hy + 0.035, 0.0],
                      [sz * L / 2, hy + 0.035, 0.0]], 0.007, 6, P["rope"])   # two holes, square out of the board
    zE = open_side * (D / 2 - t)                                                # (the inner edge of the rim they lean on)
    fh = fl[2] + r                                                              # (how far the feathers reach from the axis)
    rh = 2.2 * r                                                                # (and the heads: their square points)
    ends = L / 2 - t - rh - 0.003
    deep = D - 2 * t - 2 * rh - 0.004
    backs = [0.003, 0.52, 0.26, 0.78, 0.13, 0.65, 0.39, 0.91]                   # (how far back from the rim each stands, in
    placed = []                                                                 #  turn, as a share of the box's depth)
    slots = [-ends + 2 * ends * i / (n - 1.0) for i in range(n)]
    slots += [(a_ + b_) / 2 for a_, b_ in zip(slots, slots[1:])]               # (and if they leave room, between them)
    for i, xt in enumerate(slots):                                              # one by one along the box, each leaning over
        if len(placed) == n:
            break
        for j in range(len(backs)):                                             # the rim from as far back as leaves it clear
            back = rh + 0.002 + deep * backs[(i + j) % len(backs)]              # of those before it
            tip = [xt, t + 0.0005, zE - open_side * back]                       # (its point a hair over the bottom, the
            dz, dy = zE - tip[2], H - tip[1]                                    #  shaft leaning over the rim's edge, a
            a0 = add.atan2(dy, abs(dz)) + add.asin(r / add.sqrt(dz * dz + dy * dy))   # shaft's radius above it)
            dir_ = vunit([0.008 * (hash2(i, j, 300 + seed) - 0.5), add.sin(a0), open_side * add.cos(a0)])
            nock = _plus(tip, _times(dir_, length))
            f_lo = _plus(nock, _times(dir_, -fl[1] - 0.005))
            h_up = _plus(tip, _times(dir_, 0.055))                              # (the head: from its point to its socket)
            if any(abs(p[0]) > ends + 0.001 and p[1] < H + r for p in (_plus(tip, _times(dir_, s * length / 20.0)) for s in range(21))):
                continue                                                        # (clear of the ends' boards)
            if not any(_seg_dist(tip, nock, q[0], q[1]) < 2 * r + 0.0012 or _seg_dist(tip, h_up, q[3], q[4]) < 2 * rh + 0.0012 or
                       _seg_dist(tip, h_up, q[0], q[1]) < rh + r + 0.0012 or _seg_dist(q[3], q[4], tip, nock) < rh + r + 0.0012 or
                       (vanes == 3 and (_seg_dist(f_lo, nock, q[0], q[1]) < fh + r + 0.0012 or                 # (a bolt's two vanes
                                        _seg_dist(f_lo, nock, q[2], q[1]) < 2 * fh + 0.0012))                  # lie in the plane it
                       for q in placed):                                                                  # leans in: clear of
                placed.append((tip, nock, f_lo, tip, h_up))                                               # the next)
                arrow(nock, tip, r, point=True, fletch=fl, vanes=vanes, cock=P["red"] if i % 3 else P["blue"],
                      roll=0.6 * i if vanes == 3 else add.pi / 2)
                break
    add.mesh(add.move(add.rotateY(add.pop(), facing), at))


SHOT_ROW = 10                                                                                # the guns' balls on the walk: a row
for k, end in ((0, 1), (2, 0), (3, 1), (5, 0), (6, 1), (7, 1)):                              # of ten on a board against its low
    a, b = CORNERS[k], CORNERS[(k + 1) % 8]                                                  # parapet, near the tower at one end
    L, d, n = outward(a, b)                                                                  # of the wall (the door onto the walk
    half = SHOT_ROW * (2 * CANNONBALL + 0.004) / 2 + 0.05                                    # left clear), the one away from the
    x = TOWER_R + 1.3 + half                                                                 # ladders
    x = L - x if end else x
    zc = -WALL_T / 2 + 0.15 + 0.01 + (2 * CANNONBALL + 0.004 + 0.1) / 2
    ball_pile([a[0] + d[0] * x + n[0] * zc, WALK, a[2] + d[2] * x + n[2] * zc], add.atan2(-d[2], d[0]),
              n=1, rows=SHOT_ROW, margin=0.05)
for k, kind in ((2, "bow"), (3, "crossbow"), (5, "crossbow"), (6, "bow"), (0, "bow"), (4, "crossbow"), (7, "bow")):   # and a box
    a, b = CORNERS[k], CORNERS[(k + 1) % 8]                                                  # of spare arrows or bolts on every
    L, d, n = outward(a, b)                                                                  # wall but the gate's, midway along
    zc = -WALL_T / 2 + 0.15 + 0.022 + (0.26 if kind == "bow" else 0.22) / 2                  # it (between its bowmen), against
    ammo_box([a[0] + d[0] * L / 2 + n[0] * zc, WALK, a[2] + d[2] * L / 2 + n[2] * zc], add.atan2(-d[2], d[0]), kind, seed=k)   # the low
flush("wall walk")                                                                           # parapet on the walk's inner side


def watchman(at, facing=0.0):
    """The lookout of the donjon: a man in a steel cap on a chair (its seat
    at ``at``), a spyglass to his right eye, both hands on it, keeping
    watch over the road and the lake."""
    glass, arms = spyglass(-0.83)
    M = person("sit", P["blue"], hat="steel", seat=0.48, arms=arms, lean=0.0)   # (upright, the glass at his eye)
    M.extend(glass)
    add.mesh(add.move(add.rotateY(add.stretch(M, [LIFE] * 3, (0, 0, 0)), facing), at))


lx, lz = DON[0] + 4.5 * add.cos(LOOK_A), DON[1] + 4.5 * add.sin(LOOK_A)                        # the donjon's lookout: a chair
                                                                                                # facing an embrasure to the south,
chair([lx, DON_TOP, lz], add.pi / 2 - LOOK_A, P["wood_dark"])                                  # towards the gate, the road and
watchman([lx, DON_TOP + 0.48, lz], add.pi / 2 - LOOK_A)                                        # the lake, and the watchman in it
PF = add.atan2(-DON[0], 50.0 - DON[1])                                                          # beside the king post in the middle
princess([DON[0] - 1.15 * add.cos(PF), DON_TOP, DON[1] + 1.15 * add.sin(PF)], PF)              # of the highest tower, the princess,
                                                                                                # looking out to the gate


def clear_of_stair(arrive, ang, head):
    """Is the angle ``ang`` on a tower top clear of the opening where its
    stair comes up (``head`` wide, ending at ``arrive``) and of the low
    wall round it?"""
    return (ang - (arrive - head - 0.35)) % (2 * add.pi) >= head + 0.95


def along_clear(arrive, head, t):
    """The angle a fraction ``t`` of the way round the part of a tower top
    that is clear of the stairwell."""
    a0 = arrive + 0.6
    return a0 + t * (2 * add.pi - head - 0.95)


for k, c in enumerate(CORNERS):                                     # a second man on every tower of the wall: an archer,
    ang = snap(EMBRASURES[(c[0], c[2])], along_clear(ARRIVE[k], HEADROOM, 0.96 if k % 2 else 0.12),   # at an embrasure at
               lambda e: clear_of_stair(ARRIVE[k], e, HEADROOM), (GUN_A[k], XBOW_A[k]))              # the end of the free
    TOP_MEN.setdefault(k, []).append((c[0] + 2.6 * add.cos(ang), c[2] + 2.6 * add.sin(ang)))
    bowman([c[0] + 2.6 * add.cos(ang), TOWER_TOP, c[2] + 2.6 * add.sin(ang)], add.atan2(add.cos(ang), add.sin(ang)), "bow",
           pose=("draw", "rest", "nock", "draw", "quiver", "rest", "draw", "nock")[k], seed=20 + k, aim=-0.15)
SQUARE_EMB = [k * add.pi / 2 + dd for k in range(4) for dd in (-0.507, 0.0, 0.507)]   # (a gate tower's: three a side)
tops = [((s * 7, 50), G + 20, GATE_ARRIVE[i], 1.65, SQUARE_EMB) for i, s in enumerate((-1, 1))]    # two on each gate tower
tops += [(PALACE_TOWERS[i], EAVE + 4, PT_ARRIVE[i], 2.3, EMBRASURES[PALACE_TOWERS[i]]) for i in range(len(PALACE_TOWERS))]
for i, ((cx, cz), y, arrive, radius, emb) in enumerate(tops):        # and each palace tower, at embrasures
    taken = []
    for j, t in enumerate((0.25, 0.75)):
        ang = snap(emb, along_clear(arrive, HEADROOM, t), lambda e: clear_of_stair(arrive, e, HEADROOM), taken)
        taken.append(ang)
        bowman([cx + radius * add.cos(ang), y, cz + radius * add.sin(ang)], add.atan2(add.cos(ang), add.sin(ang)),
               "bow" if (i + j) % 2 else "crossbow", pose=("draw", "nock", "rest")[(i + j) % 3] if (i + j) % 2 else
               ("aim", "shoulder", "load")[(i + 2 * j) % 3], seed=30 + 2 * i + j, aim=-0.15)
for da in (1.3, -1.3, 2.2, -2.2):                                   # and a crossbowman by the watchman on the donjon
    ang = snap(DON_EMB, LOOK_A + da)
    if clear_of_stair(DON_ARRIVE, ang, WALL_HEAD):
        bowman([DON[0] + 4.3 * add.cos(ang), DON_TOP, DON[1] + 4.3 * add.sin(ang)], add.atan2(add.cos(ang), add.sin(ang)), "crossbow",
               pose="shoulder", seed=40)
        break
def box_angle(k):
    """Where on the top of the wall's tower ``k`` a box of shot stands
    against the parapet, on the ring of flags round the lookout (outside
    its floor and the stairwell in it): between two posts of its lantern,
    well away from the gun and its gunner and clear of the men."""
    c = CORNERS[k]
    for j in range(8):
        a = j * add.pi / 4
        p = (c[0] + 4.3 * add.cos(a), c[2] + 4.3 * add.sin(a))
        if turn_off(a, GUN_A[k]) > 0.8 and all((p[0] - mx) ** 2 + (p[1] - mz) ** 2 > 1.8 ** 2 for mx, mz in TOP_MEN[k]):
            return a
    return None


for k, deg, kind in ((3, 135, "crossbow"), (5, 45, "bow"), (0, None, "bow"), (2, None, "crossbow"), (6, None, "bow"),
                     (7, None, "crossbow")):                        # and on six towers a box of them against the parapet,
    c = CORNERS[k]                                                  # clear of the men, the gun and the stair (its back a
    a = add.pi * deg / 180.0 if deg is not None else box_angle(k)   # hair off the parapet's curve at its corners)
    if a is None:
        continue
    rc = TOWER_R - 0.02 - 0.037 - (0.26 if kind == "bow" else 0.22) / 2
    ammo_box([c[0] + rc * add.cos(a), TOWER_TOP, c[2] + rc * add.sin(a)], add.atan2(-add.cos(a), -add.sin(a)), kind, seed=k + 10,
             open_side=1)                                           # (its shot leaning in, over the rim on the tower's side)
flush("the donjon's lookout, shooters on the towers")


# the guns on the walls, ready for the enemy, and their gunners -- the newest trade in the garrison.  Over the gate,
# on the roof between the gate towers, two heavy guns point out over the drawbridge through the embrasures, with a
# pile of balls and a keg of powder behind them; on every tower of the wall a lighter gun points out between two
# posts of its lantern.  By each gun its gunner, the linstock in his hand and its match alight.


GUN_Z = GATE_Z1 + 0.15 - 1.95                          # the gate's guns: their muzzles in the two embrasures, one either
for x in GATE_GAPS:                                    # side of the gate's middle line, the one gun the other's mirror
    cannon([x, GATE_ROOF, GUN_Z], -add.pi / 2, balls=False, mirror=x > 0)
gun_crew([GATE_GAPS[0], GATE_ROOF, GUN_Z], -add.pi / 2, "fire", seed=3)   # the gunners: one at the left gun, his linstock at
gunner([0.36, GATE_ROOF, GUN_Z - 1.75], 0.0, "blow", seed=8)                  # its vent, the other blowing on his match
ball_pile([-2.3, GATE_ROOF, GATE_Z0 + 0.95], n=4)
barrel([2.3, GATE_ROOF, GATE_Z0 + 0.95], 0.4, 0.95)
GUN_S = 0.75                                           # the towers' guns, lighter ones, run out on the lookout's flags
GUN_R = add.sqrt((TOWER_R - 0.05) ** 2 - (0.43 * GUN_S) ** 2) - 1.0 * GUN_S   # run out so far that a point 1.0 before
                                                       # the trunnions and 0.43 aside comes 3 cm short of the parapet: the
                                                       # muzzles in the embrasures, over their sills, as the gate's guns
                                                       # are, the wheels stopping 0.28 short of the parapet
for k, c in enumerate(CORNERS):                        # the towers' guns, the gunner beside the breech on the side of
    a, side = GUN_A[k], (-1 if k % 2 else 1)           # the crossbowman
    cannon([c[0] + GUN_R * add.cos(a), TOWER_TOP, c[2] + GUN_R * add.sin(a)], -a, balls=False, s=GUN_S, rammer="stowed")
    pose = ("ready", "watch", "sit", "blow", "carry", "ready", "sit", "watch")[k]
    gr = GUN_R - (1.25 if pose == "sit" else 0.71)                          # (one sitting, his feet clear of the post)
    gx, gz = c[0] + gr * add.cos(a) - side * 1.05 * add.sin(a), c[2] + gr * add.sin(a) + side * 1.05 * add.cos(a)
    gunner([gx, TOWER_TOP, gz], add.pi / 2 - a, pose, seed=k)
    men = TOP_MEN.get(k, []) + [(gx, gz)]                                                    # and three balls ready on a board by
    for lx, lz in ((-0.6, -side * 0.95), (-1.3, -side * 0.9), (0.1, -side * 1.0), (-0.6, side * 2.0), (-1.3, side * 2.0)):   # the
        bx_, bz_ = c[0] + (GUN_R + lx) * add.cos(a) - lz * add.sin(a), c[2] + (GUN_R + lx) * add.sin(a) + lz * add.cos(a)   # gun,
        rad = add.sqrt((bx_ - c[0]) ** 2 + (bz_ - c[2]) ** 2)                                 # clear of the men, of the posts'
        if rad + 0.42 < TOWER_R - 0.7 and rad > 0.9 and all((bx_ - mx) ** 2 + (bz_ - mz) ** 2 > 0.85 ** 2 for mx, mz in men) and \
                clear_of_stair(ARRIVE[k], add.atan2(bz_ - c[2], bx_ - c[0]), HEADROOM):       # footings and of the stairwell
            break
    ball_pile([bx_, TOWER_TOP, bz_], -a, n=1, rows=3, margin=0.05)
flush("the guns on the walls and their gunners")


